(function (A) { for (const l in A) I18N[l] = Object.assign(I18N[l] || {}, A[l]); })({"zh":{"meta.title":"终极井字棋 — 世界桌游大百科","title":"终极井字棋","sub":"Ultimate Tic-Tac-Toe","p1":"×","p2":"○","ng.first":"先手（×）","ng.second":"后手（○）","ng.level1":"先手（×）AI强度","ng.level2":"后手（○）AI强度","pcs":"小盘","hb.free":"可任意落子","hb.to":"去向：{b}","hb.var":"变体规则","rsv.won":"赢下小盘 {n}","rsv.free":"任意","rsv.title":"{c}：赢下小盘 {n}（连成三个即胜）","send.first":"×先走：任选一格落子","send.free":"可以落在任何小盘","send.to":"请落在发光的小盘（{b}）","bname":["左上","上","右上","左","中央","右","左下","下","右下"],"cant.taken":"这一格已经有子了","cant.closed":"这个小盘已经分出结果","cant.board":"请落在发光的小盘（{b}）","opt.send":"去向箭头","opt.num":"坐标","ng.rules":"规则","var.help":"查看规则","var.fc":"被送到已分胜负的小盘时","var.fc0":"可任意落子","var.fc1":"有空格就落在那里","var.tie":"平局的小盘","var.tie0":"不属于任何一方","var.tie1":"双方都算","var.cnt":"大盘没有连成三个就结束时","var.cnt0":"和棋","var.cnt1":"按小盘数定胜负","var.std":"这是现在最主流的规则（等级分对局、课程、谜题也用这个规则）。","var.custom":"这是改过规则的对局。AI会按任何规则思考，但等级分对局、课程和谜题使用主流规则。","lvd":["入门：只看眼前的三连","初级〜中级：读几步后的去向","高级：分辨小盘的争夺","最高级：深读大盘"],"lvd.top":"基准测试用：每步长时间思考的最强计算（赢了也没有奖励）","bd.title":"棋盘","bd.walnut":"胡桃木与黄铜","bd.slate":"黑板（石板）","bd.washi":"和纸与墨","bd.parchment":"旧纸与墨水","bd.marble":"大理石与金","bd.cherry":"樱桃木与黑檀","pcs.title":"×与○的记号","pcs.token":"朱漆与象牙棋子","pcs.brush":"墨与朱砂毛笔","pcs.chalk":"粉笔","pcs.ink":"钢笔与墨水","res.why.line":"在大盘上连成了三个小盘","res.why.count":"大盘没有连成三个，按赢下的小盘数决定","res.why.full":"已无处可落（大盘没有连成三个）","dr.none":"","intro.t":"终极井字棋是什么样的游戏？","intro.origin":"不详（作为纸笔游戏流传）","intro.players":"2人","intro.time":"10〜20分钟","intro.hist":"在井字棋棋盘的每一格里再画一个小井字棋的游戏。本·奥林看到数学家们在野餐时玩，2013年在博客《Math with Bad Drawings》上介绍后广为人知。","intro.win":"在小盘上连成三个就赢下这个小盘。赢下的小盘<b>在大盘上连成三个就获胜</b>。无处可落时为和棋。","intro.cult":"普通井字棋很快就会和棋，而这个游戏因为“落子位置决定对手下一步的去向”，读算非常深，也成了AI研究和编程比赛的题材。","tr.board.t":"棋盘：9个小井字棋","tr.board.b":"大盘的9个格子里各有一个3×3的<b>小盘</b>（共81格）。\n在小盘上连成三个就赢下这个小盘，盘上会画一个大记号。","tr.first.t":"第一步","tr.first.b":"×先走。只有第一步可以落在81格中的<b>任何地方</b>。","tr.first.task":"在任意一格放一个×","tr.first.ok":"放好了！接下来轮到○。","tr.send.t":"落子的格子就是“去向”","tr.send.b":"×落在中央小盘的<b>右上格</b>，所以○必须落在<b>右上的小盘</b>。\n落子格子的位置 ＝ 对手下一步的小盘。","tr.send.task":"在发光的小盘放一个○","tr.send.ok":"没错！现在○落子的位置决定×的去向。","tr.pick.t":"把对手送到哪里","tr.pick.b":"你落在哪一格，决定了<b>对手的下一个小盘</b>。\n这是这个游戏作战的核心。","tr.pick.task":"放一个把○送到<b>右上小盘</b>的×","tr.pick.ok":"○去右上的小盘。你学会选择去向了！","tr.pick.ng":"这个位置会把对手送到别的小盘。请落在发光小盘的右上格。","tr.small.t":"赢下小盘","tr.small.b":"在小盘里横、竖、斜连成三个，<b>就赢下这个小盘</b>。\n赢下的小盘不能再落子。","tr.small.task":"连成三个×赢下小盘","tr.small.ok":"赢下了小盘！","tr.small.ng":"还没有连成三个。找出两个×连着的那一行的第三格。","tr.free.t":"被送到已分胜负的小盘","tr.free.b":"如果要去的小盘已经被赢下（或下满），<b>可以落在任何还空着的小盘</b>。\n注意别把这种自由给对手。","tr.free.task":"在任意发光的小盘放一个×","tr.free.ok":"自由落子！","tr.big.t":"大盘连成三个就赢","tr.big.b":"赢下的小盘在大盘上<b>横、竖、斜连成三个就获胜</b>。","tr.big.task":"赢下这个小盘，在大盘连成三个","tr.big.ok":"大盘连成三个，×获胜！","tr.big.ng":"还没赢。去赢下能在大盘连成第三个的小盘。","tr.draw.t":"和棋","tr.draw.b":"下满了也没有连成三个的小盘<b>不属于任何一方</b>（灰色）。\n无处可落而大盘没有连成三个，就是<b>和棋</b>。","tr.vars.t":"规则的差异","tr.vars.b":"本站的标准是现在最主流的规则。在对局设置的“规则”里可以改变以下三点：\n① 被送到已分胜负的小盘：可任意落子（标准）／有空格就落在那里（最早介绍文章的规则，已被证明先手必胜）\n② 平局的小盘：不属于任何一方（标准）／双方都算\n③ 结束时大盘没有连成三个：和棋（标准）／赢下小盘多的一方获胜","ls.title":"课程","ls.desc":"为刚学会规则的人准备的“第一步”，以及为了获胜的“战术”。每一步先做准备例题，再做5题，每题20分，75分合格。","course.basics":"第一步","course.basics.sub":"用题目确认：赢下小盘、堵住、选择去向、在大盘获胜。","course.strategy":"战术","course.strategy.sub":"赢之前先看去向、自由落子的用法、读透互送直到获胜。","course.graduate":"🎉“第一步”完成！可以对局了。先和AI的Lv.1〜6下一下吧。","ls.anywhere":"可任意落子的状态","ls.ng.miss":"{x} 不能在这个小盘连成三个。","ls.ng.missBig":"{x} 不能在大盘连成三个。","ls.ng.lose":"{x} 之后，对手走 {r} 就在大盘连成三个获胜。","ls.ng.take":"{x} 会让对手去{t}小盘，对手走 {r} 赢下{tb}小盘。","ls.ng.takeFree":"{x} 把对手送到已分胜负的小盘，对手可任意落子，走 {r} 赢下{tb}小盘。","ls.ng.free":"{x} 把对手送到已分胜负的小盘，对手可以任意落子。","ls.ng.slow":"{x} 之后对手用 {r} 顽强抵抗，再走{n}步也无法在大盘连成三个。","ls.ng.ok":"{x} 也不坏，但这里有更好的一步。","ls.ng.ans":"正解是 {m}。","ls.b_take.title":"赢下小盘","ls.b_take.sub":"放第三个","ls.b_take.intro":"<p>如果小盘里你的记号已经连成两个、第三格还空着，落在那里就能赢下这个小盘。在可以落子的小盘（发光处）里找找连成两个的一行。</p>","ls.b_take.goal":"落在能赢下小盘的格子。","ls.b_take.hint":"在发光的小盘里，找你的记号连成两个的一行。","ls.b_take.why":"{m} 赢下了{b}小盘！","ls.b_take.ex.t":"两连的第三格","ls.b_take.ex.b":"发光的小盘里有你的记号连成两个的一行。落在第三格 {m} 就能赢下这个小盘。","ls.b_block.title":"堵住对手的第三格","ls.b_block.sub":"被赢之前先防守","ls.b_block.intro":"<p>如果可以落子的小盘里对手已经连成两个，堵住第三格是基本的防守。不堵的话，对手一被送到这里（或得到自由落子）就会立刻赢下它。</p>","ls.b_block.goal":"走一步守住这个小盘。","ls.b_block.hint":"在发光的小盘里，对手连成两个的是哪一行？","ls.b_block.why":"{m} 堵住了对手的第三格。对手去{t}小盘，无法立刻赢下小盘。","ls.b_block.ex.t":"堵住第三格","ls.b_block.ex.b":"对手在发光的小盘里连成了两个。堵住第三格 {m}，这个小盘暂时就不会被赢走。","ls.b_send.title":"选择去向","ls.b_send.sub":"不白送","ls.b_send.intro":"<p>落子格子的位置决定对手的下一个小盘。把对手送到他已连成两个的小盘，就会被赢下。落子前先确认送到哪个小盘才安全。</p>","ls.b_send.goal":"走一步不让对手赢下小盘。","ls.b_send.hint":"发红光的小盘里有对手的两连。哪个位置不会把对手送到那里？","ls.b_send.why":"走 {m}，对手去{t}小盘，在那里无法立刻赢下小盘。","ls.b_send.ex.t":"确认去向","ls.b_send.ex.b":"红色那步会把对手送到有他两连的小盘，马上被赢走。绿色的 {m} 则把对手送到赢不了的地方。","ls.b_big.title":"在大盘连成三个","ls.b_big.sub":"一锤定音","ls.b_big.intro":"<p>赢下的小盘在大盘上连成两个时，再赢下第三个就获胜。能赢下小盘的着法可能有好几个，但能获胜的只有大盘那一行的第三个。</p>","ls.b_big.goal":"用这一步定胜负。","ls.b_big.hint":"虚线的小盘是在大盘上再差一个就连成三个的位置。哪一步能赢下它？","ls.b_big.why":"{m} 赢下{b}小盘，在大盘连成三个。获胜！","ls.b_big.ex.t":"大盘的第三个","ls.b_big.ex.b":"赢下大盘两连那一行的第三个（虚线小盘）就获胜。{m} 就是这一步。","ls.s_look.title":"赢之前先看去向","ls.s_look.sub":"白吃的陷阱","ls.s_look.intro":"<p>即使有能赢下小盘的着法，那一格的位置也可能把对手送到好地方。也要确认赢小盘那步的去向，选不给对手机会的一步。</p>","ls.s_look.goal":"走最好的一步（赢下小盘不一定是正解）。","ls.s_look.hint":"发红光的小盘里有对手的两连。赢小盘那步会把对手送到哪里？","ls.s_look.why":"走 {m}，对手去{t}小盘，无法立刻赢下小盘。这个局面里去向比眼前的小盘更重要。","ls.s_look.ex.t":"赢了反而送过去","ls.s_look.ex.b":"红色那步能赢下小盘，却把对手送到有他两连的小盘。用绿色的 {m} 送到安全的地方才是正解。","ls.s_free.title":"自由落子的用法","ls.s_free.sub":"去大盘的关键处","ls.s_free.intro":"<p>可以任意落子是很大的机会。去大盘上任意一方差一个就连成三个的小盘（关键处）落子吧。</p>","ls.s_free.goal":"可以任意落子。走最重要的一步。","ls.s_free.hint":"虚线的小盘是大盘的关键处。在那里能做什么？","ls.s_free.why":"{m} 落在了大盘的关键处——{b}小盘。","ls.s_free.ex.t":"选择关键处","ls.s_free.ex.b":"自由落子是选择大盘关键处（虚线）的机会。{m} 就是这一步。","ls.s_force2.title":"两步获胜","ls.s_force2.sub":"读懂互送","ls.s_force2.intro":"<p>把对手送到某个小盘，让他无论落在哪里，你的下一步都能在大盘连成三个。逐一确认对手能落的格子，以及那个位置会把你送到哪里。</p>","ls.s_force2.goal":"两步之内在大盘连成三个。","ls.s_force2.hint":"找一个小盘：把对手送到那里，他的每个应手都会让你获胜。","ls.s_force2.why":"{m} 是获胜的一步：无论对手怎么应，你的下一步都能在大盘连成三个。","ls.s_force2.ex.t":"送过去再获胜","ls.s_force2.ex.b":"走绿色的 {m} 之后，对手的每个应手都会把你送到能获胜的小盘。","ls.s_force3.title":"三步获胜","ls.s_force3.sub":"终盘的强制","ls.s_force3.intro":"<p>终盘时互送决定胜负。每一步都缩小对手的选择，读透三步之内在大盘连成三个的路线。</p>","ls.s_force3.goal":"三步之内在大盘连成三个。","ls.s_force3.hint":"依次检查：能赢小盘的着法、不白送的着法、不给对手自由落子的着法。","ls.s_force3.why":"从 {m} 开始三步之内能赢。","ls.s_force3.ex.t":"三步的计算","ls.s_force3.ex.b":"从绿色的 {m} 开始，根据对手的应手把他送回去，三步在大盘连成三个。","pz.title":"终极井字棋谜题","pz.desc":"在规定步数内在大盘连成三个。对手会用最顽强的应手抵抗。所有正解都经引擎完全计算验证。","pz.winIn":"{n}步获胜","pz.goal":"{c}走：{n}步之内在大盘连成三个","pz.start":"请走第一步。","pz.best":"正解是 {b}。","pz.solvedSub":"{n}步在大盘连成了三个。","pz.hint1":"还剩{n}步。确认把对手送去的小盘里他能做什么。","pz.hintText":"有一步取胜的着法从虚线小盘开始。","pz.reply":"对手走 {m}。还剩{n}步。","pz.retry":"重来","pz.grpWin":"N步获胜","pz.grpWinSub":"面对最顽强的防守，在规定步数内在大盘连成三个。","pz.grpTac":"主题","pz.grpTacSub":"靠去向获胜・从自由落子获胜。只靠赢小盘解不开。","pz.th.w1":"1步获胜","pz.th.w1.sub":"在能赢下小盘的着法中，找出在大盘连成三个的那一步。","pz.th.w2":"2步获胜","pz.th.w2.sub":"读出对手的应手，第二步在大盘连成三个。","pz.th.w3":"3步获胜","pz.th.w3.sub":"读透对手的抵抗，3步之内获胜。","pz.th.w4":"4步获胜","pz.th.w4.sub":"漫长的互送：一边缩小对手的去向一边逼近。","pz.th.send":"靠去向获胜","pz.th.send.sub":"第一步不赢小盘：把对手送到哪里决定胜负。","pz.th.free":"从自由落子获胜","pz.th.free.sub":"可以任意落子——选出通往胜利的一步。","pz.why.last":"{m} 没有在大盘连成三个。","pz.why.took":"对手走 {r} 赢下{b}小盘，并把你送到{t}小盘。再走{n}步也赢不了。","pz.why.far":"对手用 {r} 顽强抵抗，并把你送到{t}小盘。{n}步之内大盘连不成三个。","pz.why.answer":"按“答案”可以看正解的着法。","rv.note":"恶手＝使胜负逆转或损失很大的着法。疑问手＝损失不小的着法。盘上的数字是落在该格时的评估。","cr.forced":"只能落在这一格。","cr.first":"第一步。<b>{b}</b> 是稍好一点的开局。","cr.firstOk":"第一步——不错的开局。","cr.won":"在大盘连成三个的制胜一步。","cr.best":"最佳着法。","cr.bestTake":"最佳着法，赢下了{t}小盘。","cr.good":"不坏的一步（最佳是 <b>{b}</b>，差距很小）。","cr.gen":"损害了形势的一步（{d}）。最佳是 <b>{b}</b>。","cr.missWin":"错过了胜利：<b>{b}</b> 能在大盘连成三个。","cr.allowWin":"这步之后，对手走 {r} 在大盘连成三个获胜。<b>{b}</b> 能防住。","cr.gift":"这步把对手送到{t}小盘，对手走 {r} 赢下{tb}小盘。<b>{b}</b> 不会白送。","cr.free":"这步送到已分胜负的小盘，对手可以任意落子。<b>{b}</b> 能把他限制在一个小盘里。","cr.missTake":"错过了赢下{tb}小盘的着法。最佳是 <b>{b}</b>。","cr.tookBad":"虽然赢下了小盘，但去向对对手有利。最佳是 <b>{b}</b>。","cr.tip.take":"💡 能赢的小盘很重要——但那一格的位置决定对手的去向。","cr.tip.send":"💡 落子前，看看要送去的小盘里对手有没有两连。","cr.tip.free":"💡 送到已分胜负的小盘，对手就能选最重要的小盘。","cr.tip.look":"💡 也要确认赢小盘那步的去向。有时大盘比小盘更重要。","cr.tip.gen":"💡 盘上的箭头是最佳着法，数字是落在各格时的评估。"},
"zh-TW":{"meta.title":"終極井字棋 — 世界桌遊大百科","title":"終極井字棋","sub":"Ultimate Tic-Tac-Toe","p1":"×","p2":"○","ng.first":"先手（×）","ng.second":"後手（○）","ng.level1":"先手（×）AI強度","ng.level2":"後手（○）AI強度","pcs":"小盤","hb.free":"可任意落子","hb.to":"去向：{b}","hb.var":"變體規則","rsv.won":"贏下小盤 {n}","rsv.free":"任意","rsv.title":"{c}：贏下小盤 {n}（連成三個即勝）","send.first":"×先下：任選一格落子","send.free":"可以下在任何小盤","send.to":"請下在發光的小盤（{b}）","bname":["左上","上","右上","左","中央","右","左下","下","右下"],"cant.taken":"這一格已經有子了","cant.closed":"這個小盤已經分出勝負","cant.board":"請下在發光的小盤（{b}）","opt.send":"去向箭頭","opt.num":"座標","ng.rules":"規則","var.help":"查看規則","var.fc":"被送到已分勝負的小盤時","var.fc0":"可任意落子","var.fc1":"有空格就下在那裡","var.tie":"平手的小盤","var.tie0":"不屬於任何一方","var.tie1":"雙方都算","var.cnt":"大盤沒有連成三個就結束時","var.cnt0":"和局","var.cnt1":"依小盤數決勝負","var.std":"這是目前最主流的規則（積分對局、課程、謎題也使用這個規則）。","var.custom":"這是改過規則的對局。AI 會依任何規則思考，但積分對局、課程和謎題使用主流規則。","lvd":["入門：只看眼前的三連","初級〜中級：讀幾步後的去向","高級：分辨小盤的爭奪","最高級：深讀大盤"],"lvd.top":"基準測試用：每步長時間思考的最強計算（贏了也沒有獎勵）","bd.title":"棋盤","bd.walnut":"胡桃木與黃銅","bd.slate":"黑板（石板）","bd.washi":"和紙與墨","bd.parchment":"舊紙與墨水","bd.marble":"大理石與金","bd.cherry":"櫻桃木與黑檀","pcs.title":"×與○的記號","pcs.token":"朱漆與象牙棋子","pcs.brush":"墨與朱砂毛筆","pcs.chalk":"粉筆","pcs.ink":"鋼筆與墨水","res.why.line":"在大盤上連成了三個小盤","res.why.count":"大盤沒有連成三個，依贏下的小盤數決定","res.why.full":"已無處可下（大盤沒有連成三個）","dr.none":"","intro.t":"終極井字棋是什麼樣的遊戲？","intro.origin":"不詳（作為紙筆遊戲流傳）","intro.players":"2人","intro.time":"10〜20分鐘","intro.hist":"在井字棋棋盤的每一格裡再畫一個小井字棋的遊戲。班‧奧林看到數學家們在野餐時玩，2013年在部落格《Math with Bad Drawings》介紹後廣為人知。","intro.win":"在小盤上連成三個就贏下這個小盤。贏下的小盤<b>在大盤上連成三個就獲勝</b>。無處可下時為和局。","intro.cult":"一般井字棋很快就會和局，而這個遊戲因為「落子位置決定對手下一步的去向」，計算非常深，也成了 AI 研究和程式競賽的題材。","tr.board.t":"棋盤：9個小井字棋","tr.board.b":"大盤的9個格子裡各有一個3×3的<b>小盤</b>（共81格）。\n在小盤上連成三個就贏下這個小盤，盤上會畫一個大記號。","tr.first.t":"第一步","tr.first.b":"×先下。只有第一步可以下在81格中的<b>任何地方</b>。","tr.first.task":"在任意一格放一個×","tr.first.ok":"放好了！接下來輪到○。","tr.send.t":"落子的格子就是「去向」","tr.send.b":"×下在中央小盤的<b>右上格</b>，所以○必須下在<b>右上的小盤</b>。\n落子格子的位置 ＝ 對手下一步的小盤。","tr.send.task":"在發光的小盤放一個○","tr.send.ok":"沒錯！現在○落子的位置決定×的去向。","tr.pick.t":"把對手送到哪裡","tr.pick.b":"你下在哪一格，決定了<b>對手的下一個小盤</b>。\n這是這個遊戲作戰的核心。","tr.pick.task":"放一個把○送到<b>右上小盤</b>的×","tr.pick.ok":"○去右上的小盤。你學會選擇去向了！","tr.pick.ng":"這個位置會把對手送到別的小盤。請下在發光小盤的右上格。","tr.small.t":"贏下小盤","tr.small.b":"在小盤裡橫、直、斜連成三個，<b>就贏下這個小盤</b>。\n贏下的小盤不能再落子。","tr.small.task":"連成三個×贏下小盤","tr.small.ok":"贏下了小盤！","tr.small.ng":"還沒有連成三個。找出兩個×連著的那一行的第三格。","tr.free.t":"被送到已分勝負的小盤","tr.free.b":"如果要去的小盤已經被贏下（或下滿），<b>可以下在任何還空著的小盤</b>。\n注意別把這種自由給對手。","tr.free.task":"在任意發光的小盤放一個×","tr.free.ok":"自由落子！","tr.big.t":"大盤連成三個就贏","tr.big.b":"贏下的小盤在大盤上<b>橫、直、斜連成三個就獲勝</b>。","tr.big.task":"贏下這個小盤，在大盤連成三個","tr.big.ok":"大盤連成三個，×獲勝！","tr.big.ng":"還沒贏。去贏下能在大盤連成第三個的小盤。","tr.draw.t":"和局","tr.draw.b":"下滿了也沒有連成三個的小盤<b>不屬於任何一方</b>（灰色）。\n無處可下而大盤沒有連成三個，就是<b>和局</b>。","tr.vars.t":"規則的差異","tr.vars.b":"本站的標準是目前最主流的規則。在對局設定的「規則」裡可以改變以下三點：\n① 被送到已分勝負的小盤：可任意落子（標準）／有空格就下在那裡（最早介紹文章的規則，已被證明先手必勝）\n② 平手的小盤：不屬於任何一方（標準）／雙方都算\n③ 結束時大盤沒有連成三個：和局（標準）／贏下小盤多的一方獲勝","ls.title":"課程","ls.desc":"為剛學會規則的人準備的「第一步」，以及為了獲勝的「戰術」。每一步先做準備例題，再做5題，每題20分，75分合格。","course.basics":"第一步","course.basics.sub":"用題目確認：贏下小盤、堵住、選擇去向、在大盤獲勝。","course.strategy":"戰術","course.strategy.sub":"贏之前先看去向、自由落子的用法、算清互送直到獲勝。","course.graduate":"🎉「第一步」完成！可以對局了。先和 AI 的 Lv.1〜6 下一下吧。","ls.anywhere":"可任意落子的狀態","ls.ng.miss":"{x} 無法在這個小盤連成三個。","ls.ng.missBig":"{x} 無法在大盤連成三個。","ls.ng.lose":"{x} 之後，對手下 {r} 就在大盤連成三個獲勝。","ls.ng.take":"{x} 會讓對手去{t}小盤，對手下 {r} 贏下{tb}小盤。","ls.ng.takeFree":"{x} 把對手送到已分勝負的小盤，對手可任意落子，下 {r} 贏下{tb}小盤。","ls.ng.free":"{x} 把對手送到已分勝負的小盤，對手可以任意落子。","ls.ng.slow":"{x} 之後對手用 {r} 頑強抵抗，再下{n}步也無法在大盤連成三個。","ls.ng.ok":"{x} 也不壞，但這裡有更好的一步。","ls.ng.ans":"正解是 {m}。","ls.b_take.title":"贏下小盤","ls.b_take.sub":"放第三個","ls.b_take.intro":"<p>如果小盤裡你的記號已經連成兩個、第三格還空著，下在那裡就能贏下這個小盤。在可以落子的小盤（發光處）裡找找連成兩個的一行。</p>","ls.b_take.goal":"下在能贏下小盤的格子。","ls.b_take.hint":"在發光的小盤裡，找你的記號連成兩個的一行。","ls.b_take.why":"{m} 贏下了{b}小盤！","ls.b_take.ex.t":"兩連的第三格","ls.b_take.ex.b":"發光的小盤裡有你的記號連成兩個的一行。下在第三格 {m} 就能贏下這個小盤。","ls.b_block.title":"堵住對手的第三格","ls.b_block.sub":"被贏之前先防守","ls.b_block.intro":"<p>如果可以落子的小盤裡對手已經連成兩個，堵住第三格是基本的防守。不堵的話，對手一被送到這裡（或得到自由落子）就會立刻贏下它。</p>","ls.b_block.goal":"下一步守住這個小盤。","ls.b_block.hint":"在發光的小盤裡，對手連成兩個的是哪一行？","ls.b_block.why":"{m} 堵住了對手的第三格。對手去{t}小盤，無法立刻贏下小盤。","ls.b_block.ex.t":"堵住第三格","ls.b_block.ex.b":"對手在發光的小盤裡連成了兩個。堵住第三格 {m}，這個小盤暫時就不會被贏走。","ls.b_send.title":"選擇去向","ls.b_send.sub":"不白送","ls.b_send.intro":"<p>落子格子的位置決定對手的下一個小盤。把對手送到他已連成兩個的小盤，就會被贏下。落子前先確認送到哪個小盤才安全。</p>","ls.b_send.goal":"下一步不讓對手贏下小盤。","ls.b_send.hint":"發紅光的小盤裡有對手的兩連。哪個位置不會把對手送到那裡？","ls.b_send.why":"下 {m}，對手去{t}小盤，在那裡無法立刻贏下小盤。","ls.b_send.ex.t":"確認去向","ls.b_send.ex.b":"紅色那步會把對手送到有他兩連的小盤，馬上被贏走。綠色的 {m} 則把對手送到贏不了的地方。","ls.b_big.title":"在大盤連成三個","ls.b_big.sub":"一舉定勝負","ls.b_big.intro":"<p>贏下的小盤在大盤上連成兩個時，再贏下第三個就獲勝。能贏下小盤的著法可能有好幾個，但能獲勝的只有大盤那一行的第三個。</p>","ls.b_big.goal":"用這一步定勝負。","ls.b_big.hint":"虛線的小盤是在大盤上再差一個就連成三個的位置。哪一步能贏下它？","ls.b_big.why":"{m} 贏下{b}小盤，在大盤連成三個。獲勝！","ls.b_big.ex.t":"大盤的第三個","ls.b_big.ex.b":"贏下大盤兩連那一行的第三個（虛線小盤）就獲勝。{m} 就是這一步。","ls.s_look.title":"贏之前先看去向","ls.s_look.sub":"白吃的陷阱","ls.s_look.intro":"<p>即使有能贏下小盤的著法，那一格的位置也可能把對手送到好地方。也要確認贏小盤那步的去向，選不給對手機會的一步。</p>","ls.s_look.goal":"下最好的一步（贏下小盤不一定是正解）。","ls.s_look.hint":"發紅光的小盤裡有對手的兩連。贏小盤那步會把對手送到哪裡？","ls.s_look.why":"下 {m}，對手去{t}小盤，無法立刻贏下小盤。這個局面裡去向比眼前的小盤更重要。","ls.s_look.ex.t":"贏了反而送過去","ls.s_look.ex.b":"紅色那步能贏下小盤，卻把對手送到有他兩連的小盤。用綠色的 {m} 送到安全的地方才是正解。","ls.s_free.title":"自由落子的用法","ls.s_free.sub":"去大盤的關鍵處","ls.s_free.intro":"<p>可以任意落子是很大的機會。去大盤上任一方差一個就連成三個的小盤（關鍵處）落子吧。</p>","ls.s_free.goal":"可以任意落子。下最重要的一步。","ls.s_free.hint":"虛線的小盤是大盤的關鍵處。在那裡能做什麼？","ls.s_free.why":"{m} 下在了大盤的關鍵處——{b}小盤。","ls.s_free.ex.t":"選擇關鍵處","ls.s_free.ex.b":"自由落子是選擇大盤關鍵處（虛線）的機會。{m} 就是這一步。","ls.s_force2.title":"兩步獲勝","ls.s_force2.sub":"看懂互送","ls.s_force2.intro":"<p>把對手送到某個小盤，讓他無論下在哪裡，你的下一步都能在大盤連成三個。逐一確認對手能下的格子，以及那個位置會把你送到哪裡。</p>","ls.s_force2.goal":"兩步之內在大盤連成三個。","ls.s_force2.hint":"找一個小盤：把對手送到那裡，他的每個應手都會讓你獲勝。","ls.s_force2.why":"{m} 是獲勝的一步：無論對手怎麼應，你的下一步都能在大盤連成三個。","ls.s_force2.ex.t":"送過去再獲勝","ls.s_force2.ex.b":"下綠色的 {m} 之後，對手的每個應手都會把你送到能獲勝的小盤。","ls.s_force3.title":"三步獲勝","ls.s_force3.sub":"終盤的強制","ls.s_force3.intro":"<p>終盤時互送決定勝負。每一步都縮小對手的選擇，算清三步之內在大盤連成三個的路線。</p>","ls.s_force3.goal":"三步之內在大盤連成三個。","ls.s_force3.hint":"依序檢查：能贏小盤的著法、不白送的著法、不給對手自由落子的著法。","ls.s_force3.why":"從 {m} 開始三步之內能贏。","ls.s_force3.ex.t":"三步的計算","ls.s_force3.ex.b":"從綠色的 {m} 開始，依對手的應手把他送回去，三步在大盤連成三個。","pz.title":"終極井字棋謎題","pz.desc":"在規定步數內在大盤連成三個。對手會用最頑強的應手抵抗。所有正解都經引擎完全計算驗證。","pz.winIn":"{n}步獲勝","pz.goal":"{c}下：{n}步之內在大盤連成三個","pz.start":"請下第一步。","pz.best":"正解是 {b}。","pz.solvedSub":"{n}步在大盤連成了三個。","pz.hint1":"還剩{n}步。確認把對手送去的小盤裡他能做什麼。","pz.hintText":"有一步取勝的著法從虛線小盤開始。","pz.reply":"對手下 {m}。還剩{n}步。","pz.retry":"重來","pz.grpWin":"N步獲勝","pz.grpWinSub":"面對最頑強的防守，在規定步數內在大盤連成三個。","pz.grpTac":"主題","pz.grpTacSub":"靠去向獲勝・從自由落子獲勝。只靠贏小盤解不開。","pz.th.w1":"1步獲勝","pz.th.w1.sub":"在能贏下小盤的著法中，找出在大盤連成三個的那一步。","pz.th.w2":"2步獲勝","pz.th.w2.sub":"看出對手的應手，第二步在大盤連成三個。","pz.th.w3":"3步獲勝","pz.th.w3.sub":"算清對手的抵抗，3步之內獲勝。","pz.th.w4":"4步獲勝","pz.th.w4.sub":"漫長的互送：一邊縮小對手的去向一邊逼近。","pz.th.send":"靠去向獲勝","pz.th.send.sub":"第一步不贏小盤：把對手送到哪裡決定勝負。","pz.th.free":"從自由落子獲勝","pz.th.free.sub":"可以任意落子——選出通往勝利的一步。","pz.why.last":"{m} 沒有在大盤連成三個。","pz.why.took":"對手下 {r} 贏下{b}小盤，並把你送到{t}小盤。再下{n}步也贏不了。","pz.why.far":"對手用 {r} 頑強抵抗，並把你送到{t}小盤。{n}步之內大盤連不成三個。","pz.why.answer":"按「答案」可以看正解的著法。","rv.note":"惡手＝使勝負逆轉或損失很大的著法。疑問手＝損失不小的著法。盤上的數字是下在該格時的評估。","cr.forced":"只能下在這一格。","cr.first":"第一步。<b>{b}</b> 是稍好一點的開局。","cr.firstOk":"第一步——不錯的開局。","cr.won":"在大盤連成三個的致勝一步。","cr.best":"最佳著法。","cr.bestTake":"最佳著法，贏下了{t}小盤。","cr.good":"不壞的一步（最佳是 <b>{b}</b>，差距很小）。","cr.gen":"損害了形勢的一步（{d}）。最佳是 <b>{b}</b>。","cr.missWin":"錯過了勝利：<b>{b}</b> 能在大盤連成三個。","cr.allowWin":"這步之後，對手下 {r} 在大盤連成三個獲勝。<b>{b}</b> 能防住。","cr.gift":"這步把對手送到{t}小盤，對手下 {r} 贏下{tb}小盤。<b>{b}</b> 不會白送。","cr.free":"這步送到已分勝負的小盤，對手可以任意落子。<b>{b}</b> 能把他限制在一個小盤裡。","cr.missTake":"錯過了贏下{tb}小盤的著法。最佳是 <b>{b}</b>。","cr.tookBad":"雖然贏下了小盤，但去向對對手有利。最佳是 <b>{b}</b>。","cr.tip.take":"💡 能贏的小盤很重要——但那一格的位置決定對手的去向。","cr.tip.send":"💡 落子前，看看要送去的小盤裡對手有沒有兩連。","cr.tip.free":"💡 送到已分勝負的小盤，對手就能選最重要的小盤。","cr.tip.look":"💡 也要確認贏小盤那步的去向。有時大盤比小盤更重要。","cr.tip.gen":"💡 盤上的箭頭是最佳著法，數字是下在各格時的評估。"},
"ko":{"meta.title":"얼티밋 틱택토 — 세계 보드게임 대백과","title":"얼티밋 틱택토","sub":"Ultimate Tic-Tac-Toe","p1":"×","p2":"○","ng.first":"선수 (×)","ng.second":"후수 (○)","ng.level1":"선수 (×) AI 강도","ng.level2":"후수 (○) AI 강도","pcs":"작은 판","hb.free":"아무 데나 둘 수 있음","hb.to":"보낼 곳: {b}","hb.var":"변형 규칙","rsv.won":"딴 작은 판 {n}","rsv.free":"자유","rsv.title":"{c}: 딴 작은 판 {n} (셋을 이으면 승리)","send.first":"× 차례: 아무 칸에나 두세요","send.free":"어느 작은 판에나 둘 수 있어요","send.to":"빛나는 작은 판({b})에 두세요","bname":["왼쪽 위","위","오른쪽 위","왼쪽","가운데","오른쪽","왼쪽 아래","아래","오른쪽 아래"],"cant.taken":"그 칸은 이미 차 있어요","cant.closed":"그 작은 판은 이미 승부가 났어요","cant.board":"빛나는 작은 판({b})에 두세요","opt.send":"보낼 곳 화살표","opt.num":"좌표","ng.rules":"규칙","var.help":"규칙 보기","var.fc":"승부가 난 작은 판으로 보내지면","var.fc0":"아무 데나 둔다","var.fc1":"빈칸이 있으면 거기에","var.tie":"비긴 작은 판은","var.tie0":"누구의 것도 아님","var.tie1":"양쪽 모두의 것","var.cnt":"큰 판에 셋이 이어지지 않고 끝나면","var.cnt0":"무승부","var.cnt1":"작은 판 수로 결정","var.std":"지금 가장 널리 쓰이는 규칙입니다(레이팅전·레슨·퍼즐도 이 규칙).","var.custom":"규칙을 바꾼 대국입니다. AI는 어떤 규칙이든 생각하지만, 레이팅전·레슨·퍼즐은 기본 규칙으로 합니다.","lvd":["입문: 눈앞의 세 줄만 본다","초급~중급: 몇 수 뒤 보낼 곳까지 읽는다","상급: 작은 판 쟁탈을 가려 읽는다","최상급: 큰 판까지 깊이 읽는다"],"lvd.top":"벤치마크용: 한 수에 오래 생각하는 최강의 수읽기(이겨도 보상 없음)","bd.title":"판","bd.walnut":"월넛과 황동","bd.slate":"칠판(석판)","bd.washi":"화지와 먹","bd.parchment":"낡은 종이와 잉크","bd.marble":"대리석과 금","bd.cherry":"벚나무와 흑단","pcs.title":"×와 ○ 표시","pcs.token":"주칠과 상아 말","pcs.brush":"먹과 주홍 붓","pcs.chalk":"분필","pcs.ink":"펜과 잉크","res.why.line":"큰 판에 작은 판 셋을 이었습니다","res.why.count":"큰 판에 셋이 이어지지 않아 딴 작은 판 수로 정해졌습니다","res.why.full":"둘 곳이 없어졌습니다(큰 판에 셋이 이어지지 않음)","dr.none":"","intro.t":"얼티밋 틱택토는 어떤 게임?","intro.origin":"알 수 없음(종이와 펜 놀이로 퍼짐)","intro.players":"2명","intro.time":"10~20분","intro.hist":"틱택토 판의 각 칸에 작은 틱택토를 하나씩 더 그린 놀이. 수학자들이 소풍에서 하던 것을 본 벤 올린이 2013년 블로그 「Math with Bad Drawings」에 소개하면서 널리 알려졌습니다.","intro.win":"작은 판에서 셋을 이으면 그 작은 판을 땁니다. 딴 작은 판을 <b>큰 판에서 셋 이으면 승리</b>. 둘 곳이 없으면 무승부입니다.","intro.cult":"보통 틱택토는 금방 비기지만, 이 게임은 「둔 칸이 상대의 다음 행선지를 정한다」는 규칙 덕분에 수읽기가 아주 깊어 AI 연구와 프로그래밍 대회의 소재가 되기도 합니다.","tr.board.t":"판: 아홉 개의 작은 틱택토","tr.board.b":"큰 판의 9칸마다 3×3 <b>작은 판</b>이 있습니다(모두 81칸).\n작은 판에서 셋을 이으면 그 작은 판을 따고 큰 표시가 붙습니다.","tr.first.t":"첫 수","tr.first.b":"×가 먼저 둡니다. 첫 수만은 81칸 <b>어디에 두어도 됩니다</b>.","tr.first.task":"아무 칸에나 ×를 두자","tr.first.ok":"두었어요! 이제 ○ 차례입니다.","tr.send.t":"둔 칸이 「보낼 곳」","tr.send.b":"×가 가운데 작은 판의 <b>오른쪽 위 칸</b>에 두었으므로 ○는 <b>오른쪽 위 작은 판</b>에 두어야 합니다.\n둔 칸의 위치 = 상대가 다음에 둘 작은 판입니다.","tr.send.task":"빛나는 작은 판에 ○를 두자","tr.send.ok":"맞아요! 이번엔 ○가 둔 위치가 ×의 행선지가 됩니다.","tr.pick.t":"상대를 어디로 보낼까","tr.pick.b":"어느 칸에 두느냐로 <b>상대의 다음 작은 판</b>이 정해집니다.\n이것이 이 게임 작전의 핵심입니다.","tr.pick.task":"○를 <b>오른쪽 위 작은 판</b>으로 보내는 ×를 두자","tr.pick.ok":"○는 오른쪽 위 작은 판으로. 보낼 곳을 고를 수 있게 됐어요!","tr.pick.ng":"그 위치는 다른 작은 판으로 보냅니다. 빛나는 작은 판의 오른쪽 위 칸에 두자.","tr.small.t":"작은 판 따기","tr.small.b":"작은 판에서 가로·세로·대각선으로 셋을 이으면 <b>그 작은 판을 땁니다</b>.\n딴 작은 판에는 더 이상 아무도 둘 수 없습니다.","tr.small.task":"×를 셋 이어 작은 판을 따자","tr.small.ok":"작은 판을 땄어요!","tr.small.ng":"아직 셋이 이어지지 않았어요. 두 개 이어진 ×의 다음 칸을 찾자.","tr.free.t":"승부가 난 작은 판으로 보내지면","tr.free.b":"보내진 작은 판이 이미 따였거나(또는 꽉 찼으면) <b>아직 빈 어느 작은 판에나 둘 수 있습니다</b>.\n상대에게 이 자유를 주지 않도록 조심하자.","tr.free.task":"빛나는 작은 판 아무 곳에나 ×를 두자","tr.free.ok":"자유롭게 두었어요!","tr.big.t":"큰 판에서 셋을 이으면 승리","tr.big.b":"딴 작은 판을 큰 판에서 <b>가로·세로·대각선으로 셋 이으면 승리</b>입니다.","tr.big.task":"이 작은 판을 따서 큰 판에 셋을 잇자","tr.big.ok":"큰 판에 셋이 이어졌어요. ×의 승리!","tr.big.ng":"아직 이기지 못했어요. 큰 판에서 세 번째가 되는 작은 판을 따자.","tr.draw.t":"무승부","tr.draw.b":"다 채워져도 셋이 이어지지 않은 작은 판은 <b>누구의 것도 아닙니다</b>(회색).\n둘 곳이 없는데 큰 판에 셋이 이어지지 않았다면 <b>무승부</b>입니다.","tr.vars.t":"규칙의 차이","tr.vars.b":"이 사이트의 기본은 지금 가장 널리 쓰이는 규칙입니다. 대국 설정의 「규칙」에서 다음 세 가지를 바꿀 수 있습니다.\n① 승부가 난 작은 판으로 보내지면: 아무 데나 둔다(기본) / 빈칸이 있으면 거기에(처음 소개된 글의 규칙. 선수 필승이 증명됨)\n② 비긴 작은 판: 누구의 것도 아님(기본) / 양쪽 모두의 것\n③ 큰 판에 셋이 이어지지 않고 끝나면: 무승부(기본) / 딴 작은 판이 많은 쪽의 승리","ls.title":"레슨","ls.desc":"규칙을 막 익힌 분을 위한 「첫걸음」과 이기기 위한 「작전」. 각 단계는 준비 예제 후 5문제, 문제당 20점, 75점이면 합격입니다.","course.basics":"첫걸음","course.basics.sub":"작은 판 따기·막기·보낼 곳 고르기·큰 판에서 이기기를 문제로 확인합니다.","course.strategy":"작전","course.strategy.sub":"따기 전에 보낼 곳, 자유로운 차례 쓰는 법, 주고받기를 끝까지 읽기.","course.graduate":"🎉 「첫걸음」 수료! 이제 대국할 수 있어요. 먼저 AI Lv.1~6과 둬 보세요.","ls.anywhere":"아무 데나 둘 수 있는 상태","ls.ng.miss":"{x}로는 이 작은 판에 셋이 이어지지 않습니다.","ls.ng.missBig":"{x}로는 큰 판에 셋이 이어지지 않습니다.","ls.ng.lose":"{x} 다음에 상대는 {r}로 큰 판에 셋을 이어 이깁니다.","ls.ng.take":"{x}면 상대는 {t} 작은 판으로 가서 {r}로 {tb} 작은 판을 땁니다.","ls.ng.takeFree":"{x}는 승부가 난 작은 판으로 보내므로 상대는 아무 데나 둘 수 있고, {r}로 {tb} 작은 판을 땁니다.","ls.ng.free":"{x}는 승부가 난 작은 판으로 보내므로 상대는 아무 데나 둘 수 있습니다.","ls.ng.slow":"{x} 다음에 상대는 {r}로 버티고, 남은 {n}수로는 큰 판에 셋을 이을 수 없습니다.","ls.ng.ok":"{x}도 나쁘진 않지만 여기서는 더 좋은 수가 있습니다.","ls.ng.ans":"정답은 {m}.","ls.b_take.title":"작은 판 따기","ls.b_take.sub":"세 번째를 둔다","ls.b_take.intro":"<p>작은 판에서 내 표시가 둘 이어져 있고 세 번째 칸이 비어 있으면, 거기에 두어 그 작은 판을 딸 수 있습니다. 둘 수 있는 작은 판(빛나는 곳)에서 둘 이어진 줄을 찾아봅시다.</p>","ls.b_take.goal":"작은 판을 딸 수 있는 칸에 두자.","ls.b_take.hint":"빛나는 작은 판에서 내 표시가 둘 이어진 줄을 찾자.","ls.b_take.why":"{m}로 {b} 작은 판을 땄어요!","ls.b_take.ex.t":"두 개 이은 줄의 세 번째","ls.b_take.ex.b":"빛나는 작은 판에는 내 표시가 둘 이어진 줄이 있습니다. 세 번째 칸 {m}에 두면 이 작은 판을 딸 수 있습니다.","ls.b_block.title":"상대의 세 번째 막기","ls.b_block.sub":"따이기 전에 지킨다","ls.b_block.intro":"<p>둘 수 있는 작은 판에서 상대가 둘을 이었다면 세 번째 칸을 막는 것이 기본 수비입니다. 막지 않으면 상대가 이 작은 판으로 보내질 때(또는 자유로운 차례에) 바로 따입니다.</p>","ls.b_block.goal":"이 작은 판을 지키는 수를 두자.","ls.b_block.hint":"빛나는 작은 판에서 상대 표시가 둘 이어진 줄은 어디?","ls.b_block.why":"{m}로 상대의 세 번째 칸을 막았어요. 상대는 {t} 작은 판으로 가며 바로 작은 판을 딸 수 없습니다.","ls.b_block.ex.t":"세 번째를 막는다","ls.b_block.ex.b":"빛나는 작은 판에서 상대가 둘을 이었습니다. 세 번째 칸 {m}를 막으면 이 작은 판은 당장은 따이지 않습니다.","ls.b_send.title":"보낼 곳 고르기","ls.b_send.sub":"공짜로 주지 않기","ls.b_send.intro":"<p>두는 칸의 위치로 상대의 다음 작은 판이 정해집니다. 상대가 둘을 이은 작은 판으로 보내면 그곳을 따입니다. 어느 작은 판으로 보내야 안전한지 두기 전에 확인합시다.</p>","ls.b_send.goal":"상대에게 작은 판을 주지 않는 수를 두자.","ls.b_send.hint":"붉게 빛나는 작은 판에는 상대의 두 줄이 있습니다. 그곳으로 보내지 않는 위치는?","ls.b_send.why":"{m}면 상대는 {t} 작은 판으로. 그곳에서는 바로 작은 판을 딸 수 없습니다.","ls.b_send.ex.t":"보낼 곳 확인","ls.b_send.ex.b":"빨간 수는 상대를 두 줄이 있는 작은 판으로 보내 바로 따입니다. 초록 {m}이면 상대는 딸 수 없는 곳으로 갑니다.","ls.b_big.title":"큰 판에서 셋 잇기","ls.b_big.sub":"승부를 결정","ls.b_big.intro":"<p>딴 작은 판이 큰 판에서 둘 이어졌다면 세 번째 작은 판을 따면 승리입니다. 작은 판을 따는 수는 여럿이어도 이기는 것은 큰 판 줄의 세 번째뿐.</p>","ls.b_big.goal":"이 한 수로 승부를 내자.","ls.b_big.hint":"점선 작은 판은 큰 판에서 하나만 더 있으면 셋이 이어지는 곳입니다. 그곳을 따는 수는?","ls.b_big.why":"{m}로 {b} 작은 판을 따서 큰 판에 셋이 이어졌어요. 승리!","ls.b_big.ex.t":"큰 판의 세 번째","ls.b_big.ex.b":"큰 판에서 둘 이어진 줄의 세 번째(점선 작은 판)를 따면 승리. {m}이 그 한 수입니다.","ls.s_look.title":"따기 전에 보낼 곳","ls.s_look.sub":"공짜 따기의 함정","ls.s_look.intro":"<p>작은 판을 딸 수 있는 수라도 그 칸의 위치가 상대를 좋은 작은 판으로 보낼 수 있습니다. 따는 수의 보낼 곳도 확인하고 상대에게 주지 않는 수를 고릅시다.</p>","ls.s_look.goal":"가장 좋은 수를 두자(작은 판을 따는 수가 정답이라고는 할 수 없습니다).","ls.s_look.hint":"붉게 빛나는 작은 판에는 상대의 두 줄이 있습니다. 따는 수는 상대를 어디로 보낼까?","ls.s_look.why":"{m}면 상대는 {t} 작은 판으로 가서 바로 작은 판을 딸 수 없습니다. 눈앞의 작은 판보다 보낼 곳이 중요한 국면이었습니다.","ls.s_look.ex.t":"따면 보내 버린다","ls.s_look.ex.b":"빨간 수는 작은 판을 따지만 상대를 두 줄이 있는 작은 판으로 보냅니다. 초록 {m}으로 안전한 곳에 보내는 것이 정답입니다.","ls.s_free.title":"자유로운 차례 쓰는 법","ls.s_free.sub":"큰 판의 승부처로","ls.s_free.intro":"<p>아무 데나 둘 수 있는 차례는 큰 기회. 큰 판에서 어느 한쪽이 하나만 더 있으면 셋이 이어지는 작은 판(승부처)에 둡시다.</p>","ls.s_free.goal":"아무 데나 둘 수 있어요. 가장 중요한 한 수를 두자.","ls.s_free.hint":"점선 작은 판이 큰 판의 승부처입니다. 거기서 무엇을 할 수 있을까?","ls.s_free.why":"{m}로 큰 판의 승부처인 {b} 작은 판에 두었습니다.","ls.s_free.ex.t":"승부처를 고른다","ls.s_free.ex.b":"자유로운 차례는 큰 판의 승부처(점선)를 고를 기회. {m}이 그 한 수입니다.","ls.s_force2.title":"2수로 이기기","ls.s_force2.sub":"주고받기를 읽는다","ls.s_force2.intro":"<p>상대를 어떤 작은 판으로 보내, 상대가 어디에 두든 나의 다음 수로 큰 판에 셋이 이어지게 만듭니다. 상대가 둘 수 있는 칸과 그 위치가 나를 어디로 보내는지 모두 확인합시다.</p>","ls.s_force2.goal":"2수 안에 큰 판에 셋을 잇자.","ls.s_force2.hint":"상대를 보냈을 때 상대의 모든 응수가 나의 승리로 이어지는 작은 판을 찾자.","ls.s_force2.why":"{m}이 승리의 한 수. 상대가 어떻게 받아도 다음 수로 큰 판에 셋이 이어집니다.","ls.s_force2.ex.t":"보내서 이긴다","ls.s_force2.ex.b":"초록 {m}로 보내면 상대의 응수는 모두 나를 이길 수 있는 작은 판으로 되돌려 보냅니다.","ls.s_force3.title":"3수로 이기기","ls.s_force3.sub":"종반의 강제","ls.s_force3.intro":"<p>종반에는 주고받기가 승부를 가릅니다. 한 수마다 상대의 선택을 좁히며 3수 안에 큰 판에 셋을 잇는 길을 끝까지 읽읍시다.</p>","ls.s_force3.goal":"3수 안에 큰 판에 셋을 잇자.","ls.s_force3.hint":"작은 판을 따는 수, 아무것도 주지 않는 수, 자유로운 차례를 주지 않는 수를 차례로 살피자.","ls.s_force3.why":"{m}부터 3수 안에 이길 수 있습니다.","ls.s_force3.ex.t":"3수의 수읽기","ls.s_force3.ex.b":"초록 {m}부터 상대의 응수에 맞춰 되돌려 보내며 3수 만에 큰 판에 셋을 잇습니다.","pz.title":"얼티밋 틱택토 퍼즐","pz.desc":"정해진 수 안에 큰 판에 셋을 이으세요. 상대는 가장 끈질긴 응수로 버팁니다. 모든 정답은 엔진으로 완전히 읽어 확인했습니다.","pz.winIn":"{n}수로 이겨라","pz.goal":"{c} 차례: {n}수 안에 큰 판에 셋을 잇자","pz.start":"첫 수를 두세요.","pz.best":"정답은 {b}였습니다.","pz.solvedSub":"{n}수 만에 큰 판에 셋을 이었습니다.","pz.hint1":"{n}수 남음. 상대를 보내는 작은 판에서 상대가 무엇을 할 수 있는지 확인하자.","pz.hintText":"점선 작은 판에서 시작하는 이기는 수가 있습니다.","pz.reply":"상대는 {m}. {n}수 남음.","pz.retry":"다시","pz.grpWin":"N수로 이겨라","pz.grpWinSub":"상대가 최선으로 버텨도 정해진 수 안에 큰 판에 셋을 잇자.","pz.grpTac":"테마","pz.grpTacSub":"보낼 곳으로 이기기·자유로운 차례에서 이기기. 작은 판만 따서는 풀리지 않는 문제입니다.","pz.th.w1":"1수로 이겨라","pz.th.w1.sub":"작은 판을 따는 수 가운데 큰 판에 셋이 이어지는 한 수를 찾자.","pz.th.w2":"2수로 이겨라","pz.th.w2.sub":"상대의 응수를 읽고 두 번째 수로 큰 판에 셋을 잇자.","pz.th.w3":"3수로 이겨라","pz.th.w3.sub":"상대의 버팀을 끝까지 읽고 3수 안에 이기자.","pz.th.w4":"4수로 이겨라","pz.th.w4.sub":"긴 주고받기. 상대의 행선지를 좁히며 몰아붙이자.","pz.th.send":"보낼 곳으로 이기기","pz.th.send.sub":"첫 수는 작은 판을 따지 않는 수. 상대를 보낼 곳이 승부를 가릅니다.","pz.th.free":"자유로운 차례에서 이기기","pz.th.free.sub":"아무 데나 둘 수 있는 국면에서 승리로 가는 한 수를 고르자.","pz.why.last":"{m}로는 큰 판에 셋이 이어지지 않았습니다.","pz.why.took":"상대는 {r}로 {b} 작은 판을 따고 당신을 {t} 작은 판으로 보냈습니다. 남은 {n}수로는 이길 수 없습니다.","pz.why.far":"상대는 {r}로 버티며 당신을 {t} 작은 판으로 보냈습니다. 남은 {n}수로는 큰 판에 셋이 이어지지 않습니다.","pz.why.answer":"「정답」으로 정답 수순을 볼 수 있습니다.","rv.note":"악수 = 승패가 뒤집힌 수 또는 크게 손해 본 수. 의문수 = 작지 않은 손해. 판 위의 숫자는 그 칸에 두었을 때의 평가입니다.","cr.forced":"둘 수 있는 칸이 여기뿐이었습니다.","cr.first":"첫 수입니다. <b>{b}</b> 쪽이 조금 더 좋은 시작이었습니다.","cr.firstOk":"첫 수. 좋은 시작입니다.","cr.won":"큰 판에 셋을 이은 승리의 한 수입니다.","cr.best":"최선수입니다.","cr.bestTake":"최선수입니다. {t} 작은 판을 땄습니다.","cr.good":"나쁘지 않은 수입니다(최선은 <b>{b}</b>, 차이는 근소합니다).","cr.gen":"형세를 해친 수입니다({d}). 최선은 <b>{b}</b>였습니다.","cr.missWin":"승리를 놓쳤습니다. <b>{b}</b>면 큰 판에 셋이 이어졌습니다.","cr.allowWin":"이 수 다음에 상대는 {r}로 큰 판에 셋을 이어 이길 수 있습니다. <b>{b}</b>면 막을 수 있었습니다.","cr.gift":"이 수로 상대를 {t} 작은 판으로 보내 {r}로 {tb} 작은 판을 따이는 형태가 됐습니다. <b>{b}</b>면 주지 않았습니다.","cr.free":"이 수는 승부가 난 작은 판으로 보내므로 상대는 아무 데나 둘 수 있습니다. <b>{b}</b>면 행선지를 묶을 수 있었습니다.","cr.missTake":"{tb} 작은 판을 딸 수 있는 수를 놓쳤습니다. 최선은 <b>{b}</b>였습니다.","cr.tookBad":"작은 판은 땄지만 보낸 곳이 상대에게 유리했습니다. 최선은 <b>{b}</b>였습니다.","cr.tip.take":"💡 딸 수 있는 작은 판은 중요해요. 다만 딴 칸의 위치가 상대의 행선지가 됩니다.","cr.tip.send":"💡 두기 전에, 보낼 작은 판에 상대의 두 줄이 없는지 보자.","cr.tip.free":"💡 승부가 난 작은 판으로 보내면 상대가 가장 중요한 작은 판을 고를 수 있게 됩니다.","cr.tip.look":"💡 따는 수가 보낼 곳도 확인하자. 작은 판보다 큰 판의 모양이 중요한 장면이 있습니다.","cr.tip.gen":"💡 판 위의 화살표가 최선수, 숫자는 그 칸에 두었을 때의 평가입니다."},
"es":{"meta.title":"Ultimate Tic-Tac-Toe — Gran Atlas de Juegos de Mesa","title":"Ultimate Tic-Tac-Toe","sub":"Tres en raya definitivo","p1":"X","p2":"O","ng.first":"Primero (X)","ng.second":"Segundo (O)","ng.level1":"IA del primero (X)","ng.level2":"IA del segundo (O)","pcs":"tableros","hb.free":"Juega donde quieras","hb.to":"Destino: {b}","hb.var":"Variante","rsv.won":"Tableros ganados {n}","rsv.free":"libre","rsv.title":"{c}: {n} tableros pequeños ganados (tres en raya ganan)","send.first":"Juega X: elige cualquier casilla","send.free":"Puedes jugar en cualquier tablero pequeño","send.to":"Juega en el tablero que brilla ({b})","bname":["superior izquierdo","superior","superior derecho","izquierdo","central","derecho","inferior izquierdo","inferior","inferior derecho"],"cant.taken":"Esa casilla ya está ocupada","cant.closed":"Ese tablero pequeño ya está decidido","cant.board":"Juega en el tablero que brilla ({b})","opt.send":"Flecha al siguiente tablero","opt.num":"Coordenadas","ng.rules":"Reglas","var.help":"Ver las reglas","var.fc":"Enviado a un tablero decidido","var.fc0":"Juega donde quieras","var.fc1":"Allí, si tiene huecos","var.tie":"Un tablero pequeño empatado","var.tie0":"No es de nadie","var.tie1":"Cuenta para ambos","var.cnt":"Sin tres en raya en el tablero grande","var.cnt0":"Tablas","var.cnt1":"Gana quien tenga más","var.std":"La regla que más se juega hoy (las partidas puntuadas, lecciones y problemas la usan).","var.custom":"Partida con reglas cambiadas. La IA juega cualquier variante; las partidas puntuadas, lecciones y problemas usan la regla principal.","lvd":["Principiante: solo ve la línea que tiene delante","Novato–intermedio: lee adónde te envían sus jugadas","Avanzado: sopesa la lucha por los tableros pequeños","Experto: lee a fondo el tablero grande"],"lvd.top":"Prueba de rendimiento: la búsqueda más fuerte, larga por jugada (sin recompensas)","bd.title":"Tablero","bd.walnut":"Nogal y latón","bd.slate":"Pizarra escolar","bd.washi":"Washi y sumi","bd.parchment":"Papel viejo y tinta","bd.marble":"Mármol y oro","bd.cherry":"Cerezo y ébano","pcs.title":"Marcas X y O","pcs.token":"Laca y marfil","pcs.brush":"Pincel sumi y bermellón","pcs.chalk":"Tiza","pcs.ink":"Pluma y tinta","res.why.line":"Tres tableros pequeños en raya en el tablero grande","res.why.count":"Sin raya en el tablero grande: decide el número de tableros ganados","res.why.full":"No quedan casillas (sin raya en el tablero grande)","dr.none":"","intro.t":"¿Qué es el Ultimate Tic-Tac-Toe?","intro.origin":"Desconocido (se difundió como juego de lápiz y papel)","intro.players":"2","intro.time":"10–20 min","intro.hist":"Un tres en raya con otro tres en raya más pequeño dentro de cada casilla. Ben Orlin vio a unos matemáticos jugarlo en un pícnic y lo contó en 2013 en su blog «Math with Bad Drawings», lo que lo hizo muy conocido.","intro.win":"Tres en raya en un tablero pequeño lo gana. <b>Tres tableros ganados en raya en el tablero grande ganan la partida.</b> Si nadie puede jugar, son tablas.","intro.cult":"El tres en raya normal siempre acaba en tablas, pero aquí la casilla que juegas decide dónde juega el rival, y eso lo hace profundo: es un clásico de la investigación en IA y de los concursos de programación.","tr.board.t":"El tablero: nueve partidas pequeñas","tr.board.b":"Cada una de las 9 casillas del tablero grande contiene un <b>tablero pequeño</b> de 3 × 3 (81 casillas en total).\nTres en raya en un tablero pequeño lo gana y le pone una marca grande.","tr.first.t":"La primera jugada","tr.first.b":"Empieza X. Solo la primera jugada puede ir <b>a cualquier sitio</b> de las 81 casillas.","tr.first.task":"Pon una X en cualquier casilla","tr.first.ok":"¡Hecho! Ahora le toca a O.","tr.send.t":"Tu casilla envía al rival","tr.send.b":"X jugó la <b>casilla de arriba a la derecha</b> del tablero central, así que O debe jugar en el <b>tablero de arriba a la derecha</b>.\nLa casilla que juegas = el tablero donde juega el rival después.","tr.send.task":"Pon una O en el tablero que brilla","tr.send.ok":"¡Correcto! Ahora la casilla de O decide adónde va X.","tr.pick.t":"Adónde enviar al rival","tr.pick.b":"La casilla que eliges decide <b>el siguiente tablero del rival</b>.\nEs el corazón de la estrategia.","tr.pick.task":"Juega la X que envía a O al <b>tablero de arriba a la derecha</b>","tr.pick.ok":"O va al tablero de arriba a la derecha. ¡Ya sabes elegir adónde enviar!","tr.pick.ng":"Esa casilla envía a O a otro sitio. Usa la casilla de arriba a la derecha del tablero que brilla.","tr.small.t":"Ganar un tablero pequeño","tr.small.b":"Tres en raya en un tablero pequeño —en horizontal, vertical o diagonal— <b>gana ese tablero</b>.\nYa nadie juega en un tablero ganado.","tr.small.task":"Haz tres X en raya y gana el tablero","tr.small.ok":"¡Ganaste el tablero pequeño!","tr.small.ng":"Aún no hay tres en raya. Completa la línea de dos X.","tr.free.t":"Enviado a un tablero decidido","tr.free.b":"Si el tablero al que te envían ya está ganado (o lleno), <b>puedes jugar en cualquier tablero abierto</b>.\nIntenta no dar esa libertad a tu rival.","tr.free.task":"Pon una X en cualquier tablero que brille","tr.free.ok":"¡Una jugada libre!","tr.big.t":"Tres tableros en raya ganan","tr.big.b":"Gana tres tableros pequeños <b>en raya en el tablero grande</b> —en horizontal, vertical o diagonal— para ganar la partida.","tr.big.task":"Gana este tablero para hacer tres en raya","tr.big.ok":"Tres en raya en el tablero grande. ¡Gana X!","tr.big.ng":"Todavía no. Gana el tablero que hace el tercero en raya.","tr.draw.t":"Tablas","tr.draw.b":"Un tablero pequeño que se llena sin raya <b>no es de nadie</b> (gris).\nSi nadie puede jugar y no hay raya en el tablero grande, la partida termina en <b>tablas</b>.","tr.vars.t":"Variantes de las reglas","tr.vars.b":"Este sitio usa la regla que más se juega hoy. En la ventana de nueva partida puedes cambiar tres cosas:\n① Enviado a un tablero decidido: juega donde quieras (regla principal) / juega allí si tiene huecos (la regla del primer artículo; está demostrado que gana el primero)\n② Un tablero pequeño empatado: no es de nadie (regla principal) / cuenta para ambos\n③ Sin raya en el tablero grande al final: tablas (regla principal) / gana quien tenga más tableros","ls.title":"Lecciones","ls.desc":"«Primeros pasos» para quien acaba de aprender las reglas y «Estrategia» para ganar. Cada paso: un calentamiento y luego 5 problemas de 20 puntos; se aprueba con 75.","course.basics":"Primeros pasos","course.basics.sub":"Ganar un tablero, bloquear, elegir adónde enviar, ganar en el tablero grande.","course.strategy":"Estrategia","course.strategy.sub":"Mirar adónde envía la captura, usar una jugada libre, calcular los envíos hasta ganar.","course.graduate":"🎉 ¡«Primeros pasos» completado! Ya puedes jugar: prueba primero la IA de Lv.1–6.","ls.anywhere":"jugada libre","ls.ng.miss":"{x} no hace tres en raya en este tablero.","ls.ng.missBig":"{x} no hace tres en raya en el tablero grande.","ls.ng.lose":"Tras {x}, el rival juega {r} y gana con tres en raya en el tablero grande.","ls.ng.take":"Tras {x} el rival va al tablero {t} y gana el tablero {tb} con {r}.","ls.ng.takeFree":"{x} envía a un tablero decidido: el rival juega donde quiere y gana el tablero {tb} con {r}.","ls.ng.free":"{x} envía a un tablero decidido, así que el rival puede jugar donde quiera.","ls.ng.slow":"Tras {x} el rival resiste con {r} y no logras tres en raya en {n} jugadas más.","ls.ng.ok":"{x} no es mala, pero aquí hay una jugada mejor.","ls.ng.ans":"La respuesta es {m}.","ls.b_take.title":"Ganar un tablero pequeño","ls.b_take.sub":"Pon la tercera marca","ls.b_take.intro":"<p>Si dos de tus marcas están en línea en un tablero pequeño y la tercera casilla está vacía, jugar allí gana ese tablero. Busca esa línea en el tablero donde puedes jugar (el que brilla).</p>","ls.b_take.goal":"Juega la casilla que gana un tablero pequeño.","ls.b_take.hint":"En el tablero que brilla, busca una línea con dos de tus marcas.","ls.b_take.why":"¡{m} gana el tablero {b}!","ls.b_take.ex.t":"La tercera de la línea","ls.b_take.ex.b":"El tablero que brilla tiene una línea con dos de tus marcas. Jugar la tercera, {m}, gana el tablero.","ls.b_block.title":"Bloquear su tercera","ls.b_block.sub":"Defiende antes de perderlo","ls.b_block.intro":"<p>Si el rival tiene dos en raya en el tablero donde juegas, bloquear la tercera casilla es la defensa básica. Si no, lo ganará en cuanto lo envíen allí (o tenga una jugada libre).</p>","ls.b_block.goal":"Juega la jugada que defiende este tablero.","ls.b_block.hint":"En el tablero que brilla, ¿dónde hay dos marcas del rival en línea?","ls.b_block.why":"{m} bloquea su tercera casilla. El rival va al tablero {t} y no puede ganar un tablero enseguida.","ls.b_block.ex.t":"Bloquea la tercera","ls.b_block.ex.b":"El rival tiene dos en raya en el tablero que brilla. Bloquear la tercera, {m}, mantiene el tablero a salvo por ahora.","ls.b_send.title":"Elegir adónde enviar","ls.b_send.sub":"No regales nada","ls.b_send.intro":"<p>La casilla que juegas decide el siguiente tablero del rival. Enviarlo a un tablero donde tiene dos en raya le deja ganarlo. Comprueba antes de jugar qué tablero es seguro.</p>","ls.b_send.goal":"Juega una jugada que no regale ningún tablero pequeño.","ls.b_send.hint":"Los tableros que brillan en rojo tienen dos en raya del rival. ¿Qué casilla no lo envía allí?","ls.b_send.why":"Con {m} el rival va al tablero {t} y allí no puede ganar un tablero enseguida.","ls.b_send.ex.t":"Comprueba adónde envías","ls.b_send.ex.b":"La jugada roja envía al rival a un tablero con sus dos en raya y lo gana. La verde, {m}, lo envía adonde no puede.","ls.b_big.title":"Tres en raya en el tablero grande","ls.b_big.sub":"Cierra la partida","ls.b_big.intro":"<p>Cuando dos de tus tableros ganados están en línea en el tablero grande, ganar el tercero gana la partida. Puede haber varias jugadas que ganen un tablero pequeño, pero solo la tercera de esa línea gana.</p>","ls.b_big.goal":"Gana la partida con esta jugada.","ls.b_big.hint":"El tablero punteado está a uno de hacer tres en raya en el tablero grande. ¿Qué jugada lo gana?","ls.b_big.why":"{m} gana el tablero {b}: tres en raya en el tablero grande. ¡Ganas!","ls.b_big.ex.t":"El tercero del tablero grande","ls.b_big.ex.b":"Gana el tercer tablero de una línea de dos en el tablero grande (el punteado) y la partida es tuya. {m} lo consigue.","ls.s_look.title":"Mira antes de capturar","ls.s_look.sub":"La trampa del tablero regalado","ls.s_look.intro":"<p>Una jugada puede ganar un tablero pequeño y aun así enviar al rival a un buen sitio. Comprueba adónde envía la casilla ganadora y elige la jugada que no regala nada.</p>","ls.s_look.goal":"Juega la mejor jugada (ganar un tablero no siempre lo es).","ls.s_look.hint":"Los tableros que brillan en rojo tienen dos en raya del rival. ¿Adónde envía la jugada que gana?","ls.s_look.why":"Con {m} el rival va al tablero {t} y no puede ganar un tablero enseguida. Aquí importaba más adónde envías que el tablero de delante.","ls.s_look.ex.t":"Ganarlo lo enviaría","ls.s_look.ex.b":"La jugada roja gana un tablero pero envía al rival a un tablero con sus dos en raya. La verde, {m}, que lo envía a un lugar seguro, es la correcta.","ls.s_free.title":"Usar una jugada libre","ls.s_free.sub":"Ve adonde importa","ls.s_free.intro":"<p>Una jugada libre es una gran oportunidad. Juega en el tablero que importa en el tablero grande: el que haría tres en raya para cualquiera de los dos.</p>","ls.s_free.goal":"Puedes jugar donde quieras. Juega la jugada más importante.","ls.s_free.hint":"Los tableros punteados son los clave del tablero grande. ¿Qué puedes hacer allí?","ls.s_free.why":"{m} va al tablero clave del tablero grande, el tablero {b}.","ls.s_free.ex.t":"Elige el tablero clave","ls.s_free.ex.b":"Una jugada libre te deja elegir el tablero clave del tablero grande (punteado). {m} es esa jugada.","ls.s_force2.title":"Gana en 2","ls.s_force2.sub":"Calcula los envíos","ls.s_force2.intro":"<p>Envía al rival a un tablero donde cualquier jugada suya permita que tu siguiente jugada complete tres en raya en el tablero grande. Revisa cada casilla suya y adónde te envía.</p>","ls.s_force2.goal":"Haz tres en raya en el tablero grande en 2 jugadas.","ls.s_force2.hint":"Busca un tablero al que enviarlo donde todas sus respuestas lleven a tu victoria.","ls.s_force2.why":"{m} es la jugada ganadora: responda lo que responda, tu siguiente jugada completa tres en raya.","ls.s_force2.ex.t":"Envía y gana","ls.s_force2.ex.b":"Tras la verde, {m}, cada respuesta del rival te envía a un tablero donde ganas.","ls.s_force3.title":"Gana en 3","ls.s_force3.sub":"Forzar en el final","ls.s_force3.intro":"<p>En el final, los envíos deciden la partida. Reduce las opciones del rival en cada jugada y calcula el camino a tres en raya en 3 jugadas.</p>","ls.s_force3.goal":"Haz tres en raya en el tablero grande en 3 jugadas.","ls.s_force3.hint":"Revisa por orden: jugadas que ganan un tablero, jugadas que no regalan nada, jugadas que no dan jugada libre.","ls.s_force3.why":"Desde {m} ganas en 3 jugadas.","ls.s_force3.ex.t":"Calcular 3 jugadas","ls.s_force3.ex.b":"Desde la verde, {m}, responde a cada réplica devolviéndolo y gana en el tablero grande en 3.","pz.title":"Problemas de Ultimate Tic-Tac-Toe","pz.desc":"Haz tres en raya en el tablero grande en el número de jugadas dado. El rival defiende con la mayor terquedad. Todas las soluciones están demostradas por el motor.","pz.winIn":"Gana en {n}","pz.goal":"Juega {c}: tres en raya en el tablero grande en {n} jugadas","pz.start":"Haz tu primera jugada.","pz.best":"La respuesta era {b}.","pz.solvedSub":"Tres en raya en el tablero grande en {n} jugadas.","pz.hint1":"Quedan {n} jugadas. Mira qué puede hacer el rival en el tablero al que lo envías.","pz.hintText":"Una jugada ganadora empieza en el tablero punteado.","pz.reply":"El rival juega {m}. Quedan {n} jugadas.","pz.retry":"Reintentar","pz.grpWin":"Gana en N","pz.grpWinSub":"Haz tres en raya en el tablero grande en las jugadas dadas, contra la defensa más tenaz.","pz.grpTac":"Temas","pz.grpTacSub":"Ganar enviando · ganar desde una jugada libre. Ganar tableros no basta para resolverlos.","pz.th.w1":"Gana en 1","pz.th.w1.sub":"Entre las jugadas que ganan un tablero pequeño, encuentra la que gana la partida.","pz.th.w2":"Gana en 2","pz.th.w2.sub":"Lee su respuesta y completa la raya con tu segunda jugada.","pz.th.w3":"Gana en 3","pz.th.w3.sub":"Calcula su defensa y gana en 3 jugadas.","pz.th.w4":"Gana en 4","pz.th.w4.sub":"Luchas largas de envíos: reduce sus opciones y acorrálalo.","pz.th.send":"Ganar enviando","pz.th.send.sub":"La primera jugada no gana ningún tablero: adónde envía al rival decide la partida.","pz.th.free":"Ganar desde una jugada libre","pz.th.free.sub":"Puedes jugar donde quieras: elige la jugada que lleva a la victoria.","pz.why.last":"{m} no hizo tres en raya en el tablero grande.","pz.why.took":"El rival ganó el tablero {b} con {r} y te envió al tablero {t}. No puedes ganar en {n} jugadas más.","pz.why.far":"El rival resistió con {r} y te envió al tablero {t}. No hay tres en raya en {n} jugadas más.","pz.why.answer":"Pulsa «Respuesta» para ver la solución.","rv.note":"Error = jugada que dio la vuelta a una victoria o unas tablas, o perdió mucho. Dudosa = una pérdida clara. Los números del tablero son el valor de jugar cada casilla.","cr.forced":"La única casilla posible.","cr.first":"La primera jugada. <b>{b}</b> era un comienzo algo mejor.","cr.firstOk":"La primera jugada: un buen comienzo.","cr.won":"La jugada ganadora: tres en raya en el tablero grande.","cr.best":"La mejor jugada.","cr.bestTake":"La mejor jugada: ganó el tablero {t}.","cr.good":"No está mal (la mejor era <b>{b}</b>, solo un poco mejor).","cr.gen":"Esto empeoró la posición ({d}). La mejor era <b>{b}</b>.","cr.missWin":"Se escapó la victoria: <b>{b}</b> hacía tres en raya en el tablero grande.","cr.allowWin":"Después de esto el rival gana con {r}, tres en raya en el tablero grande. <b>{b}</b> lo impedía.","cr.gift":"Esto envió al rival al tablero {t}, donde {r} le da el tablero {tb}. <b>{b}</b> no regalaba nada.","cr.free":"Esto envió a un tablero decidido, así que el rival podía jugar donde quisiera. <b>{b}</b> lo mantenía en un tablero.","cr.missTake":"Se te escapó ganar el tablero {tb}. La mejor era <b>{b}</b>.","cr.tookBad":"Ganaste un tablero, pero adónde envió al rival le ayudó. La mejor era <b>{b}</b>.","cr.tip.take":"💡 Los tableros que puedes ganar importan, pero la casilla ganadora decide adónde va el rival.","cr.tip.send":"💡 Antes de jugar, busca dos en raya del rival en el tablero al que lo envías.","cr.tip.free":"💡 Enviar a un tablero decidido deja al rival elegir el tablero que más importa.","cr.tip.look":"💡 Comprueba adónde envía una jugada que gana. A veces importa más el tablero grande que el pequeño.","cr.tip.gen":"💡 La flecha del tablero es la mejor jugada; los números son el valor de jugar cada casilla."},
"fr":{"meta.title":"Morpion ultime — Grand Atlas des jeux de société","title":"Morpion ultime","sub":"Ultimate Tic-Tac-Toe","p1":"X","p2":"O","ng.first":"Premier (X)","ng.second":"Second (O)","ng.level1":"IA du premier (X)","ng.level2":"IA du second (O)","pcs":"grilles","hb.free":"Coup libre","hb.to":"Envoyé : {b}","hb.var":"Variante","rsv.won":"Grilles gagnées {n}","rsv.free":"libre","rsv.title":"{c} : {n} petites grilles gagnées (trois alignées gagnent)","send.first":"Au tour de X : n’importe quelle case","send.free":"Vous pouvez jouer dans n’importe quelle petite grille","send.to":"Jouez dans la grille qui brille ({b})","bname":["en haut à gauche","en haut","en haut à droite","à gauche","au centre","à droite","en bas à gauche","en bas","en bas à droite"],"cant.taken":"Cette case est déjà prise","cant.closed":"Cette petite grille est déjà décidée","cant.board":"Jouez dans la grille qui brille ({b})","opt.send":"Flèche vers la grille suivante","opt.num":"Coordonnées","ng.rules":"Règles","var.help":"Voir les règles","var.fc":"Envoyé vers une grille décidée","var.fc0":"Jouer n’importe où","var.fc1":"Y jouer s’il reste de la place","var.tie":"Une petite grille nulle","var.tie0":"N’est à personne","var.tie1":"Compte pour les deux","var.cnt":"Aucun alignement sur la grande grille","var.cnt0":"Partie nulle","var.cnt1":"Le plus de grilles gagne","var.std":"La règle la plus jouée aujourd’hui (parties classées, leçons et problèmes l’utilisent).","var.custom":"Partie à règles modifiées. L’IA joue toutes les variantes ; parties classées, leçons et problèmes gardent la règle principale.","lvd":["Débutant : ne voit que l’alignement devant lui","Novice–intermédiaire : lit où ses coups vous envoient","Avancé : pèse la lutte pour les petites grilles","Expert : lit loin dans la grande grille"],"lvd.top":"Banc d’essai : le calcul le plus fort, long à chaque coup (sans récompense)","bd.title":"Plateau","bd.walnut":"Noyer et laiton","bd.slate":"Ardoise d’écolier","bd.washi":"Washi et sumi","bd.parchment":"Vieux papier et encre","bd.marble":"Marbre et or","bd.cherry":"Merisier et ébène","pcs.title":"Marques X et O","pcs.token":"Laque et ivoire","pcs.brush":"Pinceau sumi et vermillon","pcs.chalk":"Craie","pcs.ink":"Plume et encre","res.why.line":"Trois petites grilles alignées sur la grande grille","res.why.count":"Pas d’alignement sur la grande grille : décidé par le nombre de grilles gagnées","res.why.full":"Plus aucune case jouable (pas d’alignement sur la grande grille)","dr.none":"","intro.t":"Qu’est-ce que le morpion ultime ?","intro.origin":"Inconnue (répandu comme jeu papier-crayon)","intro.players":"2","intro.time":"10–20 min","intro.hist":"Un morpion dont chaque case contient un morpion plus petit. Ben Orlin l’a vu jouer par des mathématiciens lors d’un pique-nique et l’a raconté en 2013 sur son blog « Math with Bad Drawings », ce qui l’a fait connaître.","intro.win":"Trois alignés dans une petite grille la gagnent. <b>Trois grilles gagnées alignées sur la grande grille gagnent la partie.</b> Si personne ne peut jouer, c’est nul.","intro.cult":"Le morpion classique finit toujours nul, mais ici la case jouée décide où joue l’adversaire, ce qui rend le jeu profond : un favori de la recherche en IA et des concours de programmation.","tr.board.t":"Le plateau : neuf petites parties","tr.board.b":"Chacune des 9 cases de la grande grille contient une <b>petite grille</b> de 3 × 3 (81 cases en tout).\nTrois alignés dans une petite grille la gagnent et y posent une grande marque.","tr.first.t":"Le premier coup","tr.first.b":"X commence. Seul le tout premier coup peut aller <b>n’importe où</b> parmi les 81 cases.","tr.first.task":"Placez un X dans n’importe quelle case","tr.first.ok":"C’est fait ! Au tour de O.","tr.send.t":"Votre case envoie l’adversaire","tr.send.b":"X a joué la <b>case en haut à droite</b> de la grille centrale : O doit donc jouer dans la <b>grille en haut à droite</b>.\nLa case jouée = la grille où l’adversaire joue ensuite.","tr.send.task":"Placez un O dans la grille qui brille","tr.send.ok":"Exact ! Maintenant la case de O décide où va X.","tr.pick.t":"Où envoyer l’adversaire","tr.pick.b":"La case choisie décide de <b>la prochaine grille de l’adversaire</b>.\nC’est le cœur de la stratégie.","tr.pick.task":"Jouez le X qui envoie O dans la <b>grille en haut à droite</b>","tr.pick.ok":"O part en haut à droite. Vous savez choisir où envoyer !","tr.pick.ng":"Cette case envoie O ailleurs. Prenez la case en haut à droite de la grille qui brille.","tr.small.t":"Gagner une petite grille","tr.small.b":"Trois alignés dans une petite grille — en ligne, en colonne ou en diagonale — <b>la gagnent</b>.\nPlus personne ne joue dans une grille gagnée.","tr.small.task":"Alignez trois X et gagnez la grille","tr.small.ok":"Petite grille gagnée !","tr.small.ng":"Pas encore d’alignement. Complétez la ligne de deux X.","tr.free.t":"Envoyé vers une grille décidée","tr.free.b":"Si la grille où l’on vous envoie est déjà gagnée (ou pleine), <b>vous pouvez jouer dans n’importe quelle grille ouverte</b>.\nÉvitez d’offrir cette liberté à l’adversaire.","tr.free.task":"Placez un X dans une grille qui brille","tr.free.ok":"Un coup libre !","tr.big.t":"Trois grilles alignées gagnent","tr.big.b":"Gagnez trois petites grilles <b>alignées sur la grande grille</b> — en ligne, en colonne ou en diagonale — pour gagner la partie.","tr.big.task":"Gagnez cette grille pour aligner trois","tr.big.ok":"Trois alignées sur la grande grille. X gagne !","tr.big.ng":"Pas encore. Gagnez la grille qui fait la troisième de l’alignement.","tr.draw.t":"Parties nulles","tr.draw.b":"Une petite grille remplie sans alignement <b>n’est à personne</b> (grise).\nSi personne ne peut jouer et qu’il n’y a pas d’alignement sur la grande grille, la partie est <b>nulle</b>.","tr.vars.t":"Variantes des règles","tr.vars.b":"Ce site joue la règle la plus répandue aujourd’hui. Dans la fenêtre de nouvelle partie, vous pouvez changer trois choses :\n① Envoyé vers une grille décidée : jouer n’importe où (règle principale) / y jouer s’il reste de la place (la règle du premier article ; gain prouvé pour le premier joueur)\n② Une petite grille nulle : n’est à personne (règle principale) / compte pour les deux\n③ Pas d’alignement sur la grande grille à la fin : nul (règle principale) / le plus de grilles gagnées l’emporte","ls.title":"Leçons","ls.desc":"« Premiers pas » pour qui vient d’apprendre les règles, et « Stratégie » pour gagner. Chaque étape : un échauffement puis 5 problèmes de 20 points ; 75 pour réussir.","course.basics":"Premiers pas","course.basics.sub":"Gagner une grille, bloquer, choisir où envoyer, gagner sur la grande grille.","course.strategy":"Stratégie","course.strategy.sub":"Regarder où mène une prise, utiliser un coup libre, calculer les envois jusqu’au gain.","course.graduate":"🎉 « Premiers pas » terminé ! Vous pouvez jouer : essayez d’abord l’IA Lv.1–6.","ls.anywhere":"un coup libre","ls.ng.miss":"{x} n’aligne pas trois sur cette grille.","ls.ng.missBig":"{x} n’aligne pas trois sur la grande grille.","ls.ng.lose":"Après {x}, l’adversaire joue {r} et gagne avec trois alignées sur la grande grille.","ls.ng.take":"Après {x}, l’adversaire va dans la grille {t} et gagne la grille {tb} avec {r}.","ls.ng.takeFree":"{x} envoie vers une grille décidée : l’adversaire joue où il veut et gagne la grille {tb} avec {r}.","ls.ng.free":"{x} envoie vers une grille décidée : l’adversaire peut jouer où il veut.","ls.ng.slow":"Après {x}, l’adversaire tient avec {r} et vous ne pouvez pas aligner trois en {n} coups de plus.","ls.ng.ok":"{x} n’est pas mauvais, mais il y a mieux ici.","ls.ng.ans":"La réponse est {m}.","ls.b_take.title":"Gagner une petite grille","ls.b_take.sub":"Poser la troisième marque","ls.b_take.intro":"<p>Si deux de vos marques sont alignées dans une petite grille et que la troisième case est vide, y jouer gagne cette grille. Cherchez un tel alignement dans la grille où vous jouez (celle qui brille).</p>","ls.b_take.goal":"Jouez la case qui gagne une petite grille.","ls.b_take.hint":"Dans la grille qui brille, trouvez une ligne avec deux de vos marques.","ls.b_take.why":"{m} gagne la grille {b} !","ls.b_take.ex.t":"La troisième de la ligne","ls.b_take.ex.b":"La grille qui brille a une ligne avec deux de vos marques. Jouer la troisième, {m}, gagne la grille.","ls.b_block.title":"Bloquer sa troisième","ls.b_block.sub":"Défendre avant de perdre","ls.b_block.intro":"<p>Si l’adversaire a deux alignés dans la grille où vous jouez, bloquer la troisième case est la défense de base. Sinon, il la gagne dès qu’on l’y envoie (ou qu’il a un coup libre).</p>","ls.b_block.goal":"Jouez le coup qui défend cette grille.","ls.b_block.hint":"Dans la grille qui brille, où sont deux marques adverses alignées ?","ls.b_block.why":"{m} bloque sa troisième case. L’adversaire va dans la grille {t} et ne peut pas gagner de grille tout de suite.","ls.b_block.ex.t":"Bloquer la troisième","ls.b_block.ex.b":"L’adversaire a deux alignés dans la grille qui brille. Bloquer la troisième, {m}, protège la grille pour l’instant.","ls.b_send.title":"Choisir où envoyer","ls.b_send.sub":"Ne rien offrir","ls.b_send.intro":"<p>La case jouée décide de la prochaine grille de l’adversaire. L’envoyer dans une grille où il a deux alignés lui permet de la gagner. Vérifiez avant de jouer quelle grille est sûre.</p>","ls.b_send.goal":"Jouez un coup qui n’offre aucune petite grille.","ls.b_send.hint":"Les grilles qui brillent en rouge contiennent deux alignés adverses. Quelle case ne l’y envoie pas ?","ls.b_send.why":"Avec {m}, l’adversaire va dans la grille {t} et n’y peut pas gagner de grille tout de suite.","ls.b_send.ex.t":"Vérifier où l’on envoie","ls.b_send.ex.b":"Le coup rouge envoie l’adversaire dans une grille avec ses deux alignés, qu’il gagne. Le vert, {m}, l’envoie là où il ne peut pas.","ls.b_big.title":"Aligner trois sur la grande grille","ls.b_big.sub":"Finir la partie","ls.b_big.intro":"<p>Quand deux de vos grilles gagnées sont alignées sur la grande grille, gagner la troisième gagne la partie. Plusieurs coups peuvent gagner une petite grille, mais seule la troisième de cet alignement gagne.</p>","ls.b_big.goal":"Gagnez la partie avec ce coup.","ls.b_big.hint":"La grille en pointillé est à une grille de l’alignement sur la grande grille. Quel coup la gagne ?","ls.b_big.why":"{m} gagne la grille {b} : trois alignées sur la grande grille. Vous gagnez !","ls.b_big.ex.t":"La troisième de la grande grille","ls.b_big.ex.b":"Gagnez la troisième grille d’un alignement de deux sur la grande grille (en pointillé) et la partie est à vous. {m} le fait.","ls.s_look.title":"Regarder avant de prendre","ls.s_look.sub":"Le piège de la grille offerte","ls.s_look.intro":"<p>Un coup peut gagner une petite grille et pourtant envoyer l’adversaire à un bon endroit. Vérifiez où envoie la case gagnante et choisissez le coup qui n’offre rien.</p>","ls.s_look.goal":"Jouez le meilleur coup (gagner une grille n’est pas toujours la solution).","ls.s_look.hint":"Les grilles qui brillent en rouge contiennent deux alignés adverses. Où envoie le coup qui prend ?","ls.s_look.why":"Avec {m}, l’adversaire va dans la grille {t} et ne peut pas gagner de grille tout de suite. Ici, où l’on envoie comptait plus que la grille sous les yeux.","ls.s_look.ex.t":"Prendre l’enverrait","ls.s_look.ex.b":"Le coup rouge gagne une grille mais envoie l’adversaire vers une grille avec ses deux alignés. Le vert, {m}, qui l’envoie en lieu sûr, est le bon.","ls.s_free.title":"Utiliser un coup libre","ls.s_free.sub":"Aller là où ça compte","ls.s_free.intro":"<p>Un coup libre est une belle occasion. Jouez dans la grille qui compte sur la grande grille : celle qui ferait un alignement pour l’un ou l’autre.</p>","ls.s_free.goal":"Vous pouvez jouer n’importe où. Jouez le coup le plus important.","ls.s_free.hint":"Les grilles en pointillé sont les grilles clés de la grande grille. Que pouvez-vous y faire ?","ls.s_free.why":"{m} va dans la grille clé de la grande grille, la grille {b}.","ls.s_free.ex.t":"Choisir la grille clé","ls.s_free.ex.b":"Un coup libre permet de choisir la grille clé de la grande grille (en pointillé). {m} est ce coup.","ls.s_force2.title":"Gagner en 2","ls.s_force2.sub":"Calculer les envois","ls.s_force2.intro":"<p>Envoyez l’adversaire dans une grille où chacun de ses coups permet à votre coup suivant d’aligner trois sur la grande grille. Vérifiez chacune de ses cases et où elle vous envoie.</p>","ls.s_force2.goal":"Alignez trois sur la grande grille en 2 coups.","ls.s_force2.hint":"Trouvez une grille où l’envoyer telle que toutes ses réponses mènent à votre gain.","ls.s_force2.why":"{m} est le coup gagnant : quoi qu’il réponde, votre coup suivant aligne trois.","ls.s_force2.ex.t":"Envoyer et gagner","ls.s_force2.ex.b":"Après le vert, {m}, chaque réponse de l’adversaire vous envoie vers une grille où vous gagnez.","ls.s_force3.title":"Gagner en 3","ls.s_force3.sub":"Forcer en finale","ls.s_force3.intro":"<p>En finale, les envois décident de la partie. Réduisez les choix de l’adversaire à chaque coup et calculez le chemin vers l’alignement en 3 coups.</p>","ls.s_force3.goal":"Alignez trois sur la grande grille en 3 coups.","ls.s_force3.hint":"Vérifiez dans l’ordre : les coups qui gagnent une grille, ceux qui n’offrent rien, ceux qui ne donnent pas de coup libre.","ls.s_force3.why":"À partir de {m}, vous gagnez en 3 coups.","ls.s_force3.ex.t":"Calculer 3 coups","ls.s_force3.ex.b":"À partir du vert, {m}, renvoyez-le à chaque réponse et gagnez sur la grande grille en 3.","pz.title":"Problèmes de morpion ultime","pz.desc":"Alignez trois sur la grande grille dans le nombre de coups donné. L’adversaire se défend le plus obstinément possible. Chaque solution est prouvée par le moteur.","pz.winIn":"Gain en {n}","pz.goal":"{c} joue : trois alignées sur la grande grille en {n} coups","pz.start":"Jouez votre premier coup.","pz.best":"La réponse était {b}.","pz.solvedSub":"Trois alignées sur la grande grille en {n} coups.","pz.hint1":"Encore {n} coups. Regardez ce que l’adversaire peut faire dans la grille où vous l’envoyez.","pz.hintText":"Un coup gagnant commence dans la grille en pointillé.","pz.reply":"L’adversaire joue {m}. Encore {n} coups.","pz.retry":"Recommencer","pz.grpWin":"Gain en N","pz.grpWinSub":"Alignez trois sur la grande grille dans les coups donnés, face à la défense la plus tenace.","pz.grpTac":"Thèmes","pz.grpTacSub":"Gagner en envoyant · gagner depuis un coup libre. Prendre des grilles ne suffit pas.","pz.th.w1":"Gain en 1","pz.th.w1.sub":"Parmi les coups qui gagnent une petite grille, trouvez celui qui gagne la partie.","pz.th.w2":"Gain en 2","pz.th.w2.sub":"Lisez sa réponse et alignez avec votre deuxième coup.","pz.th.w3":"Gain en 3","pz.th.w3.sub":"Calculez sa défense et gagnez en 3 coups.","pz.th.w4":"Gain en 4","pz.th.w4.sub":"De longs échanges d’envois : réduisez ses choix et acculez-le.","pz.th.send":"Gagner en envoyant","pz.th.send.sub":"Le premier coup ne gagne aucune grille : où il envoie l’adversaire décide la partie.","pz.th.free":"Gagner depuis un coup libre","pz.th.free.sub":"Vous pouvez jouer n’importe où : choisissez le coup qui mène au gain.","pz.why.last":"{m} n’a pas aligné trois sur la grande grille.","pz.why.took":"L’adversaire a gagné la grille {b} avec {r} et vous a envoyé dans la grille {t}. Pas de gain en {n} coups de plus.","pz.why.far":"L’adversaire a tenu avec {r} et vous a envoyé dans la grille {t}. Pas d’alignement en {n} coups de plus.","pz.why.answer":"Appuyez sur « Réponse » pour voir la solution.","rv.note":"Erreur = un coup qui a retourné un gain ou une nulle, ou perdu beaucoup. Douteux = une perte nette. Les nombres sur le plateau valent le coup joué sur chaque case.","cr.forced":"La seule case jouable.","cr.first":"Le premier coup. <b>{b}</b> était un départ un peu meilleur.","cr.firstOk":"Le premier coup : un bon départ.","cr.won":"Le coup gagnant : trois alignées sur la grande grille.","cr.best":"Le meilleur coup.","cr.bestTake":"Le meilleur coup : il gagne la grille {t}.","cr.good":"Pas mal (le meilleur était <b>{b}</b>, à peine meilleur).","cr.gen":"Ce coup a gâché la position ({d}). Le meilleur était <b>{b}</b>.","cr.missWin":"Gain manqué : <b>{b}</b> alignait trois sur la grande grille.","cr.allowWin":"Après ce coup, l’adversaire gagne avec {r}, trois alignées sur la grande grille. <b>{b}</b> l’empêchait.","cr.gift":"Ce coup a envoyé l’adversaire dans la grille {t}, où {r} lui donne la grille {tb}. <b>{b}</b> n’offrait rien.","cr.free":"Ce coup envoyait vers une grille décidée : l’adversaire pouvait jouer n’importe où. <b>{b}</b> le gardait dans une grille.","cr.missTake":"Vous avez manqué le gain de la grille {tb}. Le meilleur était <b>{b}</b>.","cr.tookBad":"Vous avez gagné une grille, mais l’endroit où l’adversaire a été envoyé l’a aidé. Le meilleur était <b>{b}</b>.","cr.tip.take":"💡 Les grilles gagnables comptent, mais la case gagnante décide où va l’adversaire.","cr.tip.send":"💡 Avant de jouer, cherchez ses deux alignés dans la grille où vous l’envoyez.","cr.tip.free":"💡 Envoyer vers une grille décidée laisse l’adversaire choisir la grille qui compte le plus.","cr.tip.look":"💡 Vérifiez où envoie un coup qui prend. Parfois la grande grille compte plus que la petite.","cr.tip.gen":"💡 La flèche sur le plateau est le meilleur coup ; les nombres valent le coup sur chaque case."},
"pt":{"meta.title":"Jogo da velha supremo — Grande Atlas dos Jogos de Tabuleiro","title":"Jogo da velha supremo","sub":"Ultimate Tic-Tac-Toe","p1":"X","p2":"O","ng.first":"Primeiro (X)","ng.second":"Segundo (O)","ng.level1":"IA do primeiro (X)","ng.level2":"IA do segundo (O)","pcs":"tabuleiros","hb.free":"Jogada livre","hb.to":"Destino: {b}","hb.var":"Variante","rsv.won":"Tabuleiros ganhos {n}","rsv.free":"livre","rsv.title":"{c}: {n} tabuleiros pequenos ganhos (três em linha vencem)","send.first":"Vez do X: jogue em qualquer casa","send.free":"Você pode jogar em qualquer tabuleiro pequeno","send.to":"Jogue no tabuleiro que brilha ({b})","bname":["superior esquerdo","superior","superior direito","esquerdo","central","direito","inferior esquerdo","inferior","inferior direito"],"cant.taken":"Essa casa já está ocupada","cant.closed":"Esse tabuleiro pequeno já está decidido","cant.board":"Jogue no tabuleiro que brilha ({b})","opt.send":"Seta para o próximo tabuleiro","opt.num":"Coordenadas","ng.rules":"Regras","var.help":"Ver as regras","var.fc":"Enviado a um tabuleiro decidido","var.fc0":"Jogue onde quiser","var.fc1":"Ali, se houver espaço","var.tie":"Um tabuleiro pequeno empatado","var.tie0":"Não é de ninguém","var.tie1":"Conta para os dois","var.cnt":"Sem três em linha no tabuleiro grande","var.cnt0":"Empate","var.cnt1":"Vence quem tiver mais","var.std":"A regra mais jogada hoje (partidas ranqueadas, lições e problemas também a usam).","var.custom":"Partida com regras alteradas. A IA joga qualquer variante; partidas ranqueadas, lições e problemas mantêm a regra principal.","lvd":["Iniciante: só vê a linha à sua frente","Novato–intermediário: lê para onde suas jogadas mandam você","Avançado: pesa a disputa pelos tabuleiros pequenos","Especialista: lê fundo o tabuleiro grande"],"lvd.top":"Teste de desempenho: a busca mais forte, longa a cada jogada (sem recompensas)","bd.title":"Tabuleiro","bd.walnut":"Nogueira e latão","bd.slate":"Lousa escolar","bd.washi":"Washi e sumi","bd.parchment":"Papel antigo e tinta","bd.marble":"Mármore e ouro","bd.cherry":"Cerejeira e ébano","pcs.title":"Marcas X e O","pcs.token":"Laca e marfim","pcs.brush":"Pincel sumi e vermelhão","pcs.chalk":"Giz","pcs.ink":"Pena e tinta","res.why.line":"Três tabuleiros pequenos em linha no tabuleiro grande","res.why.count":"Sem linha no tabuleiro grande: decidido pelos tabuleiros ganhos","res.why.full":"Não há mais casas (sem linha no tabuleiro grande)","dr.none":"","intro.t":"O que é o jogo da velha supremo?","intro.origin":"Desconhecida (difundido como jogo de papel e lápis)","intro.players":"2","intro.time":"10–20 min","intro.hist":"Um jogo da velha com outro jogo da velha menor em cada casa. Ben Orlin viu matemáticos jogando num piquenique e escreveu sobre ele em 2013 no blog «Math with Bad Drawings», o que o tornou conhecido.","intro.win":"Três em linha num tabuleiro pequeno o ganham. <b>Três tabuleiros ganhos em linha no tabuleiro grande vencem a partida.</b> Se ninguém puder jogar, é empate.","intro.cult":"O jogo da velha comum sempre empata, mas aqui a casa jogada decide onde o adversário joga, o que torna o jogo profundo — é um clássico da pesquisa em IA e de competições de programação.","tr.board.t":"O tabuleiro: nove jogos pequenos","tr.board.b":"Cada uma das 9 casas do tabuleiro grande tem um <b>tabuleiro pequeno</b> 3 × 3 (81 casas ao todo).\nTrês em linha num tabuleiro pequeno o ganham e colocam nele uma marca grande.","tr.first.t":"A primeira jogada","tr.first.b":"X começa. Só a primeira jogada pode ir para <b>qualquer lugar</b> entre as 81 casas.","tr.first.task":"Coloque um X em qualquer casa","tr.first.ok":"Pronto! Agora é a vez do O.","tr.send.t":"Sua casa envia o adversário","tr.send.b":"X jogou na <b>casa superior direita</b> do tabuleiro central, então O deve jogar no <b>tabuleiro superior direito</b>.\nA casa que você joga = o tabuleiro onde o adversário joga em seguida.","tr.send.task":"Coloque um O no tabuleiro que brilha","tr.send.ok":"Isso! Agora a casa do O decide para onde vai o X.","tr.pick.t":"Para onde enviar o adversário","tr.pick.b":"A casa que você escolhe decide <b>o próximo tabuleiro do adversário</b>.\nEsse é o coração da estratégia.","tr.pick.task":"Jogue o X que envia o O para o <b>tabuleiro superior direito</b>","tr.pick.ok":"O vai para o tabuleiro superior direito. Você escolheu o destino!","tr.pick.ng":"Essa casa envia o O para outro lugar. Use a casa superior direita do tabuleiro que brilha.","tr.small.t":"Ganhar um tabuleiro pequeno","tr.small.b":"Três em linha num tabuleiro pequeno — na horizontal, vertical ou diagonal — <b>ganham esse tabuleiro</b>.\nNinguém mais joga num tabuleiro ganho.","tr.small.task":"Faça três X em linha e ganhe o tabuleiro","tr.small.ok":"Você ganhou o tabuleiro pequeno!","tr.small.ng":"Ainda não há três em linha. Complete a linha de dois X.","tr.free.t":"Enviado a um tabuleiro decidido","tr.free.b":"Se o tabuleiro para onde você é enviado já foi ganho (ou está cheio), <b>você pode jogar em qualquer tabuleiro aberto</b>.\nEvite dar essa liberdade ao adversário.","tr.free.task":"Coloque um X em qualquer tabuleiro que brilha","tr.free.ok":"Uma jogada livre!","tr.big.t":"Três tabuleiros em linha vencem","tr.big.b":"Ganhe três tabuleiros pequenos <b>em linha no tabuleiro grande</b> — na horizontal, vertical ou diagonal — para vencer a partida.","tr.big.task":"Ganhe este tabuleiro para fazer três em linha","tr.big.ok":"Três em linha no tabuleiro grande. X vence!","tr.big.ng":"Ainda não. Ganhe o tabuleiro que faz o terceiro da linha.","tr.draw.t":"Empates","tr.draw.b":"Um tabuleiro pequeno que se enche sem linha <b>não é de ninguém</b> (cinza).\nSe ninguém puder jogar e não houver linha no tabuleiro grande, a partida termina <b>empatada</b>.","tr.vars.t":"Variantes das regras","tr.vars.b":"Este site usa a regra mais jogada hoje. Na janela de nova partida você pode mudar três coisas:\n① Enviado a um tabuleiro decidido: jogue onde quiser (regra principal) / jogue ali se houver espaço (a regra do primeiro artigo; está provado que o primeiro jogador vence)\n② Um tabuleiro pequeno empatado: não é de ninguém (regra principal) / conta para os dois\n③ Sem linha no tabuleiro grande no fim: empate (regra principal) / vence quem tiver mais tabuleiros","ls.title":"Lições","ls.desc":"«Primeiros passos» para quem acabou de aprender as regras e «Estratégia» para vencer. Cada etapa: um aquecimento e depois 5 problemas de 20 pontos; 75 para passar.","course.basics":"Primeiros passos","course.basics.sub":"Ganhar um tabuleiro, bloquear, escolher o destino, vencer no tabuleiro grande.","course.strategy":"Estratégia","course.strategy.sub":"Ver para onde a captura envia, usar uma jogada livre, calcular os envios até vencer.","course.graduate":"🎉 «Primeiros passos» concluído! Você já pode jogar — experimente primeiro a IA nos níveis Lv.1–6.","ls.anywhere":"uma jogada livre","ls.ng.miss":"{x} não faz três em linha neste tabuleiro.","ls.ng.missBig":"{x} não faz três em linha no tabuleiro grande.","ls.ng.lose":"Depois de {x}, o adversário joga {r} e vence com três em linha no tabuleiro grande.","ls.ng.take":"Depois de {x} o adversário vai ao tabuleiro {t} e ganha o tabuleiro {tb} com {r}.","ls.ng.takeFree":"{x} envia a um tabuleiro decidido: o adversário joga onde quiser e ganha o tabuleiro {tb} com {r}.","ls.ng.free":"{x} envia a um tabuleiro decidido, então o adversário pode jogar onde quiser.","ls.ng.slow":"Depois de {x} o adversário resiste com {r}, e você não faz três em linha em mais {n} jogadas.","ls.ng.ok":"{x} não é ruim, mas há uma jogada melhor aqui.","ls.ng.ans":"A resposta é {m}.","ls.b_take.title":"Ganhar um tabuleiro pequeno","ls.b_take.sub":"Faça a terceira marca","ls.b_take.intro":"<p>Se duas marcas suas estão em linha num tabuleiro pequeno e a terceira casa está vazia, jogar ali ganha esse tabuleiro. Procure essa linha no tabuleiro onde você pode jogar (o que brilha).</p>","ls.b_take.goal":"Jogue a casa que ganha um tabuleiro pequeno.","ls.b_take.hint":"No tabuleiro que brilha, encontre uma linha com duas marcas suas.","ls.b_take.why":"{m} ganha o tabuleiro {b}!","ls.b_take.ex.t":"A terceira da linha","ls.b_take.ex.b":"O tabuleiro que brilha tem uma linha com duas marcas suas. Jogar a terceira, {m}, ganha o tabuleiro.","ls.b_block.title":"Bloquear a terceira dele","ls.b_block.sub":"Defenda antes de perder","ls.b_block.intro":"<p>Se o adversário tem duas em linha no tabuleiro onde você joga, bloquear a terceira casa é a defesa básica. Senão, ele o ganha assim que for enviado para lá (ou tiver uma jogada livre).</p>","ls.b_block.goal":"Jogue a jogada que defende este tabuleiro.","ls.b_block.hint":"No tabuleiro que brilha, onde há duas marcas do adversário em linha?","ls.b_block.why":"{m} bloqueia a terceira casa dele. O adversário vai ao tabuleiro {t} e não pode ganhar um tabuleiro na hora.","ls.b_block.ex.t":"Bloqueie a terceira","ls.b_block.ex.b":"O adversário tem duas em linha no tabuleiro que brilha. Bloquear a terceira, {m}, deixa o tabuleiro seguro por enquanto.","ls.b_send.title":"Escolher o destino","ls.b_send.sub":"Não entregue nada","ls.b_send.intro":"<p>A casa que você joga decide o próximo tabuleiro do adversário. Enviá-lo a um tabuleiro onde ele tem duas em linha deixa que o ganhe. Antes de jogar, confira qual tabuleiro é seguro.</p>","ls.b_send.goal":"Jogue algo que não entregue nenhum tabuleiro pequeno.","ls.b_send.hint":"Os tabuleiros que brilham em vermelho têm duas em linha do adversário. Qual casa não o envia para lá?","ls.b_send.why":"Com {m} o adversário vai ao tabuleiro {t} e lá não pode ganhar um tabuleiro na hora.","ls.b_send.ex.t":"Confira o destino","ls.b_send.ex.b":"A jogada vermelha envia o adversário a um tabuleiro com duas em linha dele, e ele o ganha. A verde, {m}, o envia aonde ele não pode.","ls.b_big.title":"Três em linha no tabuleiro grande","ls.b_big.sub":"Feche a partida","ls.b_big.intro":"<p>Quando dois tabuleiros ganhos seus estão em linha no tabuleiro grande, ganhar o terceiro vence a partida. Várias jogadas podem ganhar um tabuleiro pequeno, mas só a terceira dessa linha vence.</p>","ls.b_big.goal":"Vença a partida com esta jogada.","ls.b_big.hint":"O tabuleiro tracejado está a um de fazer três em linha no tabuleiro grande. Que jogada o ganha?","ls.b_big.why":"{m} ganha o tabuleiro {b}: três em linha no tabuleiro grande. Você venceu!","ls.b_big.ex.t":"O terceiro do tabuleiro grande","ls.b_big.ex.b":"Ganhe o terceiro tabuleiro de uma linha de dois no tabuleiro grande (o tracejado) e a partida é sua. {m} faz isso.","ls.s_look.title":"Olhe antes de pegar","ls.s_look.sub":"A armadilha do tabuleiro entregue","ls.s_look.intro":"<p>Uma jogada pode ganhar um tabuleiro pequeno e mesmo assim enviar o adversário a um bom lugar. Confira para onde a casa vencedora envia e escolha a jogada que não entrega nada.</p>","ls.s_look.goal":"Jogue a melhor jogada (ganhar um tabuleiro nem sempre é ela).","ls.s_look.hint":"Os tabuleiros que brilham em vermelho têm duas em linha do adversário. Para onde a jogada que ganha o envia?","ls.s_look.why":"Com {m} o adversário vai ao tabuleiro {t} e não pode ganhar um tabuleiro na hora. Aqui o destino importava mais que o tabuleiro à sua frente.","ls.s_look.ex.t":"Pegar o enviaria","ls.s_look.ex.b":"A jogada vermelha ganha um tabuleiro, mas envia o adversário a um tabuleiro com duas em linha dele. A verde, {m}, que o envia a um lugar seguro, é a certa.","ls.s_free.title":"Usar uma jogada livre","ls.s_free.sub":"Vá aonde importa","ls.s_free.intro":"<p>Uma jogada livre é uma grande chance. Jogue no tabuleiro que importa no tabuleiro grande — o que faria três em linha para qualquer um dos lados.</p>","ls.s_free.goal":"Você pode jogar onde quiser. Faça a jogada mais importante.","ls.s_free.hint":"Os tabuleiros tracejados são os tabuleiros-chave do tabuleiro grande. O que você pode fazer lá?","ls.s_free.why":"{m} vai ao tabuleiro-chave do tabuleiro grande, o tabuleiro {b}.","ls.s_free.ex.t":"Escolha o tabuleiro-chave","ls.s_free.ex.b":"Uma jogada livre deixa você escolher o tabuleiro-chave do tabuleiro grande (tracejado). {m} é essa jogada.","ls.s_force2.title":"Vencer em 2","ls.s_force2.sub":"Calcule os envios","ls.s_force2.intro":"<p>Envie o adversário a um tabuleiro onde qualquer jogada dele permita que sua próxima jogada complete três em linha no tabuleiro grande. Confira cada casa dele e para onde ela envia você.</p>","ls.s_force2.goal":"Faça três em linha no tabuleiro grande em 2 jogadas.","ls.s_force2.hint":"Encontre um tabuleiro para enviá-lo onde todas as respostas dele levem à sua vitória.","ls.s_force2.why":"{m} é a jogada vencedora: responda o que responder, sua próxima jogada completa três em linha.","ls.s_force2.ex.t":"Envie e vença","ls.s_force2.ex.b":"Depois da verde, {m}, cada resposta do adversário envia você a um tabuleiro onde você vence.","ls.s_force3.title":"Vencer em 3","ls.s_force3.sub":"Forçar no final","ls.s_force3.intro":"<p>No final, os envios decidem a partida. Reduza as opções do adversário a cada jogada e calcule o caminho até três em linha em 3 jogadas.</p>","ls.s_force3.goal":"Faça três em linha no tabuleiro grande em 3 jogadas.","ls.s_force3.hint":"Confira em ordem: jogadas que ganham um tabuleiro, jogadas que não entregam nada, jogadas que não dão jogada livre.","ls.s_force3.why":"A partir de {m} você vence em 3 jogadas.","ls.s_force3.ex.t":"Calcular 3 jogadas","ls.s_force3.ex.b":"A partir da verde, {m}, responda a cada réplica mandando-o de volta e vença no tabuleiro grande em 3.","pz.title":"Problemas de jogo da velha supremo","pz.desc":"Faça três em linha no tabuleiro grande dentro do número de jogadas. O adversário defende com a maior teimosia. Toda solução é provada pelo motor.","pz.winIn":"Vença em {n}","pz.goal":"Vez de {c}: três em linha no tabuleiro grande em {n} jogadas","pz.start":"Faça sua primeira jogada.","pz.best":"A resposta era {b}.","pz.solvedSub":"Três em linha no tabuleiro grande em {n} jogadas.","pz.hint1":"Faltam {n} jogadas. Veja o que o adversário pode fazer no tabuleiro para onde você o envia.","pz.hintText":"Uma jogada vencedora começa no tabuleiro tracejado.","pz.reply":"O adversário joga {m}. Faltam {n} jogadas.","pz.retry":"Tentar de novo","pz.grpWin":"Vença em N","pz.grpWinSub":"Faça três em linha no tabuleiro grande nas jogadas dadas, contra a defesa mais teimosa.","pz.grpTac":"Temas","pz.grpTacSub":"Vencer pelo envio · vencer a partir de uma jogada livre. Só ganhar tabuleiros não resolve.","pz.th.w1":"Vença em 1","pz.th.w1.sub":"Entre as jogadas que ganham um tabuleiro pequeno, encontre a que vence a partida.","pz.th.w2":"Vença em 2","pz.th.w2.sub":"Leia a resposta dele e complete a linha com sua segunda jogada.","pz.th.w3":"Vença em 3","pz.th.w3.sub":"Calcule a defesa dele e vença em 3 jogadas.","pz.th.w4":"Vença em 4","pz.th.w4.sub":"Longas trocas de envios: reduza as opções dele e encurrale-o.","pz.th.send":"Vencer pelo envio","pz.th.send.sub":"A primeira jogada não ganha nenhum tabuleiro: para onde ela envia o adversário decide a partida.","pz.th.free":"Vencer a partir de uma jogada livre","pz.th.free.sub":"Você pode jogar onde quiser — escolha a jogada que leva à vitória.","pz.why.last":"{m} não fez três em linha no tabuleiro grande.","pz.why.took":"O adversário ganhou o tabuleiro {b} com {r} e enviou você ao tabuleiro {t}. Não dá para vencer em mais {n} jogadas.","pz.why.far":"O adversário resistiu com {r} e enviou você ao tabuleiro {t}. Não há três em linha em mais {n} jogadas.","pz.why.answer":"Toque em «Resposta» para ver a solução.","rv.note":"Erro = jogada que virou uma vitória ou um empate, ou perdeu muito. Duvidosa = uma perda clara. Os números no tabuleiro são o valor de jogar em cada casa.","cr.forced":"A única casa possível.","cr.first":"A primeira jogada. <b>{b}</b> era um começo um pouco melhor.","cr.firstOk":"A primeira jogada — um bom começo.","cr.won":"A jogada vencedora: três em linha no tabuleiro grande.","cr.best":"A melhor jogada.","cr.bestTake":"A melhor jogada — ganhou o tabuleiro {t}.","cr.good":"Nada mal (a melhor era <b>{b}</b>, só um pouco melhor).","cr.gen":"Isso piorou a posição ({d}). A melhor era <b>{b}</b>.","cr.missWin":"Você perdeu a vitória: <b>{b}</b> fazia três em linha no tabuleiro grande.","cr.allowWin":"Depois disso o adversário vence com {r}, três em linha no tabuleiro grande. <b>{b}</b> impedia.","cr.gift":"Isso enviou o adversário ao tabuleiro {t}, onde {r} lhe dá o tabuleiro {tb}. <b>{b}</b> não entregava nada.","cr.free":"Isso enviou a um tabuleiro decidido, então o adversário podia jogar onde quisesse. <b>{b}</b> o mantinha num tabuleiro.","cr.missTake":"Você deixou de ganhar o tabuleiro {tb}. A melhor era <b>{b}</b>.","cr.tookBad":"Você ganhou um tabuleiro, mas o destino do adversário o ajudou. A melhor era <b>{b}</b>.","cr.tip.take":"💡 Tabuleiros que você pode ganhar importam — mas a casa vencedora decide para onde vai o adversário.","cr.tip.send":"💡 Antes de jogar, procure duas em linha dele no tabuleiro para onde você o envia.","cr.tip.free":"💡 Enviar a um tabuleiro decidido deixa o adversário escolher o tabuleiro que mais importa.","cr.tip.look":"💡 Confira para onde uma jogada que ganha envia. Às vezes o tabuleiro grande importa mais que o pequeno.","cr.tip.gen":"💡 A seta no tabuleiro é a melhor jogada; os números são o valor de jogar em cada casa."},
"de":{"meta.title":"Ultimate Tic-Tac-Toe — Großer Brettspiel-Atlas","title":"Ultimate Tic-Tac-Toe","sub":"","p1":"X","p2":"O","ng.first":"Anziehend (X)","ng.second":"Nachziehend (O)","ng.level1":"KI-Stärke X","ng.level2":"KI-Stärke O","pcs":"Felder","hb.free":"Freie Wahl","hb.to":"Geschickt: {b}","hb.var":"Regelvariante","rsv.won":"Gewonnene Felder {n}","rsv.free":"frei","rsv.title":"{c}: {n} kleine Felder gewonnen (drei in einer Reihe gewinnen)","send.first":"X am Zug: beliebiges Kästchen","send.free":"Du darfst in jedes kleine Feld setzen","send.to":"Setze in das leuchtende Feld ({b})","bname":["oben links","oben","oben rechts","links","Mitte","rechts","unten links","unten","unten rechts"],"cant.taken":"Dieses Kästchen ist schon besetzt","cant.closed":"Dieses kleine Feld ist schon entschieden","cant.board":"Setze in das leuchtende Feld ({b})","opt.send":"Pfeil zum nächsten Feld","opt.num":"Koordinaten","ng.rules":"Regeln","var.help":"Regeln ansehen","var.fc":"In ein entschiedenes Feld geschickt","var.fc0":"Überall setzen","var.fc1":"Dort, falls Platz frei","var.tie":"Ein unentschiedenes kleines Feld","var.tie0":"Gehört niemandem","var.tie1":"Zählt für beide","var.cnt":"Keine Reihe auf dem großen Feld","var.cnt0":"Remis","var.cnt1":"Mehr Felder gewinnt","var.std":"Die heute meistgespielte Regel (gewertete Partien, Lektionen und Rätsel nutzen sie auch).","var.custom":"Eine Partie mit geänderten Regeln. Die KI spielt jede Variante; gewertete Partien, Lektionen und Rätsel bleiben bei der Hauptregel.","lvd":["Anfänger: sieht nur die Reihe vor sich","Neuling–Mittel: liest, wohin seine Züge dich schicken","Fortgeschritten: wägt den Kampf um die kleinen Felder ab","Experte: liest tief ins große Feld"],"lvd.top":"Benchmark: die stärkste Suche, lange pro Zug (keine Belohnung)","bd.title":"Brett","bd.walnut":"Nussbaum & Messing","bd.slate":"Schiefertafel","bd.washi":"Washi & Sumi","bd.parchment":"Altes Papier & Tinte","bd.marble":"Marmor & Gold","bd.cherry":"Kirsche & Ebenholz","pcs.title":"X- und O-Zeichen","pcs.token":"Lack & Elfenbein","pcs.brush":"Sumi- & Zinnoberpinsel","pcs.chalk":"Kreide","pcs.ink":"Feder & Tinte","res.why.line":"Drei kleine Felder in einer Reihe auf dem großen Feld","res.why.count":"Keine Reihe auf dem großen Feld – entschieden nach gewonnenen Feldern","res.why.full":"Kein Kästchen mehr frei (keine Reihe auf dem großen Feld)","dr.none":"","intro.t":"Was ist Ultimate Tic-Tac-Toe?","intro.origin":"Unbekannt (als Papier-und-Bleistift-Spiel verbreitet)","intro.players":"2","intro.time":"10–20 Min.","intro.hist":"Ein Tic-Tac-Toe, in dessen Kästchen jeweils ein kleineres Tic-Tac-Toe steckt. Ben Orlin sah Mathematiker es bei einem Picknick spielen und schrieb 2013 in seinem Blog „Math with Bad Drawings“ darüber – dadurch wurde es bekannt.","intro.win":"Drei in einer Reihe auf einem kleinen Feld gewinnen dieses Feld. <b>Drei gewonnene Felder in einer Reihe auf dem großen Feld gewinnen die Partie.</b> Kann niemand mehr setzen, ist es remis.","intro.cult":"Normales Tic-Tac-Toe endet immer remis, doch hier bestimmt dein Kästchen, wo der Gegner als Nächstes setzt – das macht das Spiel tief: ein Liebling der KI-Forschung und von Programmierwettbewerben.","tr.board.t":"Das Brett: neun kleine Spiele","tr.board.b":"In jedem der 9 Felder des großen Bretts liegt ein 3 × 3 großes <b>kleines Feld</b> (81 Kästchen insgesamt).\nDrei in einer Reihe auf einem kleinen Feld gewinnen es und setzen ein großes Zeichen darauf.","tr.first.t":"Der erste Zug","tr.first.b":"X beginnt. Nur der allererste Zug darf <b>irgendwohin</b> unter den 81 Kästchen.","tr.first.task":"Setze ein X in ein beliebiges Kästchen","tr.first.ok":"Geschafft! Jetzt ist O am Zug.","tr.send.t":"Dein Kästchen schickt den Gegner","tr.send.b":"X hat das <b>Kästchen oben rechts</b> im mittleren Feld gespielt, also muss O im <b>Feld oben rechts</b> setzen.\nDas gespielte Kästchen = das Feld, in dem der Gegner als Nächstes setzt.","tr.send.task":"Setze ein O in das leuchtende Feld","tr.send.ok":"Genau! Jetzt bestimmt das Kästchen von O, wohin X geht.","tr.pick.t":"Wohin den Gegner schicken","tr.pick.b":"Welches Kästchen du wählst, bestimmt <b>das nächste Feld des Gegners</b>.\nDas ist der Kern der Strategie.","tr.pick.task":"Spiele das X, das O ins <b>Feld oben rechts</b> schickt","tr.pick.ok":"O muss nach oben rechts. Du hast das Ziel gewählt!","tr.pick.ng":"Dieses Kästchen schickt O woandershin. Nimm das Kästchen oben rechts im leuchtenden Feld.","tr.small.t":"Ein kleines Feld gewinnen","tr.small.b":"Drei in einer Reihe auf einem kleinen Feld – waagerecht, senkrecht oder diagonal – <b>gewinnen dieses Feld</b>.\nIn ein gewonnenes Feld setzt niemand mehr.","tr.small.task":"Bilde drei X in einer Reihe und gewinne das Feld","tr.small.ok":"Kleines Feld gewonnen!","tr.small.ng":"Noch keine Dreierreihe. Vervollständige die Reihe aus zwei X.","tr.free.t":"In ein entschiedenes Feld geschickt","tr.free.b":"Ist das Feld, in das du geschickt wirst, schon gewonnen (oder voll), <b>darfst du in jedes offene Feld setzen</b>.\nGib diese Freiheit dem Gegner möglichst nicht.","tr.free.task":"Setze ein X in ein beliebiges leuchtendes Feld","tr.free.ok":"Ein freier Zug!","tr.big.t":"Drei Felder in einer Reihe gewinnen","tr.big.b":"Gewinne drei kleine Felder <b>in einer Reihe auf dem großen Brett</b> – waagerecht, senkrecht oder diagonal – und du gewinnst die Partie.","tr.big.task":"Gewinne dieses Feld für drei in einer Reihe","tr.big.ok":"Drei in einer Reihe auf dem großen Brett. X gewinnt!","tr.big.ng":"Noch nicht. Gewinne das Feld, das die dritte in der Reihe macht.","tr.draw.t":"Remis","tr.draw.b":"Ein kleines Feld, das ohne Reihe voll wird, <b>gehört niemandem</b> (grau).\nKann niemand mehr setzen und gibt es keine Reihe auf dem großen Brett, endet die Partie <b>remis</b>.","tr.vars.t":"Regelvarianten","tr.vars.b":"Diese Seite spielt die heute verbreitetste Regel. Im Dialog „Neue Partie“ kannst du drei Dinge ändern:\n① In ein entschiedenes Feld geschickt: überall setzen (Hauptregel) / dort setzen, falls Platz frei (die Regel des ersten Artikels; Gewinn für den Anziehenden bewiesen)\n② Ein unentschiedenes kleines Feld: gehört niemandem (Hauptregel) / zählt für beide\n③ Am Ende keine Reihe auf dem großen Brett: remis (Hauptregel) / mehr gewonnene Felder gewinnen","ls.title":"Lektionen","ls.desc":"„Erste Schritte“ für alle, die gerade die Regeln gelernt haben, und „Strategie“ zum Gewinnen. Jede Stufe: ein Aufwärmen, dann 5 Aufgaben zu je 20 Punkten; 75 zum Bestehen.","course.basics":"Erste Schritte","course.basics.sub":"Ein Feld gewinnen, blockieren, das Ziel wählen, auf dem großen Brett gewinnen.","course.strategy":"Strategie","course.strategy.sub":"Erst schauen, wohin ein Gewinn schickt, freie Züge nutzen, das Hin- und Herschicken durchrechnen.","course.graduate":"🎉 „Erste Schritte“ geschafft! Du kannst jetzt spielen – probiere zuerst die KI auf Lv.1–6.","ls.anywhere":"freie Wahl","ls.ng.miss":"{x} bildet auf diesem Feld keine Dreierreihe.","ls.ng.missBig":"{x} bildet auf dem großen Brett keine Dreierreihe.","ls.ng.lose":"Nach {x} spielt der Gegner {r} und gewinnt mit drei in einer Reihe auf dem großen Brett.","ls.ng.take":"Nach {x} kommt der Gegner ins Feld {t} und gewinnt mit {r} das Feld {tb}.","ls.ng.takeFree":"{x} schickt in ein entschiedenes Feld: Der Gegner setzt, wo er will, und gewinnt mit {r} das Feld {tb}.","ls.ng.free":"{x} schickt in ein entschiedenes Feld, also darf der Gegner überall setzen.","ls.ng.slow":"Nach {x} hält der Gegner mit {r} stand, und in {n} weiteren Zügen gelingt dir keine Dreierreihe.","ls.ng.ok":"{x} ist nicht schlecht, aber hier gibt es einen besseren Zug.","ls.ng.ans":"Die Lösung ist {m}.","ls.b_take.title":"Ein kleines Feld gewinnen","ls.b_take.sub":"Das dritte Zeichen","ls.b_take.intro":"<p>Stehen zwei deiner Zeichen in einer Reihe auf einem kleinen Feld und ist das dritte Kästchen frei, gewinnt ein Zug dorthin das Feld. Suche so eine Reihe in dem Feld, in dem du setzen darfst (dem leuchtenden).</p>","ls.b_take.goal":"Setze in das Kästchen, das ein kleines Feld gewinnt.","ls.b_take.hint":"Finde im leuchtenden Feld eine Reihe mit zwei deiner Zeichen.","ls.b_take.why":"{m} gewinnt das Feld {b}!","ls.b_take.ex.t":"Das Dritte einer Reihe","ls.b_take.ex.b":"Im leuchtenden Feld liegt eine Reihe mit zwei deiner Zeichen. Das dritte, {m}, gewinnt das Feld.","ls.b_block.title":"Sein Drittes blockieren","ls.b_block.sub":"Verteidigen, bevor es fällt","ls.b_block.intro":"<p>Hat der Gegner zwei in einer Reihe im Feld, in dem du setzt, ist das Blockieren des dritten Kästchens die Grundverteidigung. Sonst gewinnt er das Feld, sobald er dorthin geschickt wird (oder freie Wahl hat).</p>","ls.b_block.goal":"Spiele den Zug, der dieses Feld verteidigt.","ls.b_block.hint":"Wo stehen im leuchtenden Feld zwei Zeichen des Gegners in einer Reihe?","ls.b_block.why":"{m} blockiert sein drittes Kästchen. Der Gegner kommt ins Feld {t} und kann nicht sofort ein Feld gewinnen.","ls.b_block.ex.t":"Das Dritte blockieren","ls.b_block.ex.b":"Der Gegner hat zwei in einer Reihe im leuchtenden Feld. Das dritte, {m}, zu blockieren hält das Feld vorerst sicher.","ls.b_send.title":"Das Ziel wählen","ls.b_send.sub":"Nichts verschenken","ls.b_send.intro":"<p>Dein Kästchen bestimmt das nächste Feld des Gegners. Schickst du ihn in ein Feld mit seiner Zweierreihe, gewinnt er es. Prüfe vor dem Setzen, welches Feld sicher ist.</p>","ls.b_send.goal":"Spiele einen Zug, der kein kleines Feld verschenkt.","ls.b_send.hint":"Die rot leuchtenden Felder enthalten eine Zweierreihe des Gegners. Welches Kästchen schickt ihn nicht dorthin?","ls.b_send.why":"Mit {m} kommt der Gegner ins Feld {t} und kann dort nicht sofort ein Feld gewinnen.","ls.b_send.ex.t":"Das Ziel prüfen","ls.b_send.ex.b":"Der rote Zug schickt den Gegner in ein Feld mit seiner Zweierreihe, und er gewinnt es. Der grüne, {m}, schickt ihn dorthin, wo er es nicht kann.","ls.b_big.title":"Drei auf dem großen Brett","ls.b_big.sub":"Die Partie beenden","ls.b_big.intro":"<p>Stehen zwei deiner gewonnenen Felder in einer Reihe auf dem großen Brett, gewinnt das dritte die Partie. Mehrere Züge können ein kleines Feld gewinnen, aber nur das dritte dieser Reihe gewinnt.</p>","ls.b_big.goal":"Gewinne die Partie mit diesem Zug.","ls.b_big.hint":"Das gestrichelte Feld fehlt zur Dreierreihe auf dem großen Brett. Welcher Zug gewinnt es?","ls.b_big.why":"{m} gewinnt das Feld {b} – drei in einer Reihe auf dem großen Brett. Gewonnen!","ls.b_big.ex.t":"Das Dritte auf dem großen Brett","ls.b_big.ex.b":"Gewinne das dritte Feld einer Zweierreihe auf dem großen Brett (das gestrichelte), und die Partie gehört dir. {m} schafft das.","ls.s_look.title":"Erst schauen, dann nehmen","ls.s_look.sub":"Die Falle des geschenkten Feldes","ls.s_look.intro":"<p>Ein Zug kann ein kleines Feld gewinnen und den Gegner trotzdem an einen guten Ort schicken. Prüfe, wohin das gewinnende Kästchen schickt, und wähle den Zug, der nichts verschenkt.</p>","ls.s_look.goal":"Spiele den besten Zug (ein Feld zu gewinnen ist es nicht immer).","ls.s_look.hint":"Die rot leuchtenden Felder enthalten eine Zweierreihe des Gegners. Wohin schickt der gewinnende Zug?","ls.s_look.why":"Mit {m} kommt der Gegner ins Feld {t} und kann nicht sofort ein Feld gewinnen. Hier zählte das Ziel mehr als das Feld vor dir.","ls.s_look.ex.t":"Nehmen würde ihn schicken","ls.s_look.ex.b":"Der rote Zug gewinnt ein Feld, schickt den Gegner aber in ein Feld mit seiner Zweierreihe. Der grüne, {m}, schickt ihn an einen sicheren Ort und ist richtig.","ls.s_free.title":"Freie Wahl nutzen","ls.s_free.sub":"Dorthin, wo es zählt","ls.s_free.intro":"<p>Eine freie Wahl ist eine große Chance. Setze in das Feld, das auf dem großen Brett zählt – das eine Dreierreihe für eine der beiden Seiten machen würde.</p>","ls.s_free.goal":"Du darfst überall setzen. Spiele den wichtigsten Zug.","ls.s_free.hint":"Die gestrichelten Felder sind die Schlüsselfelder des großen Bretts. Was kannst du dort tun?","ls.s_free.why":"{m} geht ins Schlüsselfeld des großen Bretts, das Feld {b}.","ls.s_free.ex.t":"Das Schlüsselfeld wählen","ls.s_free.ex.b":"Eine freie Wahl erlaubt dir, das Schlüsselfeld des großen Bretts (gestrichelt) zu wählen. {m} ist dieser Zug.","ls.s_force2.title":"Gewinn in 2","ls.s_force2.sub":"Das Schicken durchrechnen","ls.s_force2.intro":"<p>Schicke den Gegner in ein Feld, in dem jeder seiner Züge deinem nächsten Zug die Dreierreihe auf dem großen Brett erlaubt. Prüfe jedes seiner Kästchen und wohin es dich schickt.</p>","ls.s_force2.goal":"Bilde in 2 Zügen drei in einer Reihe auf dem großen Brett.","ls.s_force2.hint":"Finde ein Feld, in das du ihn schickst, sodass alle seine Antworten zu deinem Sieg führen.","ls.s_force2.why":"{m} ist der Gewinnzug: Was er auch antwortet, dein nächster Zug vollendet die Reihe.","ls.s_force2.ex.t":"Schicken und gewinnen","ls.s_force2.ex.b":"Nach dem grünen {m} schickt jede Antwort des Gegners dich in ein Feld, in dem du gewinnst.","ls.s_force3.title":"Gewinn in 3","ls.s_force3.sub":"Zwingen im Endspiel","ls.s_force3.intro":"<p>Im Endspiel entscheidet das Schicken. Engen die Wahl des Gegners mit jedem Zug ein und rechne den Weg zur Dreierreihe in 3 Zügen durch.</p>","ls.s_force3.goal":"Bilde in 3 Zügen drei in einer Reihe auf dem großen Brett.","ls.s_force3.hint":"Prüfe der Reihe nach: Züge, die ein Feld gewinnen, Züge, die nichts verschenken, Züge, die keine freie Wahl geben.","ls.s_force3.why":"Ab {m} gewinnst du in 3 Zügen.","ls.s_force3.ex.t":"3 Züge rechnen","ls.s_force3.ex.b":"Ab dem grünen {m} schickst du ihn auf jede Antwort zurück und gewinnst auf dem großen Brett in 3.","pz.title":"Ultimate-Tic-Tac-Toe-Rätsel","pz.desc":"Bilde in der vorgegebenen Zahl von Zügen drei in einer Reihe auf dem großen Brett. Der Gegner verteidigt sich so zäh wie möglich. Jede Lösung ist von der Engine bewiesen.","pz.winIn":"Gewinn in {n}","pz.goal":"{c} am Zug: drei in einer Reihe auf dem großen Brett in {n} Zügen","pz.start":"Spiele deinen ersten Zug.","pz.best":"Die Lösung war {b}.","pz.solvedSub":"Drei in einer Reihe auf dem großen Brett in {n} Zügen.","pz.hint1":"Noch {n} Züge. Prüfe, was der Gegner in dem Feld tun kann, in das du ihn schickst.","pz.hintText":"Ein Gewinnzug beginnt im gestrichelten Feld.","pz.reply":"Der Gegner spielt {m}. Noch {n} Züge.","pz.retry":"Neu versuchen","pz.grpWin":"Gewinn in N","pz.grpWinSub":"Bilde gegen die zäheste Verteidigung in den gegebenen Zügen drei in einer Reihe auf dem großen Brett.","pz.grpTac":"Themen","pz.grpTacSub":"Gewinnen durch Schicken · gewinnen aus freier Wahl. Felder nehmen allein löst sie nicht.","pz.th.w1":"Gewinn in 1","pz.th.w1.sub":"Finde unter den Zügen, die ein kleines Feld gewinnen, den, der die Partie gewinnt.","pz.th.w2":"Gewinn in 2","pz.th.w2.sub":"Lies seine Antwort und vollende die Reihe mit deinem zweiten Zug.","pz.th.w3":"Gewinn in 3","pz.th.w3.sub":"Rechne seine Verteidigung durch und gewinne in 3 Zügen.","pz.th.w4":"Gewinn in 4","pz.th.w4.sub":"Lange Schick-Duelle: Enge seine Wahl ein und treibe ihn in die Enge.","pz.th.send":"Gewinnen durch Schicken","pz.th.send.sub":"Der erste Zug gewinnt kein Feld: Wohin er den Gegner schickt, entscheidet.","pz.th.free":"Gewinnen aus freier Wahl","pz.th.free.sub":"Du darfst überall setzen – wähle den Zug, der zum Sieg führt.","pz.why.last":"{m} bildete keine Dreierreihe auf dem großen Brett.","pz.why.took":"Der Gegner gewann mit {r} das Feld {b} und schickte dich ins Feld {t}. In {n} weiteren Zügen kein Gewinn.","pz.why.far":"Der Gegner hielt mit {r} stand und schickte dich ins Feld {t}. Keine Dreierreihe in {n} weiteren Zügen.","pz.why.answer":"Drücke „Lösung“, um sie zu sehen.","rv.note":"Fehler = ein Zug, der einen Sieg oder ein Remis gekippt oder viel verloren hat. Zweifelhaft = ein deutlicher Verlust. Die Zahlen auf dem Brett sind der Wert eines Zugs in jedes Kästchen.","cr.forced":"Das einzige spielbare Kästchen.","cr.first":"Der erste Zug. <b>{b}</b> war ein etwas besserer Beginn.","cr.firstOk":"Der erste Zug – ein guter Beginn.","cr.won":"Der Gewinnzug: drei in einer Reihe auf dem großen Brett.","cr.best":"Der beste Zug.","cr.bestTake":"Der beste Zug – er gewann das Feld {t}.","cr.good":"Nicht schlecht (am besten war <b>{b}</b>, nur wenig besser).","cr.gen":"Das hat die Stellung verschlechtert ({d}). Am besten war <b>{b}</b>.","cr.missWin":"Sieg verpasst: <b>{b}</b> bildete drei in einer Reihe auf dem großen Brett.","cr.allowWin":"Danach gewinnt der Gegner mit {r}, drei in einer Reihe auf dem großen Brett. <b>{b}</b> hätte es verhindert.","cr.gift":"Das schickte den Gegner ins Feld {t}, wo {r} ihm das Feld {tb} bringt. <b>{b}</b> verschenkte nichts.","cr.free":"Das schickte in ein entschiedenes Feld, also durfte der Gegner überall setzen. <b>{b}</b> hielt ihn in einem Feld.","cr.missTake":"Du hast den Gewinn des Feldes {tb} verpasst. Am besten war <b>{b}</b>.","cr.tookBad":"Du hast ein Feld gewonnen, aber das Ziel half dem Gegner. Am besten war <b>{b}</b>.","cr.tip.take":"💡 Gewinnbare Felder zählen – doch das gewinnende Kästchen bestimmt, wohin der Gegner geht.","cr.tip.send":"💡 Suche vor dem Setzen seine Zweierreihe im Feld, in das du ihn schickst.","cr.tip.free":"💡 Wer in ein entschiedenes Feld schickt, lässt den Gegner das wichtigste Feld wählen.","cr.tip.look":"💡 Prüfe, wohin ein gewinnender Zug schickt. Manchmal zählt das große Brett mehr als das kleine.","cr.tip.gen":"💡 Der Pfeil auf dem Brett ist der beste Zug; die Zahlen sind der Wert eines Zugs in jedes Kästchen."},
"ru":{"res.review":"К доске","meta.title":"Ультимативные крестики-нолики — Большой атлас настольных игр","title":"Ультимативные крестики-нолики","sub":"Ultimate Tic-Tac-Toe","p1":"X","p2":"O","ng.first":"Первый (X)","ng.second":"Второй (O)","ng.level1":"Сила ИИ первого (X)","ng.level2":"Сила ИИ второго (O)","pcs":"поля","hb.free":"Свободный ход","hb.to":"Куда: {b}","hb.var":"Вариант правил","rsv.won":"Выиграно полей {n}","rsv.free":"свободно","rsv.title":"{c}: выиграно малых полей {n} (три в ряд побеждают)","send.first":"Ход X: любая клетка","send.free":"Можно ходить в любое малое поле","send.to":"Ходите в светящееся поле ({b})","bname":["левое верхнее","верхнее","правое верхнее","левое","центральное","правое","левое нижнее","нижнее","правое нижнее"],"cant.taken":"Эта клетка уже занята","cant.closed":"Это малое поле уже решено","cant.board":"Ходите в светящееся поле ({b})","opt.send":"Стрелка к следующему полю","opt.num":"Координаты","ng.rules":"Правила","var.help":"Посмотреть правила","var.fc":"Отправлен в решённое поле","var.fc0":"Ход куда угодно","var.fc1":"Туда, если есть место","var.tie":"Малое поле вничью","var.tie0":"Ничьё","var.tie1":"Засчитывается обоим","var.cnt":"Нет ряда на большом поле","var.cnt0":"Ничья","var.cnt1":"У кого больше полей","var.std":"Самое распространённое сегодня правило (по нему же идут рейтинговые партии, уроки и задачи).","var.custom":"Партия с изменёнными правилами. ИИ играет любой вариант, а рейтинговые партии, уроки и задачи — по основному правилу.","lvd":["Новичок: видит только ряд перед собой","Начальный–средний: читает, куда отправляют его ходы","Продвинутый: взвешивает борьбу за малые поля","Эксперт: глубоко читает большое поле"],"lvd.top":"Тест производительности: сильнейший расчёт, долго на каждый ход (без наград)","bd.title":"Доска","bd.walnut":"Орех и латунь","bd.slate":"Грифельная доска","bd.washi":"Васи и тушь","bd.parchment":"Старая бумага и чернила","bd.marble":"Мрамор и золото","bd.cherry":"Вишня и эбен","pcs.title":"Знаки X и O","pcs.token":"Лак и слоновая кость","pcs.brush":"Кисть: тушь и киноварь","pcs.chalk":"Мел","pcs.ink":"Перо и чернила","res.why.line":"Три малых поля в ряд на большом поле","res.why.count":"Ряда на большом поле нет — решило число выигранных полей","res.why.full":"Ходить больше некуда (ряда на большом поле нет)","dr.none":"","intro.t":"Что такое ультимативные крестики-нолики?","intro.origin":"Неизвестно (распространились как игра на бумаге)","intro.players":"2","intro.time":"10–20 мин","intro.hist":"Крестики-нолики, в каждой клетке которых нарисованы маленькие крестики-нолики. Бен Орлин увидел, как в неё играют математики на пикнике, и в 2013 году рассказал о ней в блоге «Math with Bad Drawings» — так игра стала известной.","intro.win":"Три в ряд на малом поле выигрывают это поле. <b>Три выигранных поля в ряд на большом поле выигрывают партию.</b> Если ходить некуда — ничья.","intro.cult":"Обычные крестики-нолики всегда кончаются ничьёй, а здесь клетка вашего хода решает, где сходит соперник, — это делает игру глубокой: она любима исследователями ИИ и участниками конкурсов по программированию.","tr.board.t":"Доска: девять маленьких игр","tr.board.b":"В каждой из 9 клеток большого поля лежит <b>малое поле</b> 3 × 3 (всего 81 клетка).\nТри в ряд на малом поле выигрывают его, и на нём ставится большой знак.","tr.first.t":"Первый ход","tr.first.b":"Начинает X. Только самый первый ход можно сделать <b>в любую</b> из 81 клеток.","tr.first.task":"Поставьте X в любую клетку","tr.first.ok":"Готово! Теперь ход O.","tr.send.t":"Ваша клетка отправляет соперника","tr.send.b":"X сходил в <b>правую верхнюю клетку</b> центрального поля, поэтому O должен ходить в <b>правое верхнее поле</b>.\nКлетка вашего хода = поле, где соперник ходит следующим.","tr.send.task":"Поставьте O в светящееся поле","tr.send.ok":"Верно! Теперь клетка O решает, куда пойдёт X.","tr.pick.t":"Куда отправить соперника","tr.pick.b":"Выбранная клетка решает, <b>какое поле будет следующим у соперника</b>.\nЭто сердце стратегии.","tr.pick.task":"Сделайте ход X, отправляющий O в <b>правое верхнее поле</b>","tr.pick.ok":"O идёт в правое верхнее поле. Вы выбрали, куда отправить!","tr.pick.ng":"Эта клетка отправляет O в другое поле. Возьмите правую верхнюю клетку светящегося поля.","tr.small.t":"Выиграть малое поле","tr.small.b":"Три в ряд на малом поле — по горизонтали, вертикали или диагонали — <b>выигрывают это поле</b>.\nВ выигранное поле больше никто не ходит.","tr.small.task":"Поставьте три X в ряд и выиграйте поле","tr.small.ok":"Малое поле выиграно!","tr.small.ng":"Ряда из трёх пока нет. Достройте ряд из двух X.","tr.free.t":"Отправлен в решённое поле","tr.free.b":"Если поле, куда вас отправили, уже выиграно (или заполнено), <b>можно ходить в любое открытое поле</b>.\nСтарайтесь не давать сопернику такую свободу.","tr.free.task":"Поставьте X в любое светящееся поле","tr.free.ok":"Свободный ход!","tr.big.t":"Три поля в ряд побеждают","tr.big.b":"Выиграйте три малых поля <b>в ряд на большом поле</b> — по горизонтали, вертикали или диагонали — и партия ваша.","tr.big.task":"Выиграйте это поле, чтобы собрать три в ряд","tr.big.ok":"Три в ряд на большом поле. X победил!","tr.big.ng":"Пока нет. Выиграйте поле, которое станет третьим в ряду.","tr.draw.t":"Ничья","tr.draw.b":"Малое поле, заполненное без ряда, <b>ничьё</b> (серое).\nЕсли ходить некуда, а ряда на большом поле нет, партия заканчивается <b>вничью</b>.","tr.vars.t":"Варианты правил","tr.vars.b":"На сайте играют по самому распространённому сегодня правилу. В окне новой партии можно изменить три вещи:\n① Отправлен в решённое поле: ход куда угодно (основное правило) / туда, если есть место (правило первой статьи; доказана победа первого игрока)\n② Малое поле вничью: ничьё (основное правило) / засчитывается обоим\n③ В конце нет ряда на большом поле: ничья (основное правило) / побеждает тот, у кого больше полей","ls.title":"Уроки","ls.desc":"«Первые шаги» для тех, кто только выучил правила, и «Стратегия» для побед. Каждый шаг: разминка, затем 5 задач по 20 очков; для зачёта нужно 75.","course.basics":"Первые шаги","course.basics.sub":"Выиграть поле, заблокировать, выбрать, куда отправить, победить на большом поле.","course.strategy":"Стратегия","course.strategy.sub":"Смотреть, куда отправляет взятие, использовать свободный ход, просчитывать отправки до победы.","course.graduate":"🎉 «Первые шаги» пройдены! Можно играть — для начала попробуйте ИИ Lv.1–6.","ls.anywhere":"свободный ход","ls.ng.miss":"{x} не даёт трёх в ряд на этом поле.","ls.ng.missBig":"{x} не даёт трёх в ряд на большом поле.","ls.ng.lose":"После {x} соперник ходит {r} и побеждает тремя в ряд на большом поле.","ls.ng.take":"После {x} соперник попадает в {t} поле и ходом {r} выигрывает {tb} поле.","ls.ng.takeFree":"{x} отправляет в решённое поле: соперник ходит куда хочет и ходом {r} выигрывает {tb} поле.","ls.ng.free":"{x} отправляет в решённое поле, и соперник может ходить куда угодно.","ls.ng.slow":"После {x} соперник держится ходом {r}, и за {n} хода вам не собрать три в ряд.","ls.ng.ok":"{x} неплох, но здесь есть ход лучше.","ls.ng.ans":"Ответ: {m}.","ls.b_take.title":"Выиграть малое поле","ls.b_take.sub":"Третий знак","ls.b_take.intro":"<p>Если два ваших знака стоят в ряд на малом поле, а третья клетка свободна, ход туда выигрывает это поле. Ищите такой ряд в поле, где можно ходить (светящемся).</p>","ls.b_take.goal":"Сходите в клетку, которая выигрывает малое поле.","ls.b_take.hint":"В светящемся поле найдите ряд с двумя вашими знаками.","ls.b_take.why":"{m} выигрывает {b} поле!","ls.b_take.ex.t":"Третий в ряду","ls.b_take.ex.b":"В светящемся поле есть ряд с двумя вашими знаками. Ход в третью клетку, {m}, выигрывает поле.","ls.b_block.title":"Закрыть его третью клетку","ls.b_block.sub":"Защитить, пока не поздно","ls.b_block.intro":"<p>Если у соперника два в ряд в поле, где вы ходите, закрыть третью клетку — основная защита. Иначе он выиграет поле, как только его туда отправят (или у него будет свободный ход).</p>","ls.b_block.goal":"Сделайте ход, защищающий это поле.","ls.b_block.hint":"Где в светящемся поле стоят в ряд два знака соперника?","ls.b_block.why":"{m} закрывает его третью клетку. Соперник попадает в {t} поле и не может сразу выиграть поле.","ls.b_block.ex.t":"Закрыть третью","ls.b_block.ex.b":"У соперника два в ряд в светящемся поле. Закрыв третью клетку, {m}, вы пока сохраните поле.","ls.b_send.title":"Выбрать, куда отправить","ls.b_send.sub":"Ничего не дарить","ls.b_send.intro":"<p>Клетка вашего хода решает следующее поле соперника. Отправив его в поле с его двумя в ряд, вы дадите ему выиграть это поле. Перед ходом проверьте, какое поле безопасно.</p>","ls.b_send.goal":"Сделайте ход, который не дарит ни одного малого поля.","ls.b_send.hint":"В полях, светящихся красным, есть два в ряд соперника. Какая клетка не отправляет его туда?","ls.b_send.why":"После {m} соперник попадает в {t} поле и сразу выиграть поле там не может.","ls.b_send.ex.t":"Проверьте, куда отправляете","ls.b_send.ex.b":"Красный ход отправляет соперника в поле с его двумя в ряд, и он его выигрывает. Зелёный, {m}, отправляет туда, где он этого не сможет.","ls.b_big.title":"Три в ряд на большом поле","ls.b_big.sub":"Завершить партию","ls.b_big.intro":"<p>Если два ваших выигранных поля стоят в ряд на большом поле, третье выигрывает партию. Малое поле могут выиграть несколько ходов, но побеждает только третье поле этого ряда.</p>","ls.b_big.goal":"Выиграйте партию этим ходом.","ls.b_big.hint":"Пунктирному полю не хватает одного до трёх в ряд на большом поле. Какой ход его выигрывает?","ls.b_big.why":"{m} выигрывает {b} поле — три в ряд на большом поле. Победа!","ls.b_big.ex.t":"Третье на большом поле","ls.b_big.ex.b":"Выиграйте третье поле ряда из двух на большом поле (пунктирное) — и партия ваша. Это делает {m}.","ls.s_look.title":"Смотри, прежде чем брать","ls.s_look.sub":"Ловушка подаренного поля","ls.s_look.intro":"<p>Ход может выиграть малое поле и всё же отправить соперника в хорошее место. Проверьте, куда отправляет выигрывающая клетка, и выберите ход, который ничего не дарит.</p>","ls.s_look.goal":"Сделайте лучший ход (выиграть поле — не всегда он).","ls.s_look.hint":"В полях, светящихся красным, есть два в ряд соперника. Куда отправляет выигрывающий ход?","ls.s_look.why":"После {m} соперник попадает в {t} поле и не может сразу выиграть поле. Здесь важнее было, куда отправить, а не поле перед глазами.","ls.s_look.ex.t":"Взять — значит отправить","ls.s_look.ex.b":"Красный ход выигрывает поле, но отправляет соперника в поле с его двумя в ряд. Правильно — зелёный {m}, отправляющий в безопасное место.","ls.s_free.title":"Свободный ход","ls.s_free.sub":"Туда, где это важно","ls.s_free.intro":"<p>Свободный ход — большой шанс. Сходите в поле, важное для большого поля: то, что дало бы три в ряд одной из сторон.</p>","ls.s_free.goal":"Можно ходить куда угодно. Сделайте самый важный ход.","ls.s_free.hint":"Пунктирные поля — ключевые для большого поля. Что там можно сделать?","ls.s_free.why":"{m} — ход в ключевое поле большого поля, {b} поле.","ls.s_free.ex.t":"Выбрать ключевое поле","ls.s_free.ex.b":"Свободный ход позволяет выбрать ключевое поле большого поля (пунктир). Это ход {m}.","ls.s_force2.title":"Победа в 2 хода","ls.s_force2.sub":"Просчитать отправки","ls.s_force2.intro":"<p>Отправьте соперника в поле, где любой его ход позволит вашему следующему ходу собрать три в ряд на большом поле. Проверьте каждую его клетку и куда она отправит вас.</p>","ls.s_force2.goal":"Соберите три в ряд на большом поле за 2 хода.","ls.s_force2.hint":"Найдите поле, куда его отправить, чтобы все его ответы вели к вашей победе.","ls.s_force2.why":"{m} — победный ход: как бы он ни ответил, ваш следующий ход собирает три в ряд.","ls.s_force2.ex.t":"Отправить и победить","ls.s_force2.ex.b":"После зелёного {m} любой ответ соперника отправляет вас в поле, где вы побеждаете.","ls.s_force3.title":"Победа в 3 хода","ls.s_force3.sub":"Форсирование в эндшпиле","ls.s_force3.intro":"<p>В эндшпиле всё решают отправки. Каждым ходом сужайте выбор соперника и просчитайте путь к трём в ряд за 3 хода.</p>","ls.s_force3.goal":"Соберите три в ряд на большом поле за 3 хода.","ls.s_force3.hint":"Проверьте по порядку: ходы, выигрывающие поле; ходы, ничего не дарящие; ходы, не дающие свободного хода.","ls.s_force3.why":"С {m} вы побеждаете за 3 хода.","ls.s_force3.ex.t":"Расчёт на 3 хода","ls.s_force3.ex.b":"С зелёного {m} отвечайте на каждый ход, отправляя его обратно, и побеждайте на большом поле за 3.","pz.title":"Задачи: ультимативные крестики-нолики","pz.desc":"Соберите три в ряд на большом поле за заданное число ходов. Соперник защищается максимально упорно. Каждое решение доказано движком.","pz.winIn":"Победа в {n}","pz.goal":"Ход {c}: три в ряд на большом поле за {n} хода","pz.start":"Сделайте первый ход.","pz.best":"Ответ: {b}.","pz.solvedSub":"Три в ряд на большом поле за {n} хода.","pz.hint1":"Осталось ходов: {n}. Проверьте, что соперник может сделать в поле, куда вы его отправляете.","pz.hintText":"Победный ход начинается в пунктирном поле.","pz.reply":"Соперник ходит {m}. Осталось ходов: {n}.","pz.retry":"Заново","pz.grpWin":"Победа в N","pz.grpWinSub":"Соберите три в ряд на большом поле за данные ходы против самой упорной защиты.","pz.grpTac":"Темы","pz.grpTacSub":"Победа отправкой · победа со свободного хода. Одним взятием полей не решить.","pz.th.w1":"Победа в 1","pz.th.w1.sub":"Среди ходов, выигрывающих малое поле, найдите тот, что выигрывает партию.","pz.th.w2":"Победа в 2","pz.th.w2.sub":"Прочитайте его ответ и закончите ряд вторым ходом.","pz.th.w3":"Победа в 3","pz.th.w3.sub":"Просчитайте его защиту и победите за 3 хода.","pz.th.w4":"Победа в 4","pz.th.w4.sub":"Долгие отправки: сужайте его выбор и загоняйте в угол.","pz.th.send":"Победа отправкой","pz.th.send.sub":"Первый ход не выигрывает поля: всё решает, куда он отправит соперника.","pz.th.free":"Победа со свободного хода","pz.th.free.sub":"Можно ходить куда угодно — выберите ход, ведущий к победе.","pz.why.last":"{m} не дал трёх в ряд на большом поле.","pz.why.took":"Соперник ходом {r} выиграл {b} поле и отправил вас в {t} поле. За {n} хода не победить.","pz.why.far":"Соперник удержался ходом {r} и отправил вас в {t} поле. Трёх в ряд за {n} хода не будет.","pz.why.answer":"Нажмите «Ответ», чтобы увидеть решение.","rv.note":"Ошибка = ход, перевернувший победу или ничью, или потерявший много. Сомнительный = заметная потеря. Числа на доске — оценка хода в каждую клетку.","cr.forced":"Единственная возможная клетка.","cr.first":"Первый ход. <b>{b}</b> было чуть лучшим началом.","cr.firstOk":"Первый ход — хорошее начало.","cr.won":"Победный ход: три в ряд на большом поле.","cr.best":"Лучший ход.","cr.bestTake":"Лучший ход — выиграно {t} поле.","cr.good":"Неплохо (лучшим было <b>{b}</b>, лишь чуть-чуть лучше).","cr.gen":"Этот ход ухудшил позицию ({d}). Лучшим было <b>{b}</b>.","cr.missWin":"Победа упущена: <b>{b}</b> давал три в ряд на большом поле.","cr.allowWin":"После этого соперник побеждает ходом {r}, три в ряд на большом поле. <b>{b}</b> не допускал этого.","cr.gift":"Этот ход отправил соперника в {t} поле, где {r} приносит ему {tb} поле. <b>{b}</b> ничего не дарил.","cr.free":"Этот ход отправил в решённое поле, и соперник мог ходить куда угодно. <b>{b}</b> удерживал его в одном поле.","cr.missTake":"Вы упустили выигрыш поля: {tb}. Лучшим было <b>{b}</b>.","cr.tookBad":"Вы выиграли поле, но место, куда отправился соперник, помогло ему. Лучшим было <b>{b}</b>.","cr.tip.take":"💡 Поля, которые можно выиграть, важны — но выигрывающая клетка решает, куда пойдёт соперник.","cr.tip.send":"💡 Перед ходом ищите его два в ряд в поле, куда вы его отправляете.","cr.tip.free":"💡 Отправив в решённое поле, вы позволите сопернику выбрать самое важное поле.","cr.tip.look":"💡 Проверяйте, куда отправляет выигрывающий ход. Иногда большое поле важнее малого.","cr.tip.gen":"💡 Стрелка на доске — лучший ход; числа — оценка хода в каждую клетку."},
"tr":{"meta.title":"Ultimate Tic-Tac-Toe — Büyük Masa Oyunları Atlası","title":"Ultimate Tic-Tac-Toe","sub":"Süper XOX","p1":"X","p2":"O","ng.first":"İlk (X)","ng.second":"İkinci (O)","ng.level1":"İlk oyuncu (X) YZ gücü","ng.level2":"İkinci oyuncu (O) YZ gücü","pcs":"tahta","hb.free":"Serbest hamle","hb.to":"Gönderilen: {b}","hb.var":"Kural varyantı","rsv.won":"Kazanılan tahta {n}","rsv.free":"serbest","rsv.title":"{c}: kazanılan küçük tahta {n} (üçü bir sırada kazanır)","send.first":"X oynuyor: herhangi bir kareye koy","send.free":"Herhangi bir küçük tahtaya oynayabilirsin","send.to":"Parlayan tahtaya oyna ({b})","bname":["sol üst","üst","sağ üst","sol","orta","sağ","sol alt","alt","sağ alt"],"cant.taken":"O kare zaten dolu","cant.closed":"O küçük tahta zaten sonuçlandı","cant.board":"Parlayan tahtaya oyna ({b})","opt.send":"Sonraki tahta oku","opt.num":"Koordinatlar","ng.rules":"Kurallar","var.help":"Kuralları gör","var.fc":"Sonuçlanmış tahtaya gönderilince","var.fc0":"İstediğin yere","var.fc1":"Boş varsa oraya","var.tie":"Berabere biten küçük tahta","var.tie0":"Kimsenin değil","var.tie1":"İkisine de sayılır","var.cnt":"Büyük tahtada üçlü olmazsa","var.cnt0":"Beraberlik","var.cnt1":"Çok tahta alan kazanır","var.std":"Bugün en çok oynanan kural (dereceli oyunlar, dersler ve bulmacalar da bu kuralla).","var.custom":"Kuralları değiştirilmiş bir oyun. YZ her varyantı oynar; dereceli oyunlar, dersler ve bulmacalar ana kuralla kalır.","lvd":["Başlangıç: yalnızca önündeki sırayı görür","Acemi–orta: hamlelerinin seni nereye gönderdiğini okur","İleri: küçük tahta mücadelesini tartar","Uzman: büyük tahtayı derin okur"],"lvd.top":"Kıyaslama: en güçlü arama, her hamlede uzun düşünür (ödül yok)","bd.title":"Tahta","bd.walnut":"Ceviz ve pirinç","bd.slate":"Okul arduvazı","bd.washi":"Washi ve sumi","bd.parchment":"Eski kâğıt ve mürekkep","bd.marble":"Mermer ve altın","bd.cherry":"Kiraz ve abanoz","pcs.title":"X ve O işaretleri","pcs.token":"Lake ve fildişi","pcs.brush":"Sumi ve zencefre fırça","pcs.chalk":"Tebeşir","pcs.ink":"Kalem ve mürekkep","res.why.line":"Büyük tahtada üç küçük tahta bir sırada","res.why.count":"Büyük tahtada sıra yok — kazanılan tahta sayısı belirledi","res.why.full":"Oynanacak kare kalmadı (büyük tahtada sıra yok)","dr.none":"","intro.t":"Ultimate Tic-Tac-Toe nasıl bir oyun?","intro.origin":"Bilinmiyor (kâğıt-kalem oyunu olarak yayıldı)","intro.players":"2","intro.time":"10–20 dk","intro.hist":"Her karesinde daha küçük bir XOX bulunan bir XOX. Ben Orlin bir piknikte matematikçilerin oynadığını gördü ve 2013'te «Math with Bad Drawings» blogunda yazınca oyun yaygınlaştı.","intro.win":"Küçük bir tahtada üçlü yapan o tahtayı kazanır. <b>Kazanılan üç tahtayı büyük tahtada bir sıraya dizen oyunu kazanır.</b> Kimse oynayamazsa beraberlik olur.","intro.cult":"Sıradan XOX hep berabere biter; burada ise oynadığın kare rakibin nereye oynayacağını belirlediği için oyun derinleşir — YZ araştırmalarının ve programlama yarışmalarının sevilen konusudur.","tr.board.t":"Tahta: dokuz küçük oyun","tr.board.b":"Büyük tahtanın 9 karesinin her birinde 3 × 3'lük bir <b>küçük tahta</b> var (toplam 81 kare).\nKüçük tahtada üçlü yapan o tahtayı kazanır ve üstüne büyük bir işaret konur.","tr.first.t":"İlk hamle","tr.first.b":"X başlar. Yalnızca ilk hamle 81 karenin <b>herhangi birine</b> yapılabilir.","tr.first.task":"Herhangi bir kareye X koy","tr.first.ok":"Tamam! Şimdi sıra O'da.","tr.send.t":"Karen rakibi gönderir","tr.send.b":"X ortadaki tahtanın <b>sağ üst karesine</b> oynadı, bu yüzden O <b>sağ üst tahtaya</b> oynamalı.\nOynadığın kare = rakibin sonra oynayacağı tahta.","tr.send.task":"Parlayan tahtaya O koy","tr.send.ok":"Doğru! Şimdi O'nun karesi X'in nereye gideceğini belirliyor.","tr.pick.t":"Rakibi nereye göndermeli","tr.pick.b":"Seçtiğin kare <b>rakibin sonraki tahtasını</b> belirler.\nStratejinin kalbi budur.","tr.pick.task":"O'yu <b>sağ üst tahtaya</b> gönderen X'i koy","tr.pick.ok":"O sağ üst tahtaya gidiyor. Nereye göndereceğini seçtin!","tr.pick.ng":"O kare O'yu başka yere gönderiyor. Parlayan tahtanın sağ üst karesini kullan.","tr.small.t":"Küçük tahtayı kazanmak","tr.small.b":"Küçük tahtada yatay, dikey ya da çapraz üçlü <b>o tahtayı kazandırır</b>.\nKazanılmış tahtaya artık kimse oynamaz.","tr.small.task":"Üç X'i sıraya diz ve tahtayı kazan","tr.small.ok":"Küçük tahtayı kazandın!","tr.small.ng":"Henüz üçlü yok. İki X'lik sırayı tamamla.","tr.free.t":"Sonuçlanmış tahtaya gönderilince","tr.free.b":"Gönderildiğin tahta zaten kazanılmışsa (ya da doluysa) <b>açık olan herhangi bir tahtaya oynayabilirsin</b>.\nBu özgürlüğü rakibe vermemeye çalış.","tr.free.task":"Parlayan herhangi bir tahtaya X koy","tr.free.ok":"Serbest hamle!","tr.big.t":"Üç tahta bir sırada kazanır","tr.big.b":"Üç küçük tahtayı <b>büyük tahtada bir sıraya</b> — yatay, dikey ya da çapraz — dizersen oyunu kazanırsın.","tr.big.task":"Bu tahtayı kazanıp üçlüyü tamamla","tr.big.ok":"Büyük tahtada üçlü. X kazandı!","tr.big.ng":"Henüz değil. Sıranın üçüncüsü olacak tahtayı kazan.","tr.draw.t":"Beraberlik","tr.draw.b":"Sırasız dolan küçük tahta <b>kimsenin değildir</b> (gri).\nKimse oynayamaz ve büyük tahtada sıra yoksa oyun <b>berabere</b> biter.","tr.vars.t":"Kural varyantları","tr.vars.b":"Bu site bugün en çok oynanan kuralı kullanır. Yeni oyun penceresinde üç şeyi değiştirebilirsin:\n① Sonuçlanmış tahtaya gönderilince: istediğin yere (ana kural) / boş varsa oraya (ilk tanıtım yazısının kuralı; ilk oyuncunun kazandığı kanıtlandı)\n② Berabere biten küçük tahta: kimsenin değil (ana kural) / ikisine de sayılır\n③ Sonunda büyük tahtada sıra yoksa: beraberlik (ana kural) / çok tahta alan kazanır","ls.title":"Dersler","ls.desc":"Kuralları yeni öğrenenler için «İlk adımlar», kazanmak için «Strateji». Her adım: bir ısınma, ardından 20'şer puanlık 5 soru; geçmek için 75.","course.basics":"İlk adımlar","course.basics.sub":"Tahta kazanmak, engellemek, nereye göndereceğini seçmek, büyük tahtada kazanmak.","course.strategy":"Strateji","course.strategy.sub":"Almadan önce nereye gönderdiğine bak, serbest hamleyi kullan, gönderişleri kazanca kadar hesapla.","course.graduate":"🎉 «İlk adımlar» tamam! Artık oynayabilirsin — önce Lv.1–6 YZ ile dene.","ls.anywhere":"serbest hamle","ls.ng.miss":"{x} bu tahtada üçlü yapmaz.","ls.ng.missBig":"{x} büyük tahtada üçlü yapmaz.","ls.ng.lose":"{x} sonrasında rakip {r} oynar ve büyük tahtada üçlüyle kazanır.","ls.ng.take":"{x} sonrasında rakip {t} tahtaya gider ve {r} ile {tb} tahtayı kazanır.","ls.ng.takeFree":"{x} sonuçlanmış tahtaya gönderir: rakip istediği yere oynar ve {r} ile {tb} tahtayı kazanır.","ls.ng.free":"{x} sonuçlanmış tahtaya gönderir, rakip istediği yere oynayabilir.","ls.ng.slow":"{x} sonrasında rakip {r} ile direnir ve {n} hamlede daha üçlü yapamazsın.","ls.ng.ok":"{x} kötü değil ama burada daha iyi bir hamle var.","ls.ng.ans":"Doğru cevap {m}.","ls.b_take.title":"Küçük tahtayı kazan","ls.b_take.sub":"Üçüncü işaret","ls.b_take.intro":"<p>Küçük tahtada iki işaretin bir sıradaysa ve üçüncü kare boşsa, oraya oynamak o tahtayı kazandırır. Oynayabildiğin tahtada (parlayan) böyle bir sıra ara.</p>","ls.b_take.goal":"Küçük tahtayı kazandıran kareye oyna.","ls.b_take.hint":"Parlayan tahtada iki işaretinin olduğu sırayı bul.","ls.b_take.why":"{m} ile {b} tahtayı kazandın!","ls.b_take.ex.t":"Sıranın üçüncüsü","ls.b_take.ex.b":"Parlayan tahtada iki işaretinin olduğu bir sıra var. Üçüncü kare {m} tahtayı kazandırır.","ls.b_block.title":"Üçüncüsünü kapat","ls.b_block.sub":"Kaybetmeden savun","ls.b_block.intro":"<p>Oynadığın tahtada rakibin iki işareti sıradaysa üçüncü kareyi kapatmak temel savunmadır. Yoksa oraya gönderildiği anda (ya da serbest hamlesinde) o tahtayı kazanır.</p>","ls.b_block.goal":"Bu tahtayı savunan hamleyi oyna.","ls.b_block.hint":"Parlayan tahtada rakibin iki işareti nerede sırada?","ls.b_block.why":"{m} rakibin üçüncü karesini kapattı. Rakip {t} tahtaya gider ve hemen tahta kazanamaz.","ls.b_block.ex.t":"Üçüncüyü kapat","ls.b_block.ex.b":"Rakibin parlayan tahtada iki işareti sırada. Üçüncü kareyi, {m}, kapatmak tahtayı şimdilik korur.","ls.b_send.title":"Nereye göndereceğini seç","ls.b_send.sub":"Bedava verme","ls.b_send.intro":"<p>Oynadığın kare rakibin sonraki tahtasını belirler. Onu ikilisi olan bir tahtaya gönderirsen o tahtayı kazanır. Oynamadan önce hangi tahtanın güvenli olduğunu kontrol et.</p>","ls.b_send.goal":"Rakibe küçük tahta vermeyen hamleyi oyna.","ls.b_send.hint":"Kırmızı parlayan tahtalarda rakibin ikilisi var. Hangi kare onu oraya göndermez?","ls.b_send.why":"{m} ile rakip {t} tahtaya gider ve orada hemen tahta kazanamaz.","ls.b_send.ex.t":"Nereye gönderdiğine bak","ls.b_send.ex.b":"Kırmızı hamle rakibi ikilisi olan tahtaya gönderir ve o tahtayı kazanır. Yeşil {m} onu kazanamayacağı yere gönderir.","ls.b_big.title":"Büyük tahtada üçlü","ls.b_big.sub":"Oyunu bitir","ls.b_big.intro":"<p>Kazandığın iki tahta büyük tahtada bir sıradaysa üçüncüsünü kazanmak oyunu kazandırır. Küçük tahta kazanan birkaç hamle olabilir ama yalnızca o sıranın üçüncüsü oyunu kazanır.</p>","ls.b_big.goal":"Bu hamleyle oyunu kazan.","ls.b_big.hint":"Kesik çizgili tahta büyük tahtadaki üçlüye bir eksik. Hangi hamle onu kazanır?","ls.b_big.why":"{m} ile {b} tahtayı kazandın — büyük tahtada üçlü. Kazandın!","ls.b_big.ex.t":"Büyük tahtanın üçüncüsü","ls.b_big.ex.b":"Büyük tahtadaki ikili sıranın üçüncü tahtasını (kesik çizgili) kazan, oyun senin. Bunu {m} yapar.","ls.s_look.title":"Almadan önce bak","ls.s_look.sub":"Bedava tahta tuzağı","ls.s_look.intro":"<p>Bir hamle küçük tahtayı kazanıp yine de rakibi iyi bir yere gönderebilir. Kazandıran karenin nereye gönderdiğini kontrol et ve hiçbir şey vermeyen hamleyi seç.</p>","ls.s_look.goal":"En iyi hamleyi oyna (tahta kazanmak her zaman o değildir).","ls.s_look.hint":"Kırmızı parlayan tahtalarda rakibin ikilisi var. Kazandıran hamle onu nereye gönderiyor?","ls.s_look.why":"{m} ile rakip {t} tahtaya gider ve hemen tahta kazanamaz. Burada önündeki tahtadan çok nereye gönderdiğin önemliydi.","ls.s_look.ex.t":"Almak onu gönderir","ls.s_look.ex.b":"Kırmızı hamle bir tahta kazanır ama rakibi ikilisi olan tahtaya gönderir. Onu güvenli yere gönderen yeşil {m} doğrudur.","ls.s_free.title":"Serbest hamleyi kullan","ls.s_free.sub":"Önemli yere git","ls.s_free.intro":"<p>Serbest hamle büyük bir fırsattır. Büyük tahtada önemli olan tahtaya oyna — taraflardan biri için üçlüyü tamamlayacak olana.</p>","ls.s_free.goal":"İstediğin yere oynayabilirsin. En önemli hamleyi yap.","ls.s_free.hint":"Kesik çizgili tahtalar büyük tahtanın kilit tahtalarıdır. Orada ne yapabilirsin?","ls.s_free.why":"{m} büyük tahtanın kilit tahtasına, {b} tahtaya oynar.","ls.s_free.ex.t":"Kilit tahtayı seç","ls.s_free.ex.b":"Serbest hamle büyük tahtanın kilit tahtasını (kesik çizgili) seçmeni sağlar. O hamle {m}.","ls.s_force2.title":"2 hamlede kazan","ls.s_force2.sub":"Gönderişleri hesapla","ls.s_force2.intro":"<p>Rakibi öyle bir tahtaya gönder ki her hamlesi senin sonraki hamlenle büyük tahtada üçlüye izin versin. Her karesini ve seni nereye gönderdiğini kontrol et.</p>","ls.s_force2.goal":"2 hamlede büyük tahtada üçlü yap.","ls.s_force2.hint":"Tüm cevaplarının kazancına götürdüğü, onu göndereceğin tahtayı bul.","ls.s_force2.why":"{m} kazandıran hamle: ne cevap verirse versin, sonraki hamlen üçlüyü tamamlar.","ls.s_force2.ex.t":"Gönder ve kazan","ls.s_force2.ex.b":"Yeşil {m} sonrasında rakibin her cevabı seni kazanacağın bir tahtaya gönderir.","ls.s_force3.title":"3 hamlede kazan","ls.s_force3.sub":"Oyun sonunda zorlamak","ls.s_force3.intro":"<p>Oyun sonunda gönderişler oyunu belirler. Her hamlede rakibin seçeneklerini daralt ve 3 hamlede üçlüye giden yolu hesapla.</p>","ls.s_force3.goal":"3 hamlede büyük tahtada üçlü yap.","ls.s_force3.hint":"Sırayla bak: tahta kazandıran hamleler, hiçbir şey vermeyen hamleler, serbest hamle vermeyen hamleler.","ls.s_force3.why":"{m} ile 3 hamlede kazanırsın.","ls.s_force3.ex.t":"3 hamle hesabı","ls.s_force3.ex.b":"Yeşil {m}'den başlayıp her cevabında onu geri gönder ve 3 hamlede büyük tahtada kazan.","pz.title":"Ultimate Tic-Tac-Toe bulmacaları","pz.desc":"Verilen hamle sayısında büyük tahtada üçlü yap. Rakip en inatçı şekilde savunur. Her çözüm motor tarafından kanıtlandı.","pz.winIn":"{n} hamlede kazan","pz.goal":"{c} oynuyor: {n} hamlede büyük tahtada üçlü","pz.start":"İlk hamleni yap.","pz.best":"Doğru cevap {b} idi.","pz.solvedSub":"{n} hamlede büyük tahtada üçlü.","pz.hint1":"{n} hamle kaldı. Gönderdiğin tahtada rakibin ne yapabileceğine bak.","pz.hintText":"Kazandıran bir hamle kesik çizgili tahtada başlıyor.","pz.reply":"Rakip {m} oynadı. {n} hamle kaldı.","pz.retry":"Tekrar dene","pz.grpWin":"N hamlede kazan","pz.grpWinSub":"En inatçı savunmaya karşı verilen hamlelerde büyük tahtada üçlü yap.","pz.grpTac":"Temalar","pz.grpTacSub":"Göndererek kazan · serbest hamleden kazan. Yalnızca tahta almak yetmez.","pz.th.w1":"1 hamlede kazan","pz.th.w1.sub":"Küçük tahta kazandıran hamleler arasından oyunu kazandıranı bul.","pz.th.w2":"2 hamlede kazan","pz.th.w2.sub":"Cevabını oku ve ikinci hamlenle sırayı tamamla.","pz.th.w3":"3 hamlede kazan","pz.th.w3.sub":"Savunmasını hesapla ve 3 hamlede kazan.","pz.th.w4":"4 hamlede kazan","pz.th.w4.sub":"Uzun gönderiş düelloları: seçeneklerini daralt ve köşeye sıkıştır.","pz.th.send":"Göndererek kazan","pz.th.send.sub":"İlk hamle tahta kazanmaz: rakibi nereye gönderdiği oyunu belirler.","pz.th.free":"Serbest hamleden kazan","pz.th.free.sub":"İstediğin yere oynayabilirsin — kazanca götüren hamleyi seç.","pz.why.last":"{m} büyük tahtada üçlü yapmadı.","pz.why.took":"Rakip {r} ile {b} tahtayı kazandı ve seni {t} tahtaya gönderdi. {n} hamlede daha kazanamazsın.","pz.why.far":"Rakip {r} ile direndi ve seni {t} tahtaya gönderdi. {n} hamlede daha üçlü yok.","pz.why.answer":"Çözümü görmek için «Cevap»a bas.","rv.note":"Hata = bir galibiyeti ya da beraberliği tersine çeviren veya çok kaybettiren hamle. Şüpheli = belirgin bir kayıp. Tahtadaki sayılar her kareye oynamanın değeridir.","cr.forced":"Oynanabilecek tek kare.","cr.first":"İlk hamle. <b>{b}</b> biraz daha iyi bir başlangıçtı.","cr.firstOk":"İlk hamle — iyi bir başlangıç.","cr.won":"Kazandıran hamle: büyük tahtada üçlü.","cr.best":"En iyi hamle.","cr.bestTake":"En iyi hamle — {t} tahtayı kazandı.","cr.good":"Fena değil (en iyisi <b>{b}</b>, yalnızca biraz daha iyi).","cr.gen":"Bu hamle konumu bozdu ({d}). En iyisi <b>{b}</b> idi.","cr.missWin":"Galibiyeti kaçırdın: <b>{b}</b> büyük tahtada üçlü yapıyordu.","cr.allowWin":"Bundan sonra rakip {r} ile büyük tahtada üçlü yapıp kazanır. <b>{b}</b> bunu önlerdi.","cr.gift":"Bu hamle rakibi {t} tahtaya gönderdi; orada {r} ona {tb} tahtayı verir. <b>{b}</b> hiçbir şey vermezdi.","cr.free":"Bu hamle sonuçlanmış tahtaya gönderdi, rakip istediği yere oynayabildi. <b>{b}</b> onu tek tahtada tutardı.","cr.missTake":"{tb} tahtayı kazanmayı kaçırdın. En iyisi <b>{b}</b> idi.","cr.tookBad":"Bir tahta kazandın ama rakibin gönderildiği yer ona yaradı. En iyisi <b>{b}</b> idi.","cr.tip.take":"💡 Kazanılabilir tahtalar önemlidir — ama kazandıran kare rakibin nereye gideceğini belirler.","cr.tip.send":"💡 Oynamadan önce, gönderdiğin tahtada rakibin ikilisi var mı bak.","cr.tip.free":"💡 Sonuçlanmış tahtaya göndermek rakibe en önemli tahtayı seçtirir.","cr.tip.look":"💡 Kazandıran hamlenin nereye gönderdiğini kontrol et. Bazen büyük tahta küçükten önemlidir.","cr.tip.gen":"💡 Tahtadaki ok en iyi hamledir; sayılar her kareye oynamanın değeridir."},
"id":{"meta.title":"Ultimate Tic-Tac-Toe — Atlas Besar Permainan Papan","title":"Ultimate Tic-Tac-Toe","sub":"","p1":"X","p2":"O","ng.first":"Pertama (X)","ng.second":"Kedua (O)","ng.level1":"Kekuatan AI pertama (X)","ng.level2":"Kekuatan AI kedua (O)","pcs":"papan","hb.free":"Langkah bebas","hb.to":"Tujuan: {b}","hb.var":"Varian aturan","rsv.won":"Papan dimenangkan {n}","rsv.free":"bebas","rsv.title":"{c}: {n} papan kecil dimenangkan (tiga sebaris menang)","send.first":"Giliran X: pilih kotak mana saja","send.free":"Kamu boleh main di papan kecil mana saja","send.to":"Main di papan yang bersinar ({b})","bname":["kiri atas","atas","kanan atas","kiri","tengah","kanan","kiri bawah","bawah","kanan bawah"],"cant.taken":"Kotak itu sudah terisi","cant.closed":"Papan kecil itu sudah selesai","cant.board":"Main di papan yang bersinar ({b})","opt.send":"Panah ke papan berikutnya","opt.num":"Koordinat","ng.rules":"Aturan","var.help":"Lihat aturan","var.fc":"Dikirim ke papan yang sudah selesai","var.fc0":"Main di mana saja","var.fc1":"Di sana jika masih ada kotak","var.tie":"Papan kecil yang seri","var.tie0":"Bukan milik siapa pun","var.tie1":"Dihitung untuk keduanya","var.cnt":"Tak ada tiga sebaris di papan besar","var.cnt0":"Seri","var.cnt1":"Papan terbanyak menang","var.std":"Aturan yang paling banyak dimainkan saat ini (pertandingan berperingkat, pelajaran, dan teka-teki juga memakainya).","var.custom":"Permainan dengan aturan diubah. AI memainkan semua varian; pertandingan berperingkat, pelajaran, dan teka-teki tetap memakai aturan utama.","lvd":["Pemula: hanya melihat baris di depannya","Dasar–menengah: membaca ke mana langkahnya mengirimmu","Mahir: menimbang perebutan papan kecil","Ahli: membaca papan besar secara mendalam"],"lvd.top":"Tolok ukur: pencarian terkuat, lama tiap langkah (tanpa hadiah)","bd.title":"Papan","bd.walnut":"Kayu walnut & kuningan","bd.slate":"Batu tulis sekolah","bd.washi":"Washi & sumi","bd.parchment":"Kertas tua & tinta","bd.marble":"Marmer & emas","bd.cherry":"Kayu ceri & eboni","pcs.title":"Tanda X dan O","pcs.token":"Pernis & gading","pcs.brush":"Kuas sumi & merah vermilion","pcs.chalk":"Kapur","pcs.ink":"Pena & tinta","res.why.line":"Tiga papan kecil sebaris di papan besar","res.why.count":"Tak ada baris di papan besar — ditentukan jumlah papan yang dimenangkan","res.why.full":"Tak ada kotak tersisa (tak ada baris di papan besar)","dr.none":"","intro.t":"Permainan apa Ultimate Tic-Tac-Toe itu?","intro.origin":"Tidak diketahui (menyebar sebagai permainan pena dan kertas)","intro.players":"2","intro.time":"10–20 menit","intro.hist":"Tic-tac-toe yang setiap kotaknya berisi tic-tac-toe yang lebih kecil. Ben Orlin melihat para matematikawan memainkannya saat piknik dan menulisnya di blog «Math with Bad Drawings» pada 2013, sehingga permainan ini dikenal luas.","intro.win":"Tiga sebaris di papan kecil memenangkan papan itu. <b>Tiga papan yang dimenangkan sebaris di papan besar memenangkan permainan.</b> Jika tak ada yang bisa main, hasilnya seri.","intro.cult":"Tic-tac-toe biasa selalu seri, tetapi di sini kotak yang kamu mainkan menentukan tempat lawan bermain berikutnya, sehingga permainan menjadi dalam — favorit riset AI dan lomba pemrograman.","tr.board.t":"Papan: sembilan permainan kecil","tr.board.b":"Setiap 9 kotak papan besar berisi <b>papan kecil</b> 3 × 3 (total 81 kotak).\nTiga sebaris di papan kecil memenangkannya dan memberi tanda besar di atasnya.","tr.first.t":"Langkah pertama","tr.first.b":"X mulai. Hanya langkah pertama yang boleh di <b>mana saja</b> dari 81 kotak.","tr.first.task":"Letakkan X di kotak mana saja","tr.first.ok":"Selesai! Sekarang giliran O.","tr.send.t":"Kotakmu mengirim lawan","tr.send.b":"X bermain di <b>kotak kanan atas</b> papan tengah, jadi O harus bermain di <b>papan kanan atas</b>.\nKotak yang kamu mainkan = papan tempat lawan bermain berikutnya.","tr.send.task":"Letakkan O di papan yang bersinar","tr.send.ok":"Betul! Sekarang kotak O menentukan ke mana X pergi.","tr.pick.t":"Ke mana mengirim lawan","tr.pick.b":"Kotak yang kamu pilih menentukan <b>papan berikutnya bagi lawan</b>.\nInilah inti strateginya.","tr.pick.task":"Mainkan X yang mengirim O ke <b>papan kanan atas</b>","tr.pick.ok":"O pergi ke papan kanan atas. Kamu sudah bisa memilih tujuan!","tr.pick.ng":"Kotak itu mengirim O ke tempat lain. Pakai kotak kanan atas di papan yang bersinar.","tr.small.t":"Memenangkan papan kecil","tr.small.b":"Tiga sebaris di papan kecil — mendatar, menurun, atau diagonal — <b>memenangkan papan itu</b>.\nTak ada lagi yang bermain di papan yang sudah dimenangkan.","tr.small.task":"Buat tiga X sebaris dan menangkan papannya","tr.small.ok":"Papan kecil dimenangkan!","tr.small.ng":"Belum ada tiga sebaris. Lengkapi baris dua X.","tr.free.t":"Dikirim ke papan yang sudah selesai","tr.free.b":"Jika papan tujuanmu sudah dimenangkan (atau penuh), <b>kamu boleh main di papan terbuka mana saja</b>.\nUsahakan jangan memberi lawan kebebasan ini.","tr.free.task":"Letakkan X di papan bersinar mana saja","tr.free.ok":"Langkah bebas!","tr.big.t":"Tiga papan sebaris menang","tr.big.b":"Menangkan tiga papan kecil <b>sebaris di papan besar</b> — mendatar, menurun, atau diagonal — untuk memenangkan permainan.","tr.big.task":"Menangkan papan ini untuk membuat tiga sebaris","tr.big.ok":"Tiga sebaris di papan besar. X menang!","tr.big.ng":"Belum. Menangkan papan yang menjadi ketiga dalam baris.","tr.draw.t":"Seri","tr.draw.b":"Papan kecil yang penuh tanpa baris <b>bukan milik siapa pun</b> (abu-abu).\nJika tak ada yang bisa main dan tak ada baris di papan besar, permainan berakhir <b>seri</b>.","tr.vars.t":"Varian aturan","tr.vars.b":"Situs ini memakai aturan yang paling banyak dimainkan saat ini. Di jendela permainan baru kamu bisa mengubah tiga hal:\n① Dikirim ke papan yang sudah selesai: main di mana saja (aturan utama) / di sana jika masih ada kotak (aturan artikel pertama; terbukti pemain pertama menang)\n② Papan kecil yang seri: bukan milik siapa pun (aturan utama) / dihitung untuk keduanya\n③ Tak ada baris di papan besar pada akhirnya: seri (aturan utama) / papan terbanyak menang","ls.title":"Pelajaran","ls.desc":"«Langkah pertama» bagi yang baru belajar aturan, dan «Strategi» untuk menang. Setiap tahap: pemanasan, lalu 5 soal masing-masing 20 poin; lulus dengan 75.","course.basics":"Langkah pertama","course.basics.sub":"Memenangkan papan, memblokir, memilih tujuan, menang di papan besar.","course.strategy":"Strategi","course.strategy.sub":"Lihat tujuan sebelum mengambil, pakai langkah bebas, hitung kiriman sampai menang.","course.graduate":"🎉 «Langkah pertama» selesai! Kamu siap bermain — coba dulu AI Lv.1–6.","ls.anywhere":"langkah bebas","ls.ng.miss":"{x} tidak membuat tiga sebaris di papan ini.","ls.ng.missBig":"{x} tidak membuat tiga sebaris di papan besar.","ls.ng.lose":"Setelah {x}, lawan memainkan {r} dan menang dengan tiga sebaris di papan besar.","ls.ng.take":"Setelah {x}, lawan pergi ke papan {t} dan memenangkan papan {tb} dengan {r}.","ls.ng.takeFree":"{x} mengirim ke papan yang sudah selesai: lawan bebas memilih dan memenangkan papan {tb} dengan {r}.","ls.ng.free":"{x} mengirim ke papan yang sudah selesai, jadi lawan boleh main di mana saja.","ls.ng.slow":"Setelah {x}, lawan bertahan dengan {r}, dan kamu tak bisa membuat tiga sebaris dalam {n} langkah lagi.","ls.ng.ok":"{x} tidak buruk, tapi ada langkah yang lebih baik di sini.","ls.ng.ans":"Jawabannya {m}.","ls.b_take.title":"Memenangkan papan kecil","ls.b_take.sub":"Tanda ketiga","ls.b_take.intro":"<p>Jika dua tandamu sebaris di papan kecil dan kotak ketiga kosong, bermain di sana memenangkan papan itu. Cari baris seperti itu di papan tempat kamu boleh bermain (yang bersinar).</p>","ls.b_take.goal":"Mainkan kotak yang memenangkan papan kecil.","ls.b_take.hint":"Di papan yang bersinar, cari baris berisi dua tandamu.","ls.b_take.why":"{m} memenangkan papan {b}!","ls.b_take.ex.t":"Kotak ketiga sebuah baris","ls.b_take.ex.b":"Papan yang bersinar punya baris berisi dua tandamu. Kotak ketiga, {m}, memenangkan papan itu.","ls.b_block.title":"Blokir kotak ketiganya","ls.b_block.sub":"Bertahan sebelum direbut","ls.b_block.intro":"<p>Jika lawan punya dua sebaris di papan tempat kamu bermain, memblokir kotak ketiga adalah pertahanan dasar. Kalau tidak, ia memenangkannya begitu dikirim ke sana (atau mendapat langkah bebas).</p>","ls.b_block.goal":"Mainkan langkah yang mempertahankan papan ini.","ls.b_block.hint":"Di papan yang bersinar, di mana dua tanda lawan sebaris?","ls.b_block.why":"{m} memblokir kotak ketiganya. Lawan pergi ke papan {t} dan tak bisa langsung memenangkan papan.","ls.b_block.ex.t":"Blokir yang ketiga","ls.b_block.ex.b":"Lawan punya dua sebaris di papan yang bersinar. Memblokir kotak ketiga, {m}, menjaga papan itu untuk sementara.","ls.b_send.title":"Memilih tujuan","ls.b_send.sub":"Jangan memberi gratis","ls.b_send.intro":"<p>Kotak yang kamu mainkan menentukan papan berikutnya bagi lawan. Mengirimnya ke papan tempat ia punya dua sebaris membuatnya bisa memenangkan papan itu. Periksa dulu papan mana yang aman.</p>","ls.b_send.goal":"Mainkan langkah yang tidak memberi lawan papan kecil.","ls.b_send.hint":"Papan yang bersinar merah berisi dua sebaris milik lawan. Kotak mana yang tidak mengirimnya ke sana?","ls.b_send.why":"Dengan {m} lawan pergi ke papan {t} dan tak bisa langsung memenangkan papan di sana.","ls.b_send.ex.t":"Periksa tujuanmu","ls.b_send.ex.b":"Langkah merah mengirim lawan ke papan berisi dua sebarisnya, dan ia memenangkannya. Langkah hijau, {m}, mengirimnya ke tempat ia tak bisa menang.","ls.b_big.title":"Tiga sebaris di papan besar","ls.b_big.sub":"Selesaikan permainan","ls.b_big.intro":"<p>Saat dua papan yang kamu menangkan sebaris di papan besar, memenangkan yang ketiga memenangkan permainan. Beberapa langkah bisa memenangkan papan kecil, tetapi hanya papan ketiga baris itu yang memenangkan permainan.</p>","ls.b_big.goal":"Menangkan permainan dengan langkah ini.","ls.b_big.hint":"Papan bergaris putus-putus tinggal satu lagi menuju tiga sebaris di papan besar. Langkah mana yang memenangkannya?","ls.b_big.why":"{m} memenangkan papan {b} — tiga sebaris di papan besar. Kamu menang!","ls.b_big.ex.t":"Papan ketiga di papan besar","ls.b_big.ex.b":"Menangkan papan ketiga dari baris dua di papan besar (yang putus-putus) dan permainan milikmu. {m} melakukannya.","ls.s_look.title":"Lihat sebelum mengambil","ls.s_look.sub":"Jebakan papan gratis","ls.s_look.intro":"<p>Sebuah langkah bisa memenangkan papan kecil sekaligus mengirim lawan ke tempat yang bagus. Periksa ke mana kotak kemenangan itu mengirim, dan pilih langkah yang tidak memberi apa pun.</p>","ls.s_look.goal":"Mainkan langkah terbaik (memenangkan papan belum tentu jawabannya).","ls.s_look.hint":"Papan yang bersinar merah berisi dua sebaris milik lawan. Ke mana langkah yang mengambil itu mengirimnya?","ls.s_look.why":"Dengan {m} lawan pergi ke papan {t} dan tak bisa langsung memenangkan papan. Di sini tujuan kiriman lebih penting daripada papan di depan mata.","ls.s_look.ex.t":"Mengambil berarti mengirim","ls.s_look.ex.b":"Langkah merah memenangkan papan, tetapi mengirim lawan ke papan berisi dua sebarisnya. Langkah hijau, {m}, yang mengirimnya ke tempat aman, adalah jawabannya.","ls.s_free.title":"Memakai langkah bebas","ls.s_free.sub":"Pergi ke tempat penting","ls.s_free.intro":"<p>Langkah bebas adalah peluang besar. Bermainlah di papan yang penting bagi papan besar — yang akan membuat tiga sebaris bagi salah satu pihak.</p>","ls.s_free.goal":"Kamu boleh main di mana saja. Mainkan langkah terpenting.","ls.s_free.hint":"Papan putus-putus adalah papan kunci di papan besar. Apa yang bisa kamu lakukan di sana?","ls.s_free.why":"{m} bermain di papan kunci papan besar, papan {b}.","ls.s_free.ex.t":"Pilih papan kunci","ls.s_free.ex.b":"Langkah bebas memungkinkanmu memilih papan kunci di papan besar (putus-putus). {m} adalah langkah itu.","ls.s_force2.title":"Menang dalam 2","ls.s_force2.sub":"Hitung kirimannya","ls.s_force2.intro":"<p>Kirim lawan ke papan tempat setiap langkahnya memungkinkan langkahmu berikutnya membuat tiga sebaris di papan besar. Periksa setiap kotaknya dan ke mana kotak itu mengirimmu.</p>","ls.s_force2.goal":"Buat tiga sebaris di papan besar dalam 2 langkah.","ls.s_force2.hint":"Cari papan tujuan yang membuat semua jawabannya menuju kemenanganmu.","ls.s_force2.why":"{m} adalah langkah kemenangan: apa pun jawabannya, langkahmu berikutnya melengkapi tiga sebaris.","ls.s_force2.ex.t":"Kirim lalu menang","ls.s_force2.ex.b":"Setelah langkah hijau {m}, setiap jawaban lawan mengirimmu ke papan tempat kamu menang.","ls.s_force3.title":"Menang dalam 3","ls.s_force3.sub":"Memaksa di akhir permainan","ls.s_force3.intro":"<p>Di akhir permainan, kiriman menentukan hasil. Persempit pilihan lawan setiap langkah dan hitung jalan menuju tiga sebaris dalam 3 langkah.</p>","ls.s_force3.goal":"Buat tiga sebaris di papan besar dalam 3 langkah.","ls.s_force3.hint":"Periksa berurutan: langkah yang memenangkan papan, langkah yang tidak memberi apa pun, langkah yang tidak memberi langkah bebas.","ls.s_force3.why":"Dari {m} kamu menang dalam 3 langkah.","ls.s_force3.ex.t":"Menghitung 3 langkah","ls.s_force3.ex.b":"Dari langkah hijau {m}, balas setiap jawabannya dengan mengirimnya kembali, dan menangkan papan besar dalam 3.","pz.title":"Teka-teki Ultimate Tic-Tac-Toe","pz.desc":"Buat tiga sebaris di papan besar dalam jumlah langkah yang ditentukan. Lawan bertahan sekeras mungkin. Setiap solusi dibuktikan oleh mesin.","pz.winIn":"Menang dalam {n}","pz.goal":"Giliran {c}: tiga sebaris di papan besar dalam {n} langkah","pz.start":"Mainkan langkah pertamamu.","pz.best":"Jawabannya {b}.","pz.solvedSub":"Tiga sebaris di papan besar dalam {n} langkah.","pz.hint1":"Sisa {n} langkah. Periksa apa yang bisa dilakukan lawan di papan tujuan kirimanmu.","pz.hintText":"Ada langkah kemenangan yang dimulai di papan putus-putus.","pz.reply":"Lawan memainkan {m}. Sisa {n} langkah.","pz.retry":"Ulangi","pz.grpWin":"Menang dalam N","pz.grpWinSub":"Buat tiga sebaris di papan besar dalam langkah yang ditentukan, melawan pertahanan paling gigih.","pz.grpTac":"Tema","pz.grpTacSub":"Menang lewat kiriman · menang dari langkah bebas. Mengambil papan saja tidak cukup.","pz.th.w1":"Menang dalam 1","pz.th.w1.sub":"Di antara langkah yang memenangkan papan kecil, temukan yang memenangkan permainan.","pz.th.w2":"Menang dalam 2","pz.th.w2.sub":"Baca jawabannya dan lengkapi baris dengan langkah keduamu.","pz.th.w3":"Menang dalam 3","pz.th.w3.sub":"Hitung pertahanannya dan menang dalam 3 langkah.","pz.th.w4":"Menang dalam 4","pz.th.w4.sub":"Adu kiriman panjang: persempit pilihannya dan sudutkan dia.","pz.th.send":"Menang lewat kiriman","pz.th.send.sub":"Langkah pertama tidak memenangkan papan: tujuan kiriman lawan menentukan hasil.","pz.th.free":"Menang dari langkah bebas","pz.th.free.sub":"Kamu boleh main di mana saja — pilih langkah menuju kemenangan.","pz.why.last":"{m} tidak membuat tiga sebaris di papan besar.","pz.why.took":"Lawan memenangkan papan {b} dengan {r} dan mengirimmu ke papan {t}. Kamu tak bisa menang dalam {n} langkah lagi.","pz.why.far":"Lawan bertahan dengan {r} dan mengirimmu ke papan {t}. Tak ada tiga sebaris dalam {n} langkah lagi.","pz.why.answer":"Tekan «Jawaban» untuk melihat solusinya.","rv.note":"Blunder = langkah yang membalikkan kemenangan atau seri, atau rugi besar. Meragukan = rugi yang jelas. Angka di papan adalah nilai bermain di tiap kotak.","cr.forced":"Satu-satunya kotak yang bisa dimainkan.","cr.first":"Langkah pertama. <b>{b}</b> sedikit lebih baik sebagai pembuka.","cr.firstOk":"Langkah pertama — pembuka yang bagus.","cr.won":"Langkah kemenangan: tiga sebaris di papan besar.","cr.best":"Langkah terbaik.","cr.bestTake":"Langkah terbaik — memenangkan papan {t}.","cr.good":"Lumayan (yang terbaik <b>{b}</b>, hanya sedikit lebih baik).","cr.gen":"Langkah ini merusak posisi ({d}). Yang terbaik <b>{b}</b>.","cr.missWin":"Kemenangan terlewat: <b>{b}</b> membuat tiga sebaris di papan besar.","cr.allowWin":"Setelah ini lawan menang dengan {r}, tiga sebaris di papan besar. <b>{b}</b> mencegahnya.","cr.gift":"Langkah ini mengirim lawan ke papan {t}, tempat {r} memberinya papan {tb}. <b>{b}</b> tidak memberi apa pun.","cr.free":"Langkah ini mengirim ke papan yang sudah selesai, sehingga lawan bebas memilih. <b>{b}</b> menahannya di satu papan.","cr.missTake":"Kamu melewatkan kemenangan papan {tb}. Yang terbaik <b>{b}</b>.","cr.tookBad":"Kamu memenangkan papan, tetapi tujuan kiriman lawan membantunya. Yang terbaik <b>{b}</b>.","cr.tip.take":"💡 Papan yang bisa dimenangkan itu penting — tetapi kotak kemenangannya menentukan ke mana lawan pergi.","cr.tip.send":"💡 Sebelum bermain, cari dua sebaris milik lawan di papan tujuan kirimanmu.","cr.tip.free":"💡 Mengirim ke papan yang sudah selesai membiarkan lawan memilih papan terpenting.","cr.tip.look":"💡 Periksa ke mana langkah pengambil mengirim. Kadang papan besar lebih penting daripada papan kecil.","cr.tip.gen":"💡 Panah di papan adalah langkah terbaik; angkanya adalah nilai bermain di tiap kotak."},
"hi":{"meta.title":"अल्टीमेट टिक-टैक-टो — विश्व बोर्ड गेम महाकोश","title":"अल्टीमेट टिक-टैक-टो","sub":"Ultimate Tic-Tac-Toe","p1":"X","p2":"O","ng.first":"पहले (X)","ng.second":"बाद में (O)","ng.level1":"पहले (X) की AI ताकत","ng.level2":"बाद वाले (O) की AI ताकत","pcs":"बोर्ड","hb.free":"कहीं भी चलो","hb.to":"भेजा गया: {b}","hb.var":"नियम बदला","rsv.won":"जीते बोर्ड {n}","rsv.free":"खुला","rsv.title":"{c}: जीते छोटे बोर्ड {n} (एक पंक्ति में तीन जीतते हैं)","send.first":"X की चाल: कोई भी खाना चुनो","send.free":"किसी भी छोटे बोर्ड में चल सकते हो","send.to":"चमकते बोर्ड ({b}) में चलो","bname":["ऊपर बाएँ","ऊपर","ऊपर दाएँ","बाएँ","बीच","दाएँ","नीचे बाएँ","नीचे","नीचे दाएँ"],"cant.taken":"यह खाना पहले से भरा है","cant.closed":"इस छोटे बोर्ड का फ़ैसला हो चुका है","cant.board":"चमकते बोर्ड ({b}) में चलो","opt.send":"अगले बोर्ड का तीर","opt.num":"निर्देशांक","ng.rules":"नियम","var.help":"नियम देखो","var.fc":"तय हो चुके बोर्ड में भेजे जाने पर","var.fc0":"कहीं भी चलो","var.fc1":"जगह हो तो वहीं","var.tie":"बराबरी वाला छोटा बोर्ड","var.tie0":"किसी का नहीं","var.tie1":"दोनों का गिना जाए","var.cnt":"बड़े बोर्ड पर पंक्ति न बने तो","var.cnt0":"ड्रॉ","var.cnt1":"ज़्यादा बोर्ड वाला जीते","var.std":"आज सबसे ज़्यादा खेला जाने वाला नियम (रेटेड खेल, पाठ और पहेलियाँ भी इसी से)।","var.custom":"बदले हुए नियमों वाला खेल। AI हर रूप खेलता है; रेटेड खेल, पाठ और पहेलियाँ मुख्य नियम से ही।","lvd":["शुरुआती: बस सामने की पंक्ति देखता है","नौसिखिया–मध्यम: पढ़ता है कि उसकी चाल तुम्हें कहाँ भेजती है","उन्नत: छोटे बोर्डों की लड़ाई तौलता है","विशेषज्ञ: बड़े बोर्ड को गहराई से पढ़ता है"],"lvd.top":"बेंचमार्क: सबसे मज़बूत खोज, हर चाल पर लंबा सोच (कोई इनाम नहीं)","bd.title":"बोर्ड","bd.walnut":"अखरोट की लकड़ी और पीतल","bd.slate":"स्कूल की स्लेट","bd.washi":"वाशी और सुमी","bd.parchment":"पुराना कागज़ और स्याही","bd.marble":"संगमरमर और सोना","bd.cherry":"चेरी की लकड़ी और आबनूस","pcs.title":"X और O के निशान","pcs.token":"लाख और हाथीदाँत","pcs.brush":"सुमी और सिंदूरी ब्रश","pcs.chalk":"चॉक","pcs.ink":"कलम और स्याही","res.why.line":"बड़े बोर्ड पर तीन छोटे बोर्ड एक पंक्ति में","res.why.count":"बड़े बोर्ड पर पंक्ति नहीं — जीते बोर्डों की गिनती से फ़ैसला","res.why.full":"चलने को कोई खाना नहीं बचा (बड़े बोर्ड पर पंक्ति नहीं)","dr.none":"","intro.t":"अल्टीमेट टिक-टैक-टो क्या है?","intro.origin":"अज्ञात (कागज़-कलम के खेल के रूप में फैला)","intro.players":"2","intro.time":"10–20 मिनट","intro.hist":"ऐसा टिक-टैक-टो जिसके हर खाने में एक छोटा टिक-टैक-टो बना हो। बेन ओर्लिन ने गणितज्ञों को पिकनिक पर इसे खेलते देखा और 2013 में अपने ब्लॉग «Math with Bad Drawings» पर लिखा, जिससे यह मशहूर हुआ।","intro.win":"छोटे बोर्ड पर एक पंक्ति में तीन बनाओ तो वह बोर्ड तुम्हारा। <b>जीते हुए तीन बोर्ड बड़े बोर्ड पर एक पंक्ति में हों तो खेल जीतते हो।</b> कोई न चल सके तो ड्रॉ।","intro.cult":"साधारण टिक-टैक-टो हमेशा ड्रॉ होता है, पर यहाँ तुम्हारा खाना तय करता है कि विरोधी अगली चाल कहाँ चलेगा — इसीलिए खेल गहरा है और AI शोध व प्रोग्रामिंग प्रतियोगिताओं का पसंदीदा विषय है।","tr.board.t":"बोर्ड: नौ छोटे खेल","tr.board.b":"बड़े बोर्ड के 9 खानों में से हर एक में 3 × 3 का <b>छोटा बोर्ड</b> है (कुल 81 खाने)।\nछोटे बोर्ड पर एक पंक्ति में तीन उसे जिताते हैं और उस पर बड़ा निशान लगता है।","tr.first.t":"पहली चाल","tr.first.b":"X पहले चलता है। सिर्फ़ पहली चाल 81 खानों में <b>कहीं भी</b> चल सकते हो।","tr.first.task":"किसी भी खाने में X रखो","tr.first.ok":"हो गया! अब O की बारी।","tr.send.t":"तुम्हारा खाना विरोधी को भेजता है","tr.send.b":"X ने बीच वाले बोर्ड के <b>ऊपर-दाएँ खाने</b> में चला, इसलिए O को <b>ऊपर दाएँ बोर्ड</b> में चलना होगा।\nजिस खाने में चलते हो = विरोधी अगली चाल जिस बोर्ड में चलेगा।","tr.send.task":"चमकते बोर्ड में O रखो","tr.send.ok":"सही! अब O का खाना तय करेगा कि X कहाँ जाए।","tr.pick.t":"विरोधी को कहाँ भेजें","tr.pick.b":"तुम कौन-सा खाना चुनते हो, उससे <b>विरोधी का अगला बोर्ड</b> तय होता है।\nयही रणनीति का दिल है।","tr.pick.task":"वह X रखो जो O को <b>ऊपर दाएँ बोर्ड</b> में भेजे","tr.pick.ok":"O ऊपर दाएँ बोर्ड में जाएगा। तुमने भेजने की जगह चुन ली!","tr.pick.ng":"यह खाना O को कहीं और भेजता है। चमकते बोर्ड का ऊपर-दाएँ खाना लो।","tr.small.t":"छोटा बोर्ड जीतना","tr.small.b":"छोटे बोर्ड पर आड़ी, खड़ी या तिरछी तीन की पंक्ति <b>उस बोर्ड को जिताती है</b>।\nजीते बोर्ड में फिर कोई नहीं चलता।","tr.small.task":"तीन X एक पंक्ति में रखकर बोर्ड जीतो","tr.small.ok":"छोटा बोर्ड जीत लिया!","tr.small.ng":"अभी तीन की पंक्ति नहीं बनी। दो X वाली पंक्ति पूरी करो।","tr.free.t":"तय हो चुके बोर्ड में भेजे जाने पर","tr.free.b":"जिस बोर्ड में भेजा गया वह पहले से जीता (या भरा) हो, तो <b>किसी भी खुले बोर्ड में चल सकते हो</b>।\nयह आज़ादी विरोधी को न देने की कोशिश करो।","tr.free.task":"किसी भी चमकते बोर्ड में X रखो","tr.free.ok":"खुली चाल!","tr.big.t":"तीन बोर्ड एक पंक्ति में जीतते हैं","tr.big.b":"तीन छोटे बोर्ड <b>बड़े बोर्ड पर एक पंक्ति में</b> — आड़ी, खड़ी या तिरछी — जीतो तो खेल तुम्हारा।","tr.big.task":"यह बोर्ड जीतकर तीन की पंक्ति बनाओ","tr.big.ok":"बड़े बोर्ड पर तीन की पंक्ति। X जीता!","tr.big.ng":"अभी नहीं। वह बोर्ड जीतो जो पंक्ति का तीसरा बने।","tr.draw.t":"ड्रॉ","tr.draw.b":"बिना पंक्ति के भर गया छोटा बोर्ड <b>किसी का नहीं</b> (धूसर)।\nकोई न चल सके और बड़े बोर्ड पर पंक्ति न हो, तो खेल <b>ड्रॉ</b>।","tr.vars.t":"नियमों के रूप","tr.vars.b":"यह साइट आज का सबसे प्रचलित नियम खेलती है। नए खेल की खिड़की में तीन चीज़ें बदल सकते हो:\n① तय हो चुके बोर्ड में भेजे जाने पर: कहीं भी चलो (मुख्य नियम) / जगह हो तो वहीं (पहले लेख का नियम; पहले खिलाड़ी की जीत सिद्ध)\n② बराबरी वाला छोटा बोर्ड: किसी का नहीं (मुख्य नियम) / दोनों का गिना जाए\n③ अंत में बड़े बोर्ड पर पंक्ति न हो: ड्रॉ (मुख्य नियम) / ज़्यादा बोर्ड जीतने वाला जीते","ls.title":"पाठ","ls.desc":"नियम अभी सीखने वालों के लिए «पहले कदम» और जीतने के लिए «रणनीति»। हर चरण: पहले अभ्यास, फिर 20-20 अंक के 5 सवाल; पास होने के लिए 75।","course.basics":"पहले कदम","course.basics.sub":"बोर्ड जीतना, रोकना, भेजने की जगह चुनना, बड़े बोर्ड पर जीतना।","course.strategy":"रणनीति","course.strategy.sub":"लेने से पहले देखो कहाँ भेजते हो, खुली चाल का उपयोग, भेजने की चालें जीत तक गिनो।","course.graduate":"🎉 «पहले कदम» पूरे! अब खेल सकते हो — पहले Lv.1–6 की AI से खेलकर देखो।","ls.anywhere":"खुली चाल","ls.ng.miss":"{x} से इस बोर्ड पर तीन की पंक्ति नहीं बनती।","ls.ng.missBig":"{x} से बड़े बोर्ड पर तीन की पंक्ति नहीं बनती।","ls.ng.lose":"{x} के बाद विरोधी {r} चलकर बड़े बोर्ड पर तीन की पंक्ति से जीत जाता है।","ls.ng.take":"{x} के बाद विरोधी {t} बोर्ड में जाता है और {r} से {tb} बोर्ड जीत लेता है।","ls.ng.takeFree":"{x} तय हो चुके बोर्ड में भेजता है: विरोधी कहीं भी चलकर {r} से {tb} बोर्ड जीत लेता है।","ls.ng.free":"{x} तय हो चुके बोर्ड में भेजता है, तो विरोधी कहीं भी चल सकता है।","ls.ng.slow":"{x} के बाद विरोधी {r} से टिका रहता है, और {n} और चालों में तीन की पंक्ति नहीं बनती।","ls.ng.ok":"{x} बुरी नहीं, पर यहाँ बेहतर चाल है।","ls.ng.ans":"सही उत्तर {m}।","ls.b_take.title":"छोटा बोर्ड जीतो","ls.b_take.sub":"तीसरा निशान","ls.b_take.intro":"<p>अगर छोटे बोर्ड पर तुम्हारे दो निशान एक पंक्ति में हों और तीसरा खाना खाली हो, तो वहाँ चलने से वह बोर्ड जीतते हो। जिस बोर्ड में चल सकते हो (चमकता हुआ), उसमें ऐसी पंक्ति ढूँढो।</p>","ls.b_take.goal":"वह खाना चलो जो छोटा बोर्ड जिताए।","ls.b_take.hint":"चमकते बोर्ड में अपने दो निशानों वाली पंक्ति ढूँढो।","ls.b_take.why":"{m} से {b} बोर्ड जीत लिया!","ls.b_take.ex.t":"पंक्ति का तीसरा","ls.b_take.ex.b":"चमकते बोर्ड में तुम्हारे दो निशानों वाली पंक्ति है। तीसरा खाना {m} बोर्ड जिताता है।","ls.b_block.title":"उसका तीसरा रोको","ls.b_block.sub":"छिनने से पहले बचाओ","ls.b_block.intro":"<p>अगर जिस बोर्ड में तुम चलते हो उसमें विरोधी के दो निशान पंक्ति में हों, तो तीसरा खाना रोकना बुनियादी बचाव है। वरना जैसे ही वह वहाँ भेजा जाएगा (या उसे खुली चाल मिलेगी), वह बोर्ड जीत लेगा।</p>","ls.b_block.goal":"यह बोर्ड बचाने वाली चाल चलो।","ls.b_block.hint":"चमकते बोर्ड में विरोधी के दो निशान किस पंक्ति में हैं?","ls.b_block.why":"{m} ने उसका तीसरा खाना रोक दिया। विरोधी {t} बोर्ड में जाता है और तुरंत बोर्ड नहीं जीत सकता।","ls.b_block.ex.t":"तीसरा रोको","ls.b_block.ex.b":"चमकते बोर्ड में विरोधी के दो निशान पंक्ति में हैं। तीसरा खाना {m} रोकने से बोर्ड फ़िलहाल सुरक्षित रहता है।","ls.b_send.title":"भेजने की जगह चुनो","ls.b_send.sub":"मुफ़्त में मत दो","ls.b_send.intro":"<p>तुम्हारा खाना विरोधी का अगला बोर्ड तय करता है। उसे ऐसे बोर्ड में भेजो जहाँ उसके दो पंक्ति में हैं, तो वह बोर्ड जीत लेगा। चलने से पहले देखो कौन-सा बोर्ड सुरक्षित है।</p>","ls.b_send.goal":"ऐसी चाल चलो जो विरोधी को कोई छोटा बोर्ड न दे।","ls.b_send.hint":"लाल चमकते बोर्डों में विरोधी के दो पंक्ति में हैं। कौन-सा खाना उसे वहाँ नहीं भेजता?","ls.b_send.why":"{m} से विरोधी {t} बोर्ड में जाता है और वहाँ तुरंत बोर्ड नहीं जीत सकता।","ls.b_send.ex.t":"भेजने की जगह जाँचो","ls.b_send.ex.b":"लाल चाल विरोधी को उसके दो वाले बोर्ड में भेजती है, और वह उसे जीत लेता है। हरी चाल {m} उसे वहाँ भेजती है जहाँ वह नहीं जीत सकता।","ls.b_big.title":"बड़े बोर्ड पर तीन","ls.b_big.sub":"खेल ख़त्म करो","ls.b_big.intro":"<p>जब तुम्हारे जीते दो बोर्ड बड़े बोर्ड पर एक पंक्ति में हों, तो तीसरा जीतना खेल जिताता है। कई चालें छोटा बोर्ड जिता सकती हैं, पर खेल सिर्फ़ उस पंक्ति का तीसरा बोर्ड जिताता है।</p>","ls.b_big.goal":"इस चाल से खेल जीतो।","ls.b_big.hint":"बिंदीदार बोर्ड बड़े बोर्ड पर तीन की पंक्ति से एक कम है। कौन-सी चाल उसे जीतती है?","ls.b_big.why":"{m} ने {b} बोर्ड जीता — बड़े बोर्ड पर तीन की पंक्ति। तुम जीते!","ls.b_big.ex.t":"बड़े बोर्ड का तीसरा","ls.b_big.ex.b":"बड़े बोर्ड पर दो वाली पंक्ति का तीसरा बोर्ड (बिंदीदार) जीतो और खेल तुम्हारा। यह {m} करता है।","ls.s_look.title":"लेने से पहले देखो","ls.s_look.sub":"मुफ़्त बोर्ड का जाल","ls.s_look.intro":"<p>कोई चाल छोटा बोर्ड जिताकर भी विरोधी को अच्छी जगह भेज सकती है। जिताने वाला खाना कहाँ भेजता है यह जाँचो और वह चाल चुनो जो कुछ न दे।</p>","ls.s_look.goal":"सबसे अच्छी चाल चलो (बोर्ड जीतना हमेशा सही नहीं)।","ls.s_look.hint":"लाल चमकते बोर्डों में विरोधी के दो पंक्ति में हैं। जीतने वाली चाल उसे कहाँ भेजती है?","ls.s_look.why":"{m} से विरोधी {t} बोर्ड में जाता है और तुरंत बोर्ड नहीं जीत सकता। यहाँ सामने के बोर्ड से ज़्यादा ज़रूरी था कि कहाँ भेजो।","ls.s_look.ex.t":"लेना यानी भेजना","ls.s_look.ex.b":"लाल चाल बोर्ड जीतती है, पर विरोधी को उसके दो वाले बोर्ड में भेजती है। उसे सुरक्षित जगह भेजने वाली हरी {m} सही है।","ls.s_free.title":"खुली चाल का उपयोग","ls.s_free.sub":"जहाँ ज़रूरी हो वहाँ जाओ","ls.s_free.intro":"<p>खुली चाल बड़ा मौक़ा है। बड़े बोर्ड के लिए ज़रूरी बोर्ड में चलो — जो किसी भी पक्ष की तीन की पंक्ति पूरी कर सके।</p>","ls.s_free.goal":"कहीं भी चल सकते हो। सबसे ज़रूरी चाल चलो।","ls.s_free.hint":"बिंदीदार बोर्ड बड़े बोर्ड के अहम बोर्ड हैं। वहाँ क्या कर सकते हो?","ls.s_free.why":"{m} बड़े बोर्ड के अहम बोर्ड, {b} बोर्ड में जाता है।","ls.s_free.ex.t":"अहम बोर्ड चुनो","ls.s_free.ex.b":"खुली चाल से बड़े बोर्ड का अहम बोर्ड (बिंदीदार) चुन सकते हो। वह चाल {m} है।","ls.s_force2.title":"2 चालों में जीत","ls.s_force2.sub":"भेजने की चालें गिनो","ls.s_force2.intro":"<p>विरोधी को ऐसे बोर्ड में भेजो जहाँ उसकी हर चाल के बाद तुम्हारी अगली चाल बड़े बोर्ड पर तीन की पंक्ति पूरी करे। उसका हर खाना और वह तुम्हें कहाँ भेजता है, जाँचो।</p>","ls.s_force2.goal":"2 चालों में बड़े बोर्ड पर तीन की पंक्ति बनाओ।","ls.s_force2.hint":"ऐसा बोर्ड ढूँढो जहाँ भेजने पर उसका हर जवाब तुम्हारी जीत तक ले जाए।","ls.s_force2.why":"{m} जिताने वाली चाल है: वह कुछ भी जवाब दे, तुम्हारी अगली चाल तीन की पंक्ति पूरी करती है।","ls.s_force2.ex.t":"भेजो और जीतो","ls.s_force2.ex.b":"हरी {m} के बाद विरोधी का हर जवाब तुम्हें ऐसे बोर्ड में भेजता है जहाँ तुम जीतते हो।","ls.s_force3.title":"3 चालों में जीत","ls.s_force3.sub":"अंत में मजबूर करना","ls.s_force3.intro":"<p>खेल के अंत में भेजने की चालें फ़ैसला करती हैं। हर चाल से विरोधी के विकल्प घटाओ और 3 चालों में तीन की पंक्ति का रास्ता गिनो।</p>","ls.s_force3.goal":"3 चालों में बड़े बोर्ड पर तीन की पंक्ति बनाओ।","ls.s_force3.hint":"क्रम से जाँचो: बोर्ड जिताने वाली चालें, कुछ न देने वाली चालें, खुली चाल न देने वाली चालें।","ls.s_force3.why":"{m} से 3 चालों में जीत।","ls.s_force3.ex.t":"3 चालों का हिसाब","ls.s_force3.ex.b":"हरी {m} से शुरू करके हर जवाब पर उसे वापस भेजो और 3 में बड़े बोर्ड पर जीतो।","pz.title":"अल्टीमेट टिक-टैक-टो पहेलियाँ","pz.desc":"तय चालों में बड़े बोर्ड पर तीन की पंक्ति बनाओ। विरोधी पूरी ज़िद से बचाव करता है। हर हल इंजन से सिद्ध है।","pz.winIn":"{n} में जीत","pz.goal":"{c} की चाल: {n} चालों में बड़े बोर्ड पर तीन की पंक्ति","pz.start":"अपनी पहली चाल चलो।","pz.best":"सही उत्तर {b} था।","pz.solvedSub":"{n} चालों में बड़े बोर्ड पर तीन की पंक्ति।","pz.hint1":"{n} चालें बाकी। जिस बोर्ड में भेजते हो वहाँ विरोधी क्या कर सकता है, देखो।","pz.hintText":"एक जिताने वाली चाल बिंदीदार बोर्ड से शुरू होती है।","pz.reply":"विरोधी ने {m} चला। {n} चालें बाकी।","pz.retry":"फिर से","pz.grpWin":"N में जीत","pz.grpWinSub":"सबसे ज़िद्दी बचाव के ख़िलाफ़ तय चालों में बड़े बोर्ड पर तीन की पंक्ति बनाओ।","pz.grpTac":"विषय","pz.grpTacSub":"भेजकर जीतो · खुली चाल से जीतो। सिर्फ़ बोर्ड लेने से हल नहीं होते।","pz.th.w1":"1 में जीत","pz.th.w1.sub":"छोटा बोर्ड जिताने वाली चालों में से खेल जिताने वाली ढूँढो।","pz.th.w2":"2 में जीत","pz.th.w2.sub":"उसका जवाब पढ़ो और दूसरी चाल से पंक्ति पूरी करो।","pz.th.w3":"3 में जीत","pz.th.w3.sub":"उसका बचाव गिनो और 3 चालों में जीतो।","pz.th.w4":"4 में जीत","pz.th.w4.sub":"लंबी भेजा-भेजी: उसके विकल्प घटाओ और घेर लो।","pz.th.send":"भेजकर जीतो","pz.th.send.sub":"पहली चाल कोई बोर्ड नहीं जीतती: विरोधी को कहाँ भेजती है, वही फ़ैसला करता है।","pz.th.free":"खुली चाल से जीतो","pz.th.free.sub":"कहीं भी चल सकते हो — जीत की ओर ले जाने वाली चाल चुनो।","pz.why.last":"{m} से बड़े बोर्ड पर तीन की पंक्ति नहीं बनी।","pz.why.took":"विरोधी ने {r} से {b} बोर्ड जीता और तुम्हें {t} बोर्ड में भेजा। {n} और चालों में जीत नहीं।","pz.why.far":"विरोधी {r} से टिका रहा और तुम्हें {t} बोर्ड में भेजा। {n} और चालों में तीन की पंक्ति नहीं।","pz.why.answer":"हल देखने के लिए «उत्तर» दबाओ।","rv.note":"भूल = जीत या ड्रॉ पलटने वाली या बड़ा नुकसान करने वाली चाल। संदिग्ध = साफ़ नुकसान। बोर्ड पर अंक हर खाने में चलने का मूल्य हैं।","cr.forced":"चलने लायक एकमात्र खाना।","cr.first":"पहली चाल। <b>{b}</b> थोड़ी बेहतर शुरुआत थी।","cr.firstOk":"पहली चाल — अच्छी शुरुआत।","cr.won":"जिताने वाली चाल: बड़े बोर्ड पर तीन की पंक्ति।","cr.best":"सबसे अच्छी चाल।","cr.bestTake":"सबसे अच्छी चाल — {t} बोर्ड जीता।","cr.good":"बुरी नहीं (सबसे अच्छी <b>{b}</b> थी, थोड़ी ही बेहतर)।","cr.gen":"इससे स्थिति बिगड़ी ({d})। सबसे अच्छी <b>{b}</b> थी।","cr.missWin":"जीत छूट गई: <b>{b}</b> से बड़े बोर्ड पर तीन की पंक्ति बनती।","cr.allowWin":"इसके बाद विरोधी {r} से बड़े बोर्ड पर तीन की पंक्ति बनाकर जीतता है। <b>{b}</b> इसे रोकती।","cr.gift":"इसने विरोधी को {t} बोर्ड में भेजा, जहाँ {r} उसे {tb} बोर्ड देता है। <b>{b}</b> कुछ नहीं देती।","cr.free":"इसने तय हो चुके बोर्ड में भेजा, तो विरोधी कहीं भी चल सका। <b>{b}</b> उसे एक बोर्ड में रोकती।","cr.missTake":"{tb} बोर्ड जीतने का मौक़ा छूटा। सबसे अच्छी <b>{b}</b> थी।","cr.tookBad":"बोर्ड जीता, पर विरोधी को भेजी गई जगह उसके काम आई। सबसे अच्छी <b>{b}</b> थी।","cr.tip.take":"💡 जीते जा सकने वाले बोर्ड ज़रूरी हैं — पर जिताने वाला खाना तय करता है कि विरोधी कहाँ जाएगा।","cr.tip.send":"💡 चलने से पहले, जिस बोर्ड में भेज रहे हो वहाँ उसके दो पंक्ति में तो नहीं, देखो।","cr.tip.free":"💡 तय हो चुके बोर्ड में भेजने से विरोधी सबसे ज़रूरी बोर्ड चुन लेता है।","cr.tip.look":"💡 लेने वाली चाल कहाँ भेजती है, जाँचो। कभी बड़ा बोर्ड छोटे से ज़्यादा ज़रूरी होता है।","cr.tip.gen":"💡 बोर्ड पर तीर सबसे अच्छी चाल है; अंक हर खाने में चलने का मूल्य हैं।"},
"ar":{"meta.title":"إكس أو المطلقة — الأطلس الكبير لألعاب الطاولة","title":"إكس أو المطلقة","sub":"Ultimate Tic-Tac-Toe","p1":"X","p2":"O","ng.first":"الأول (X)","ng.second":"الثاني (O)","ng.level1":"قوة ذكاء الأول (X)","ng.level2":"قوة ذكاء الثاني (O)","pcs":"لوحات","hb.free":"نقلة حرة","hb.to":"الوجهة: {b}","hb.var":"قواعد معدّلة","rsv.won":"لوحات مكسوبة {n}","rsv.free":"حرة","rsv.title":"{c}: لوحات صغيرة مكسوبة {n} (ثلاث في صف تفوز)","send.first":"دور X: اختر أي خانة","send.free":"يمكنك اللعب في أي لوحة صغيرة","send.to":"العب في اللوحة المضيئة ({b})","bname":["العلوية اليسرى","العلوية","العلوية اليمنى","اليسرى","الوسطى","اليمنى","السفلية اليسرى","السفلية","السفلية اليمنى"],"cant.taken":"هذه الخانة مشغولة","cant.closed":"حُسمت هذه اللوحة الصغيرة","cant.board":"العب في اللوحة المضيئة ({b})","opt.send":"سهم اللوحة التالية","opt.num":"الإحداثيات","ng.rules":"القواعد","var.help":"عرض القواعد","var.fc":"عند الإرسال إلى لوحة محسومة","var.fc0":"العب في أي مكان","var.fc1":"هناك إن بقي فراغ","var.tie":"لوحة صغيرة متعادلة","var.tie0":"ليست لأحد","var.tie1":"تُحسب للاثنين","var.cnt":"بلا صف على اللوحة الكبيرة","var.cnt0":"تعادل","var.cnt1":"يفوز صاحب الأكثر","var.std":"القاعدة الأكثر لعبًا اليوم (المباريات المصنفة والدروس والألغاز تستخدمها أيضًا).","var.custom":"مباراة بقواعد معدّلة. يلعب الذكاء الاصطناعي كل الصيغ، أما المباريات المصنفة والدروس والألغاز فبالقاعدة الأساسية.","lvd":["مبتدئ: لا يرى إلا الصف أمامه","مستجد–متوسط: يقرأ إلى أين ترسلك نقلاته","متقدم: يوازن الصراع على اللوحات الصغيرة","خبير: يقرأ اللوحة الكبيرة بعمق"],"lvd.top":"اختبار أداء: أقوى بحث، يفكر طويلًا في كل نقلة (بلا مكافآت)","bd.title":"اللوحة","bd.walnut":"جوز ونحاس","bd.slate":"لوح أردواز مدرسي","bd.washi":"واشي وحبر سومي","bd.parchment":"ورق قديم وحبر","bd.marble":"رخام وذهب","bd.cherry":"خشب الكرز والأبنوس","pcs.title":"علامات X و O","pcs.token":"ورنيش وعاج","pcs.brush":"فرشاة حبر سومي وزنجفر","pcs.chalk":"طباشير","pcs.ink":"ريشة وحبر","res.why.line":"ثلاث لوحات صغيرة في صف على اللوحة الكبيرة","res.why.count":"لا صف على اللوحة الكبيرة — حسمه عدد اللوحات المكسوبة","res.why.full":"لم تبق خانة للعب (لا صف على اللوحة الكبيرة)","dr.none":"","intro.t":"ما لعبة إكس أو المطلقة؟","intro.origin":"غير معروف (انتشرت لعبةً بالورقة والقلم)","intro.players":"2","intro.time":"10–20 دقيقة","intro.hist":"لعبة إكس أو في كل خانة منها لعبة إكس أو أصغر. رأى بن أورلين علماء رياضيات يلعبونها في نزهة، وكتب عنها عام 2013 في مدونته «<bdi>Math with Bad Drawings</bdi>» فاشتهرت.","intro.win":"ثلاث في صف على لوحة صغيرة تكسبها. <b>ثلاث لوحات مكسوبة في صف على اللوحة الكبيرة تكسب المباراة.</b> إن لم يستطع أحد اللعب فهي تعادل.","intro.cult":"إكس أو العادية تنتهي دائمًا بالتعادل، أما هنا فالخانة التي تلعبها تحدد أين يلعب خصمك، فتصبح اللعبة عميقة — وهي مفضلة في أبحاث الذكاء الاصطناعي ومسابقات البرمجة.","tr.board.t":"اللوحة: تسع ألعاب صغيرة","tr.board.b":"في كل خانة من خانات اللوحة الكبيرة التسع <b>لوحة صغيرة</b> 3 × 3 (81 خانة في المجموع).\nثلاث في صف على لوحة صغيرة تكسبها وتوضع عليها علامة كبيرة.","tr.first.t":"النقلة الأولى","tr.first.b":"يبدأ X. النقلة الأولى وحدها يمكن أن تكون <b>في أي مكان</b> من الخانات الـ81.","tr.first.task":"ضع X في أي خانة","tr.first.ok":"تم! الآن دور O.","tr.send.t":"خانتك ترسل خصمك","tr.send.b":"لعب X في <b>الخانة العلوية اليمنى</b> من اللوحة الوسطى، لذا يجب أن يلعب O في <b>اللوحة العلوية اليمنى</b>.\nالخانة التي تلعبها = اللوحة التي يلعب فيها خصمك بعدها.","tr.send.task":"ضع O في اللوحة المضيئة","tr.send.ok":"صحيح! الآن خانة O تحدد إلى أين يذهب X.","tr.pick.t":"إلى أين ترسل خصمك","tr.pick.b":"الخانة التي تختارها تحدد <b>لوحة خصمك التالية</b>.\nهذا قلب الاستراتيجية.","tr.pick.task":"العب X الذي يرسل O إلى <b>اللوحة العلوية اليمنى</b>","tr.pick.ok":"يذهب O إلى اللوحة العلوية اليمنى. لقد اخترت الوجهة!","tr.pick.ng":"هذه الخانة ترسل O إلى مكان آخر. استخدم الخانة العلوية اليمنى من اللوحة المضيئة.","tr.small.t":"كسب لوحة صغيرة","tr.small.b":"ثلاث في صف على لوحة صغيرة — أفقيًا أو رأسيًا أو قطريًا — <b>تكسب تلك اللوحة</b>.\nلا يلعب أحد بعدها في لوحة مكسوبة.","tr.small.task":"اصنع ثلاث X في صف واكسب اللوحة","tr.small.ok":"كسبت اللوحة الصغيرة!","tr.small.ng":"لا صف من ثلاث بعد. أكمل صف علامتي X.","tr.free.t":"الإرسال إلى لوحة محسومة","tr.free.b":"إن كانت اللوحة التي أُرسلت إليها مكسوبة (أو ممتلئة) <b>فيمكنك اللعب في أي لوحة مفتوحة</b>.\nحاول ألا تمنح خصمك هذه الحرية.","tr.free.task":"ضع X في أي لوحة مضيئة","tr.free.ok":"نقلة حرة!","tr.big.t":"ثلاث لوحات في صف تفوز","tr.big.b":"اكسب ثلاث لوحات صغيرة <b>في صف على اللوحة الكبيرة</b> — أفقيًا أو رأسيًا أو قطريًا — لتفوز بالمباراة.","tr.big.task":"اكسب هذه اللوحة لتصنع ثلاثًا في صف","tr.big.ok":"ثلاث في صف على اللوحة الكبيرة. فاز X!","tr.big.ng":"ليس بعد. اكسب اللوحة التي تكمل الصف ثالثةً.","tr.draw.t":"التعادل","tr.draw.b":"اللوحة الصغيرة التي امتلأت بلا صف <b>ليست لأحد</b> (رمادية).\nإن لم يستطع أحد اللعب ولا صف على اللوحة الكبيرة، تنتهي المباراة <b>بالتعادل</b>.","tr.vars.t":"صيغ القواعد","tr.vars.b":"يعتمد الموقع القاعدة الأكثر لعبًا اليوم. في نافذة المباراة الجديدة يمكنك تغيير ثلاثة أمور:\n① الإرسال إلى لوحة محسومة: العب في أي مكان (القاعدة الأساسية) / هناك إن بقي فراغ (قاعدة المقال الأول؛ ثبت فوز اللاعب الأول)\n② لوحة صغيرة متعادلة: ليست لأحد (القاعدة الأساسية) / تُحسب للاثنين\n③ لا صف على اللوحة الكبيرة في النهاية: تعادل (القاعدة الأساسية) / يفوز صاحب اللوحات الأكثر","ls.title":"الدروس","ls.desc":"«الخطوات الأولى» لمن تعلم القواعد للتو، و«الاستراتيجية» للفوز. كل مرحلة: إحماء ثم 5 مسائل بـ20 نقطة لكل منها؛ النجاح بـ75.","course.basics":"الخطوات الأولى","course.basics.sub":"كسب لوحة، السدّ، اختيار الوجهة، الفوز على اللوحة الكبيرة.","course.strategy":"الاستراتيجية","course.strategy.sub":"انظر إلى أين ترسل قبل الأخذ، استخدم النقلة الحرة، احسب الإرسال حتى الفوز.","course.graduate":"🎉 أتممت «الخطوات الأولى»! يمكنك اللعب الآن — جرّب أولًا الذكاء الاصطناعي من Lv.1 إلى Lv.6.","ls.anywhere":"نقلة حرة","ls.ng.miss":"{x} لا تصنع ثلاثًا في صف على هذه اللوحة.","ls.ng.missBig":"{x} لا تصنع ثلاثًا في صف على اللوحة الكبيرة.","ls.ng.lose":"بعد {x} يلعب الخصم {r} ويفوز بثلاث في صف على اللوحة الكبيرة.","ls.ng.take":"بعد {x} يذهب الخصم إلى اللوحة {t} ويكسب اللوحة {tb} بـ {r}.","ls.ng.takeFree":"{x} ترسل إلى لوحة محسومة: يلعب الخصم حيث يشاء ويكسب اللوحة {tb} بـ {r}.","ls.ng.free":"{x} ترسل إلى لوحة محسومة، فيلعب الخصم حيث يشاء.","ls.ng.slow":"بعد {x} يصمد الخصم بـ {r}، ولا تصنع ثلاثًا في صف خلال {n} نقلات أخرى.","ls.ng.ok":"{x} ليست سيئة، لكن هنا نقلة أفضل.","ls.ng.ans":"الإجابة {m}.","ls.b_take.title":"اكسب لوحة صغيرة","ls.b_take.sub":"العلامة الثالثة","ls.b_take.intro":"<p>إن كانت علامتان لك في صف على لوحة صغيرة والخانة الثالثة فارغة، فاللعب فيها يكسب تلك اللوحة. ابحث عن صف كهذا في اللوحة التي يمكنك اللعب فيها (المضيئة).</p>","ls.b_take.goal":"العب الخانة التي تكسب لوحة صغيرة.","ls.b_take.hint":"في اللوحة المضيئة، ابحث عن صف فيه علامتان لك.","ls.b_take.why":"{m} تكسب اللوحة {b}!","ls.b_take.ex.t":"ثالثة الصف","ls.b_take.ex.b":"في اللوحة المضيئة صف فيه علامتان لك. الخانة الثالثة {m} تكسب اللوحة.","ls.b_block.title":"سدّ ثالثته","ls.b_block.sub":"دافع قبل أن تُؤخذ","ls.b_block.intro":"<p>إن كان لخصمك اثنتان في صف في اللوحة التي تلعب فيها، فسدّ الخانة الثالثة هو الدفاع الأساسي. وإلا كسبها حالما يُرسل إليها (أو تكون له نقلة حرة).</p>","ls.b_block.goal":"العب النقلة التي تدافع عن هذه اللوحة.","ls.b_block.hint":"في اللوحة المضيئة، أين علامتا الخصم في صف؟","ls.b_block.why":"{m} تسدّ خانته الثالثة. يذهب الخصم إلى اللوحة {t} ولا يستطيع كسب لوحة فورًا.","ls.b_block.ex.t":"سدّ الثالثة","ls.b_block.ex.b":"للخصم اثنتان في صف في اللوحة المضيئة. سدّ الخانة الثالثة {m} يحفظ اللوحة الآن.","ls.b_send.title":"اختر الوجهة","ls.b_send.sub":"لا تمنح شيئًا مجانًا","ls.b_send.intro":"<p>الخانة التي تلعبها تحدد لوحة خصمك التالية. إرساله إلى لوحة فيها اثنتان له في صف يجعله يكسبها. تحقق قبل اللعب أي لوحة آمنة.</p>","ls.b_send.goal":"العب نقلة لا تمنح الخصم أي لوحة صغيرة.","ls.b_send.hint":"اللوحات المضيئة بالأحمر فيها اثنتان في صف للخصم. أي خانة لا ترسله إليها؟","ls.b_send.why":"مع {m} يذهب الخصم إلى اللوحة {t} ولا يستطيع كسب لوحة فيها فورًا.","ls.b_send.ex.t":"تحقق من الوجهة","ls.b_send.ex.b":"النقلة الحمراء ترسل الخصم إلى لوحة فيها اثنتان له في صف فيكسبها. الخضراء {m} ترسله حيث لا يستطيع.","ls.b_big.title":"ثلاث في صف على اللوحة الكبيرة","ls.b_big.sub":"أنهِ المباراة","ls.b_big.intro":"<p>حين تكون لوحتان مكسوبتان لك في صف على اللوحة الكبيرة، فكسب الثالثة يكسب المباراة. قد تكسب عدة نقلات لوحة صغيرة، لكن الثالثة في ذلك الصف وحدها تفوز.</p>","ls.b_big.goal":"افز بالمباراة بهذه النقلة.","ls.b_big.hint":"اللوحة المنقطة تنقصها واحدة لصف ثلاثي على اللوحة الكبيرة. أي نقلة تكسبها؟","ls.b_big.why":"{m} تكسب اللوحة {b} — ثلاث في صف على اللوحة الكبيرة. فزت!","ls.b_big.ex.t":"ثالثة اللوحة الكبيرة","ls.b_big.ex.b":"اكسب اللوحة الثالثة من صف ثنائي على اللوحة الكبيرة (المنقطة) والمباراة لك. هذا ما تفعله {m}.","ls.s_look.title":"انظر قبل أن تأخذ","ls.s_look.sub":"فخ اللوحة المجانية","ls.s_look.intro":"<p>قد تكسب نقلةٌ لوحة صغيرة ومع ذلك ترسل الخصم إلى مكان جيد. تحقق إلى أين ترسل الخانة الكاسبة، واختر النقلة التي لا تمنح شيئًا.</p>","ls.s_look.goal":"العب أفضل نقلة (كسب لوحة ليس دائمًا هو الحل).","ls.s_look.hint":"اللوحات المضيئة بالأحمر فيها اثنتان في صف للخصم. إلى أين ترسله النقلة الكاسبة؟","ls.s_look.why":"مع {m} يذهب الخصم إلى اللوحة {t} ولا يستطيع كسب لوحة فورًا. هنا كانت الوجهة أهم من اللوحة التي أمامك.","ls.s_look.ex.t":"الأخذ يرسله","ls.s_look.ex.b":"النقلة الحمراء تكسب لوحة لكنها ترسل الخصم إلى لوحة فيها اثنتان له في صف. الصحيحة هي الخضراء {m} التي ترسله إلى مكان آمن.","ls.s_free.title":"استخدام النقلة الحرة","ls.s_free.sub":"اذهب حيث يهم","ls.s_free.intro":"<p>النقلة الحرة فرصة كبيرة. العب في اللوحة المهمة للوحة الكبيرة — التي تصنع صفًا ثلاثيًا لأي من الطرفين.</p>","ls.s_free.goal":"يمكنك اللعب في أي مكان. العب أهم نقلة.","ls.s_free.hint":"اللوحات المنقطة هي اللوحات المفتاحية للوحة الكبيرة. ماذا يمكنك أن تفعل هناك؟","ls.s_free.why":"{m} تذهب إلى اللوحة المفتاحية للوحة الكبيرة، اللوحة {b}.","ls.s_free.ex.t":"اختر اللوحة المفتاحية","ls.s_free.ex.b":"النقلة الحرة تتيح لك اختيار اللوحة المفتاحية للوحة الكبيرة (المنقطة). تلك النقلة هي {m}.","ls.s_force2.title":"الفوز في نقلتين","ls.s_force2.sub":"احسب الإرسال","ls.s_force2.intro":"<p>أرسل الخصم إلى لوحة تسمح فيها كل نقلة له لنقلتك التالية بإكمال ثلاث في صف على اللوحة الكبيرة. افحص كل خانة له وإلى أين ترسلك.</p>","ls.s_force2.goal":"اصنع ثلاثًا في صف على اللوحة الكبيرة في نقلتين.","ls.s_force2.hint":"ابحث عن لوحة ترسله إليها فتقود كل ردوده إلى فوزك.","ls.s_force2.why":"{m} هي النقلة الفائزة: أيًّا كان رده، تكمل نقلتك التالية الصف.","ls.s_force2.ex.t":"أرسل واكسب","ls.s_force2.ex.b":"بعد الخضراء {m} يرسلك كل رد للخصم إلى لوحة تفوز فيها.","ls.s_force3.title":"الفوز في ثلاث","ls.s_force3.sub":"الإجبار في النهاية","ls.s_force3.intro":"<p>في نهاية المباراة يحسم الإرسالُ النتيجة. ضيّق خيارات الخصم في كل نقلة واحسب الطريق إلى صف ثلاثي في 3 نقلات.</p>","ls.s_force3.goal":"اصنع ثلاثًا في صف على اللوحة الكبيرة في 3 نقلات.","ls.s_force3.hint":"افحص بالترتيب: النقلات التي تكسب لوحة، والتي لا تمنح شيئًا، والتي لا تعطي نقلة حرة.","ls.s_force3.why":"من {m} تفوز في 3 نقلات.","ls.s_force3.ex.t":"حساب 3 نقلات","ls.s_force3.ex.b":"من الخضراء {m} ردّ على كل رد بإعادته، وافز على اللوحة الكبيرة في 3.","pz.title":"ألغاز إكس أو المطلقة","pz.desc":"اصنع ثلاثًا في صف على اللوحة الكبيرة في العدد المحدد من النقلات. يدافع الخصم بأشد عناد. كل حل مُثبت بالمحرك.","pz.winIn":"الفوز في {n}","pz.goal":"دور {c}: ثلاث في صف على اللوحة الكبيرة في {n} نقلات","pz.start":"العب نقلتك الأولى.","pz.best":"كانت الإجابة {b}.","pz.solvedSub":"ثلاث في صف على اللوحة الكبيرة في {n} نقلات.","pz.hint1":"بقيت {n} نقلات. انظر ماذا يستطيع الخصم في اللوحة التي ترسله إليها.","pz.hintText":"تبدأ نقلة فائزة في اللوحة المنقطة.","pz.reply":"لعب الخصم {m}. بقيت {n} نقلات.","pz.retry":"إعادة","pz.grpWin":"الفوز في N","pz.grpWinSub":"اصنع ثلاثًا في صف على اللوحة الكبيرة في النقلات المحددة أمام أعند دفاع.","pz.grpTac":"مواضيع","pz.grpTacSub":"الفوز بالإرسال · الفوز من نقلة حرة. أخذ اللوحات وحده لا يحلها.","pz.th.w1":"الفوز في 1","pz.th.w1.sub":"من بين النقلات التي تكسب لوحة صغيرة، جد التي تكسب المباراة.","pz.th.w2":"الفوز في 2","pz.th.w2.sub":"اقرأ رده وأكمل الصف بنقلتك الثانية.","pz.th.w3":"الفوز في 3","pz.th.w3.sub":"احسب دفاعه وافز في 3 نقلات.","pz.th.w4":"الفوز في 4","pz.th.w4.sub":"إرسال متبادل طويل: ضيّق خياراته وحاصره.","pz.th.send":"الفوز بالإرسال","pz.th.send.sub":"النقلة الأولى لا تكسب لوحة: الوجهة التي ترسل إليها الخصم تحسم المباراة.","pz.th.free":"الفوز من نقلة حرة","pz.th.free.sub":"يمكنك اللعب في أي مكان — اختر النقلة التي تقود إلى الفوز.","pz.why.last":"{m} لم تصنع ثلاثًا في صف على اللوحة الكبيرة.","pz.why.took":"كسب الخصم اللوحة {b} بـ {r} وأرسلك إلى اللوحة {t}. لا فوز في {n} نقلات أخرى.","pz.why.far":"صمد الخصم بـ {r} وأرسلك إلى اللوحة {t}. لا صف ثلاثي في {n} نقلات أخرى.","pz.why.answer":"اضغط «الإجابة» لرؤية الحل.","rv.note":"خطأ = نقلة قلبت فوزًا أو تعادلًا أو خسرت كثيرًا. مشكوك فيها = خسارة واضحة. الأرقام على اللوحة قيمة اللعب في كل خانة.","cr.forced":"الخانة الوحيدة الممكنة.","cr.first":"النقلة الأولى. كانت <b>{b}</b> بداية أفضل قليلًا.","cr.firstOk":"النقلة الأولى — بداية جيدة.","cr.won":"النقلة الفائزة: ثلاث في صف على اللوحة الكبيرة.","cr.best":"أفضل نقلة.","cr.bestTake":"أفضل نقلة — كسبت اللوحة {t}.","cr.good":"ليست سيئة (الأفضل كانت <b>{b}</b>، أفضل بقليل).","cr.gen":"أضعفت هذه النقلة الموقف ({d}). الأفضل كانت <b>{b}</b>.","cr.missWin":"فاتك الفوز: <b>{b}</b> كانت تصنع ثلاثًا في صف على اللوحة الكبيرة.","cr.allowWin":"بعد هذا يفوز الخصم بـ {r}، ثلاث في صف على اللوحة الكبيرة. <b>{b}</b> كانت تمنع ذلك.","cr.gift":"أرسلت هذه النقلة الخصم إلى اللوحة {t}، حيث تمنحه {r} اللوحة {tb}. <b>{b}</b> لم تكن تمنح شيئًا.","cr.free":"أرسلت هذه النقلة إلى لوحة محسومة، فلعب الخصم حيث شاء. <b>{b}</b> كانت تحبسه في لوحة واحدة.","cr.missTake":"فاتك كسب اللوحة {tb}. الأفضل كانت <b>{b}</b>.","cr.tookBad":"كسبت لوحة، لكن الوجهة التي أُرسل إليها الخصم ساعدته. الأفضل كانت <b>{b}</b>.","cr.tip.take":"💡 اللوحات التي يمكنك كسبها مهمة — لكن الخانة الكاسبة تحدد إلى أين يذهب الخصم.","cr.tip.send":"💡 قبل اللعب، ابحث عن اثنتين في صف للخصم في اللوحة التي ترسله إليها.","cr.tip.free":"💡 الإرسال إلى لوحة محسومة يترك الخصم يختار أهم لوحة.","cr.tip.look":"💡 تحقق إلى أين ترسل نقلة الأخذ. أحيانًا تهم اللوحة الكبيرة أكثر من الصغيرة.","cr.tip.gen":"💡 السهم على اللوحة هو أفضل نقلة؛ والأرقام قيمة اللعب في كل خانة."}});
